INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fdf5b41-d838-4c3a-8866-9ce89ac30990', '荅趙子', '荅趙子', '0158a178-19c3-4993-8301-c9c72cb27d8f', '唐', '["綠慘雙蛾不自持，只緣幽恨在新詩。","郎心應似琴心怨，脈脈春情更泥誰。"]', '["綠慘雙蛾不自持，只緣幽恨在新诗。","郎心應似琴心怨，脈脈春情更泥誰。"]', '诗', 'shi', '', NULL, '荅趙子 步非煙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('661ebc1b-808b-418f-955d-204d5ca66807', '又荅趙象獨坐', '又荅趙象独坐', '0158a178-19c3-4993-8301-c9c72cb27d8f', '唐', '["無力嚴妝倚繡櫳，暗題蟬錦思難窮。","近來贏得傷春病，柳弱花敧怯曉風。"]', '["無力嚴妝倚繡櫳，暗題蟬錦思难窮。","近来贏得傷春病，柳弱花敧怯晓风。"]', '诗', 'shi', '', NULL, '又荅趙象獨坐 步非煙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d427c8bb-101f-4974-984b-a1b920df8480', '寄懷', '寄懷', '0158a178-19c3-4993-8301-c9c72cb27d8f', '唐', '["畫簷春燕須同宿，蘭浦雙鴛肯獨飛。","長恨桃源諸女伴，等閑花裏送郎歸。"]', '["畫簷春燕須同宿，蘭浦雙鴛肯独飞。","长恨桃源諸女伴，等闲花裏送郎归。"]', '诗', 'shi', '', NULL, '寄懷 步非煙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('939d8171-0196-4fb4-9eb5-faa10768dce0', '荅趙象', '荅趙象', '0158a178-19c3-4993-8301-c9c72cb27d8f', '唐', '["相思只恨難相見，相見還愁却別君。","願得化爲松上鶴，一雙飛去入行雲。"]', '["相思只恨难相见，相见還愁却別君。","願得化爲松上鹤，一雙飞去入行云。"]', '诗', 'shi', '', NULL, '荅趙象 步非煙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5552adc-0429-470b-a7a3-45d70100bd97', '臨行獻李尚書', '臨行獻李尚书', 'adc9f099-08ea-44e1-b37e-2af4eff485f2', '唐', '["從來學製斐然詩，不料霜臺御史知。","忽見便教隨命去，戀恩腸斷出門時。"]', '["從来学製斐然诗，不料霜台御史知。","忽见便教隨命去，戀恩腸斷出门时。"]', '诗', 'shi', '', NULL, '臨行獻李尚書 崔紫雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6def4d8-1454-4dbc-81d2-cc36cbe54c25', '怨詩效徐淑體', '怨诗效徐淑體', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["妾生兮不辰，盛年兮逢屯。","寒暑兮心結，夙夜兮眉顰。","循環兮不息，如彼兮車輪。","車輪兮可歇，妾心兮焉伸。","雜沓兮無緒，如彼兮絲棼。","絲棼兮可理，妾心兮焉分。","空閨兮岑寂，妝閣兮生塵。","萱草兮徒樹，茲憂兮豈泯。","幸逢兮君子，許結兮殷勤。","分香兮翦髮，贈玉兮共珍。","指天兮結誓，願爲兮一身。","所遭兮多舛，玉體兮難親。","損餐兮減寢，帶緩兮羅裙。","菱鑑兮慵啓，博鑪兮焉熏。","整襪兮欲舉，塞路兮荆榛。","逢人兮欲語，鞈匝兮頑嚚。","煩冤兮憑胸，何時兮可論。","願君兮見察，妾死兮何瞋。"]', '["妾生兮不辰，盛年兮逢屯。","寒暑兮心結，夙夜兮眉顰。","循环兮不息，如彼兮车輪。","车輪兮可歇，妾心兮焉伸。","杂沓兮無緒，如彼兮絲棼。","絲棼兮可理，妾心兮焉分。","空閨兮岑寂，妝閣兮生塵。","萱草兮徒樹，茲憂兮豈泯。","幸逢兮君子，許結兮殷勤。","分香兮翦髮，贈玉兮共珍。","指天兮結誓，願爲兮一身。","所遭兮多舛，玉體兮难親。","損餐兮減寢，带緩兮羅裙。","菱鑑兮慵啓，博鑪兮焉熏。","整襪兮欲舉，塞路兮荆榛。","逢人兮欲語，鞈匝兮頑嚚。","煩冤兮憑胸，何时兮可論。","願君兮见察，妾死兮何瞋。"]', '诗', 'shi', '', NULL, '怨詩效徐淑體 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6ce334f-8962-4a1e-af61-2abc7ebf27e4', '製履贈楊達', '製履贈楊達', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["金刀翦紫羢，與郎作輕履。","願化雙仙鳧，飛來入閨裏。"]', '["金刀翦紫羢，與郎作轻履。","願化雙仙鳧，飞来入閨裏。"]', '诗', 'shi', '', NULL, '製履贈楊達 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1294222-3a2c-4827-b4e1-0fa0b4a6571a', '有期不至', '有期不至', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["銀燭清尊久延佇，出門入門天欲曙。","月落星稀竟不來，煙柳朧朣鵲飛去。"]', '["銀燭清尊久延佇，出门入门天欲曙。","月落星稀竟不来，煙柳朧朣鵲飞去。"]', '诗', 'shi', '', NULL, '有期不至 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('564dbde0-e6ed-4e73-b800-719862aa9011', '怨詩寄楊達 一', '怨诗寄楊達 一', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["春水悠悠春草綠，對此思君淚相續。","羞將離恨向東風，理盡秦箏不成曲。"]', '["春水悠悠春草綠，对此思君泪相續。","羞將離恨向东风，理尽秦箏不成曲。"]', '诗', 'shi', '', NULL, '怨詩寄楊達 一 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c444dd3d-0512-41a5-b1bb-96f6e84eccab', '怨詩寄楊達 二', '怨诗寄楊達 二', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["與君形影分吳越，玉枕經年對離別。","登臺北望煙雨深，回身泣向寥天月。"]', '["與君形影分吳越，玉枕經年对離別。","登台北望煙雨深，回身泣向寥天月。"]', '诗', 'shi', '', NULL, '怨詩寄楊達 二 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1621b0d9-b848-4127-bb11-a003297f475a', '楚妃怨', '楚妃怨', 'ca2cb78f-404b-4531-a90e-2c1e59774c1e', '唐', '["梧桐葉下黃金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀瓶秋水冷。"]', '["梧桐葉下黄金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀瓶秋水冷。"]', '诗', 'shi', '', NULL, '楚妃怨 姚月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84896f78-dbd0-46e1-a52b-f7170773fd3b', '獨遊家園', '独游家园', 'a4f740de-e4cd-4543-952b-7899dc3f8f86', '唐', '["可惜春時節，依前獨自遊。","無端兩行淚，長只對花流。"]', '["可惜春时節，依前独自游。","無端兩行泪，长只对花流。"]', '诗', 'shi', '', NULL, '獨遊家園 孟氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf51fd3-bc36-4bac-9c61-b200cba4fd88', '荅少年', '荅少年', 'a4f740de-e4cd-4543-952b-7899dc3f8f86', '唐', '["誰家少年兒，心中暗自欺。","不道終不可，可即恐郎知。"]', '["誰家少年兒，心中暗自欺。","不道終不可，可即恐郎知。"]', '诗', 'shi', '', NULL, '荅少年 孟氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('632e2169-cc1f-4863-9f98-c1a128f6c138', '寄情', '寄情', '64251310-8668-4310-8471-4b7c18feab72', '唐', '["春風白馬紫絲韁，正值蠶娘未採桑。","五夜有心隨暮雨，百年無節抱秋霜。","重尋繡帶朱藤合，却忍羅裙碧草長。","爲報西遊減離恨，阮郎纔去嫁劉郎。"]', '["春风白马紫絲韁，正值蠶娘未採桑。","五夜有心隨暮雨，百年無節抱秋霜。","重尋繡带朱藤合，却忍羅裙碧草长。","爲報西游減離恨，阮郎纔去嫁劉郎。"]', '诗', 'shi', '', NULL, '寄情 趙氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f0750ec-0fd5-4a06-bbd3-9f60a31d6748', '書紅綃帕 一', '书紅綃帕 一', '3bbd33b5-0f99-4a8f-9d81-f5c41baf2e30', '唐', '["囊裹真香誰見竊，鮫綃滴淚染成紅。","殷勤遺下輕綃意，好與情郎懷袖中。"]', '["囊裹真香誰见竊，鮫綃滴泪染成紅。","殷勤遺下轻綃意，好與情郎懷袖中。"]', '诗', 'shi', '', NULL, '書紅綃帕 一 李節度姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8076177-1331-45f7-a771-fbf8f6987a71', '書紅綃帕 二', '书紅綃帕 二', '3bbd33b5-0f99-4a8f-9d81-f5c41baf2e30', '唐', '["金珠富貴吾家事，常渴佳期乃寂寥。","偶用志誠求雅合，良媒未必勝紅綃。"]', '["金珠富貴吾家事，常渴佳期乃寂寥。","偶用志誠求雅合，良媒未必勝紅綃。"]', '诗', 'shi', '', NULL, '書紅綃帕 二 李節度姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039b706f-19ca-45b0-a622-fa8049f1895e', '會張生述懷', '會張生述懷', '3bbd33b5-0f99-4a8f-9d81-f5c41baf2e30', '唐', '["門前畫戟尋常設，堂上犀簪取次看。","最是惱人情緒處，鳳皇樓上月華寒。"]', '["门前畫戟尋常設，堂上犀簪取次看。","最是惱人情緒处，鳳皇楼上月华寒。"]', '诗', 'shi', '', NULL, '會張生述懷 李節度姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f349de32-aed1-4e1d-8ef3-b62508aa1df2', '別韋洵美詩', '別韋洵美诗', '9bd07b29-6b69-4b01-937a-859501ce645b', '唐', '["妾閉閑房君路岐，妾心君恨兩依依。","神魂倘遇巫娥伴，猶逐朝雲暮雨歸。"]', '["妾閉闲房君路岐，妾心君恨兩依依。","神魂倘遇巫娥伴，猶逐朝云暮雨归。"]', '诗', 'shi', '', NULL, '別韋洵美詩 崔素娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b0a781a-b0e6-4fb2-9f68-74d97725152e', '送韋生酒', '送韋生酒', '052fee33-6dba-46ed-812c-c0702b25d33a', '唐', '["白露溼庭砌，皓月臨前軒。","此時去留恨，含思獨無言。"]', '["白露溼庭砌，皓月臨前軒。","此时去留恨，含思独無言。"]', '诗', 'shi', '', NULL, '送韋生酒 鮑家四弦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('348d83bb-ab8d-420b-bbbc-6e7fbaf9ea04', '送鮑生酒', '送鲍生酒', '052fee33-6dba-46ed-812c-c0702b25d33a', '唐', '["風颭荷珠難暫圓，多情信有短姻緣。","西樓今夜三更月，還照離人泣斷弦。"]', '["风颭荷珠难暫圓，多情信有短姻緣。","西楼今夜三更月，還照離人泣斷弦。"]', '诗', 'shi', '', NULL, '送鮑生酒 鮑家四弦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f43e36e-87d8-47e2-a45e-ddf115e77c37', '贈別', '贈別', '40d0cb01-aca2-485a-9da8-9e8c4eab2815', '唐', '["風柳搖搖無定枝，陽臺雲雨夢中歸。","他年蓬島音塵絕，留取尊前舊舞衣。"]', '["风柳搖搖無定枝，陽台云雨梦中归。","他年蓬島音塵絕，留取尊前旧舞衣。"]', '诗', 'shi', '', NULL, '贈別 [嚴]續姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f445666-231e-415d-8e86-7f9f7ef1b621', '採桑', '採桑', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["春來南鴈歸，日去西蠶遠。","妾思粉何極，客遊殊未返。"]', '["春来南鴈归，日去西蠶远。","妾思粉何極，客游殊未返。"]', '诗', 'shi', '', NULL, '採桑 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67710f4c-2d97-4ce1-8b4d-aa983d74b963', '宛轉歌二首 一', '宛轉歌二首 一', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["風已清，月朗琴復鳴。","掩抑非千態，殷勤是一聲。","歌宛轉，宛轉和且長。","願爲雙鴻鵠，比翼共翺翔。"]', '["风已清，月朗琴复鳴。","掩抑非千態，殷勤是一声。","歌宛轉，宛轉和且长。","願爲雙鴻鵠，比翼共翺翔。"]', '诗', 'shi', '', NULL, '宛轉歌二首 一 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e585dee0-0fc8-4b06-86b9-7531598d5d4f', '宛轉歌二首 二', '宛轉歌二首 二', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["日已暮，長簷鳥聲度。","此時望君君不來，此時思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '["日已暮，长簷鸟声度。","此时望君君不来，此时思君君不顧。","歌宛轉，宛轉那能異棲宿。","願爲形與影，出入恆相逐。"]', '诗', 'shi', '', NULL, '宛轉歌二首 二 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b704e7-b568-4c5c-a17c-2f16efcf67b3', '長相思', '长相思', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["長相思，久離別。","關山阻，風煙絕。","臺上鏡文銷，袖中書字滅。","不見君形影，何曾有歡悅。"]', '["长相思，久離別。","关山阻，风煙絕。","台上镜文銷，袖中书字滅。","不见君形影，何曾有歡悅。"]', '诗', 'shi', '', NULL, '長相思 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e46a7b6-1e3a-4a44-a4c1-a44687af1022', '朝雲引', '朝云引', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["巴西巫峽指巴東，朝雲觸石上朝空。","巫山巫峽高何已，行雨行雲一時起。","一時起，三春暮。","若言來，且就陽臺路。"]', '["巴西巫峽指巴东，朝云觸石上朝空。","巫山巫峽高何已，行雨行云一时起。","一时起，三春暮。","若言来，且就陽台路。"]', '诗', 'shi', '', NULL, '朝雲引 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7607e42-9b69-40e6-b963-6e02393010bc', '宿巫山寄遠人', '宿巫山寄远人', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["巫山雲，巫山雨，朝雲暮雨無定所。","南峰忽暗北峰晴，空裏仙人語笑聲。","曾侍荆王枕席處，直至如今如有靈。","春風澹澹白雲閑，驚湍流水響千山。","一夜此中對明月，憶得此中與君別。","感物情懷如舊時，君今渺渺在天涯。","曉看襟上淚流處，點點血痕猶在衣。"]', '["巫山云，巫山雨，朝云暮雨無定所。","南峰忽暗北峰晴，空裏仙人語笑声。","曾侍荆王枕席处，直至如今如有靈。","春风澹澹白云闲，驚湍流水响千山。","一夜此中对明月，憶得此中與君別。","感物情懷如旧时，君今渺渺在天涯。","晓看襟上泪流处，点点血痕猶在衣。"]', '诗', 'shi', '', NULL, '宿巫山寄遠人 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e04bafcb-6d5c-4b40-83c1-67dfa8fe205c', '昭君怨', '昭君怨', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["自古無和親，貽災到妾身。","朔風嘶去馬，漢月出行輪。","衣薄狼山雪，妝成虜塞春。","迴看父母國，生死畢胡塵。"]', '["自古無和親，貽災到妾身。","朔风嘶去马，漢月出行輪。","衣薄狼山雪，妝成虜塞春。","迴看父母国，生死畢胡塵。"]', '诗', 'shi', '', NULL, '昭君怨 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14aaf7ac-4e70-4ce6-b3c1-4fd0594f2844', '銅雀臺', '銅雀台', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["歌扇向陵開，齊行奠玉杯。","舞時飛燕列，夢裏片雲來。","月色空餘恨，松聲莫更哀。","誰憐未死妾，掩袂下銅臺。"]', '["歌扇向陵开，齊行奠玉杯。","舞时飞燕列，梦裏片云来。","月色空餘恨，松声莫更哀。","誰怜未死妾，掩袂下銅台。"]', '诗', 'shi', '', NULL, '銅雀臺 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20348cf3-482b-4139-ac8d-cb71ecd3fe29', '遠意', '远意', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["脉脉長攄氣，微微不離心。","叩頭從此去，煩惱阿誰禁。"]', '["脉脉长攄氣，微微不離心。","叩头從此去，煩惱阿誰禁。"]', '诗', 'shi', '', NULL, '遠意 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ecb7481-6658-45ad-af00-4b0817d856b7', '句', '句', 'f5ff52f6-ede8-48c8-aeb2-e388f07eba25', '唐', '["玉枕空流別後淚，羅衣已盡去時香。"]', '["玉枕空流別後泪，羅衣已尽去时香。"]', '诗', 'shi', '', NULL, '句 梁瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('022554eb-12fc-47cb-882e-522994b100b1', '有所思', '有所思', 'ad274d6c-9901-4a2f-8e3a-4e56d992fec0', '唐', '["朝亦有所思，暮亦有所思。","登樓望君處，藹藹蕭關道。","掩淚向浮雲，誰知妾懷抱。","玉井蒼苔春院深，桐花落盡無人埽。"]', '["朝亦有所思，暮亦有所思。","登楼望君处，藹藹蕭关道。","掩泪向浮云，誰知妾懷抱。","玉井蒼苔春院深，桐花落尽無人埽。"]', '诗', 'shi', '', NULL, '有所思 劉雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58977f8f-2c1b-4aa8-b6d6-6da8742d923a', '婕妤怨', '婕妤怨', 'ad274d6c-9901-4a2f-8e3a-4e56d992fec0', '唐', '["君恩不可見，妾豈如秋扇。","秋扇尚有時，妾身永微賤。","莫言朝花不復落，嬌容幾奪昭陽殿。"]', '["君恩不可见，妾豈如秋扇。","秋扇尚有时，妾身永微賤。","莫言朝花不复落，嬌容幾奪昭陽殿。"]', '诗', 'shi', '', NULL, '婕妤怨 劉雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6613ee43-6bdb-45eb-9b35-3c2ba5400fd7', '望月', '望月', 'ad274d6c-9901-4a2f-8e3a-4e56d992fec0', '唐', '["天漢涼秋夜，澄澄一鏡明。","山空猨屢嘯，林靜鵲頻驚。"]', '["天漢涼秋夜，澄澄一镜明。","山空猨屢嘯，林静鵲頻驚。"]', '诗', 'shi', '', NULL, '望月 劉雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a287784-fd73-4e42-8204-45f245be1b09', '古意', '古意', 'b2302f75-e91a-44c0-8ce5-932a14aca702', '唐', '["灼灼葉中花，夏萎春又芳。","明明天上月，蟾缺圓復光。","未如君子情，朝違夕已忘。","玉帳枕猶暖，紈扇思何長。","願因西南風，吹上玳瑁牀。","嬌眠錦衾裏，展轉雙鴛鴦。"]', '["灼灼葉中花，夏萎春又芳。","明明天上月，蟾缺圓复光。","未如君子情，朝違夕已忘。","玉帳枕猶暖，紈扇思何长。","願因西南风，吹上玳瑁牀。","嬌眠錦衾裏，展轉雙鴛鴦。"]', '诗', 'shi', '', NULL, '古意 崔萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f81228e-9ff6-4963-97a9-886011eddae0', '敘別', '敘別', 'b2302f75-e91a-44c0-8ce5-932a14aca702', '唐', '["碧池漾漾春水綠，中有佳禽暮棲宿。","願持此意永相貽，祗慮君情中反覆。"]', '["碧池漾漾春水綠，中有佳禽暮棲宿。","願持此意永相貽，祗慮君情中反覆。"]', '诗', 'shi', '', NULL, '敘別 崔萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df18d30-ba0e-477a-9cac-b0bc87005307', '豪家子', '豪家子', 'b2302f75-e91a-44c0-8ce5-932a14aca702', '唐', '["年少家藏累代金，紅樓盡日醉沈沈。","馬非躞蹀寧酬價，人不嬋娟肯動心。"]', '["年少家藏累代金，紅楼尽日醉沈沈。","马非躞蹀寧酬價，人不嬋娟肯动心。"]', '诗', 'shi', '', NULL, '豪家子 崔萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253445ea-863a-4807-80c4-c280e4ac96e4', '句', '句', 'b2302f75-e91a-44c0-8ce5-932a14aca702', '唐', '["豈知一隻鳳釵價，沽得數村蝸舍人。"]', '["豈知一隻鳳釵價，沽得數村蝸舍人。"]', '诗', 'shi', '', NULL, '句 崔萱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e2dc532-9d81-43c0-ad23-e222570b599c', '贈所思', '贈所思', '0f5845f8-e5b4-4acb-96e5-494fb6190783', '唐', '["所居幸接隣，相見不相親。","一似雲間月，何殊鏡裏人。","丹誠空有夢，腸斷不禁春。","願作梁間燕，無由變此身。"]', '["所居幸接隣，相见不相親。","一似云间月，何殊镜裏人。","丹誠空有梦，腸斷不禁春。","願作梁间燕，無由变此身。"]', '诗', 'shi', '', NULL, '贈所思 崔仲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c7644e-06d3-4446-96ef-7c560ee9d785', '戲贈', '戲贈', '0f5845f8-e5b4-4acb-96e5-494fb6190783', '唐', '["暫到崑崙未得歸，阮郎何事教人非。","如今身佩上清籙，莫遣落花霑羽衣。"]', '["暫到崑崙未得归，阮郎何事教人非。","如今身佩上清籙，莫遣落花霑羽衣。"]', '诗', 'shi', '', NULL, '戲贈 崔仲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e3e0148-8399-4005-a0af-d3248343a9c8', '贈歌姬', '贈歌姬', '0f5845f8-e5b4-4acb-96e5-494fb6190783', '唐', '["水翦雙眸霧翦衣，當筵一曲媚春輝。","瀟湘夜瑟怨猶在，巫峽曉雲愁不稀。","皓齒乍分寒玉細，黛眉輕蹙遠山微。","渭城朝雨休重唱，滿眼陽關客未歸。"]', '["水翦雙眸霧翦衣，當筵一曲媚春輝。","瀟湘夜瑟怨猶在，巫峽晓云愁不稀。","皓齒乍分寒玉細，黛眉轻蹙远山微。","渭城朝雨休重唱，满眼陽关客未归。"]', '诗', 'shi', '', NULL, '贈歌姬 崔仲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c8a4ae5-8871-4227-ac2e-350b29222c34', '句', '句', '0f5845f8-e5b4-4acb-96e5-494fb6190783', '唐', '["妾心合君心，一似影隨形。","梁燕無情困，雙棲語此時。","不覺紅顏去，空嗟白髮生。","桐花落盡春又盡，紫塞征人猶未歸。"]', '["妾心合君心，一似影隨形。","梁燕無情困，雙棲語此时。","不覺紅顏去，空嗟白髮生。","桐花落尽春又尽，紫塞征人猶未归。"]', '诗', 'shi', '', NULL, '句 崔仲容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a3eaf7-155e-4e0b-b601-776f35aea623', '獨夜詞', '独夜词', 'f4c2a543-ef98-46a3-8c05-76124d5d9046', '唐', '["晴天霜落寒風急，錦帳羅幃羞更入。","秦箏不復續斷弦，回身掩淚挑燈立。"]', '["晴天霜落寒风急，錦帳羅幃羞更入。","秦箏不复續斷弦，回身掩泪挑灯立。"]', '诗', 'shi', '', NULL, '獨夜詞 崔公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c75e95b1-23b1-4b83-b595-671bd6fb55d9', '句', '句', 'f4c2a543-ef98-46a3-8c05-76124d5d9046', '唐', '["看花獨不語，裴回雙淚澘。","君今遠戍在何處，遣妾秋來長望天。"]', '["看花独不語，裴回雙泪澘。","君今远戍在何处，遣妾秋来长望天。"]', '诗', 'shi', '', NULL, '句 崔公遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ddb055c-d9e1-48c6-8f85-b050b76fed21', '春詞二首 一', '春词二首 一', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["垂柳鳴黃鸝，關關若求友。","春情不可耐，愁殺閨中婦。","日暮登高樓，誰憐小垂手。"]', '["垂柳鳴黄鸝，关关若求友。","春情不可耐，愁殺閨中婦。","日暮登高楼，誰怜小垂手。"]', '诗', 'shi', '', NULL, '春詞二首 一 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b52f305-e197-4c72-a5a6-3087de41607d', '春詞二首 二', '春词二首 二', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["昨日桃花飛，今朝梨花吐。","春色能幾時，那堪此愁緒。","蕩子遊不歸，春來淚如雨。"]', '["昨日桃花飞，今朝梨花吐。","春色能幾时，那堪此愁緒。","蕩子游不归，春来泪如雨。"]', '诗', 'shi', '', NULL, '春詞二首 二 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70e737a7-547d-4d01-8280-03a4b2d374e9', '銅雀臺', '銅雀台', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["君王冥漠不可見，銅雀歌舞空裴回。","西陵嘖嘖悲宿鳥，高殿沈沈閉青苔。","青苔無人跡，紅粉空自哀。"]', '["君王冥漠不可见，銅雀歌舞空裴回。","西陵嘖嘖悲宿鸟，高殿沈沈閉青苔。","青苔無人跡，紅粉空自哀。"]', '诗', 'shi', '', NULL, '銅雀臺 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7bfbd7-17d6-4a8f-a738-6d1278d2bc94', '句', '句', '6b4ad935-0287-43c8-8cbf-327309f402eb', '唐', '["年年人自老，日日水東流。","庭芳自搖落，永念結中腸。"]', '["年年人自老，日日水东流。","庭芳自搖落，永念結中腸。"]', '诗', 'shi', '', NULL, '句 張琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245ce2db-d956-4851-a514-faa5a56bad89', '哭夫二首 一', '哭夫二首 一', '50df3464-4165-4277-b9ee-4af80afffe83', '唐', '["風卷平沙日欲曛，狼煙遙認犬羊羣。","李陵一戰無歸日，望斷胡天哭塞雲。"]', '["风卷平沙日欲曛，狼煙遙認犬羊羣。","李陵一戰無归日，望斷胡天哭塞云。"]', '诗', 'shi', '', NULL, '哭夫二首 一 裴羽仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19d0cc5c-d597-4a67-a87c-24437cfd4a78', '哭夫二首 二', '哭夫二首 二', '50df3464-4165-4277-b9ee-4af80afffe83', '唐', '["良人平昔逐蕃渾，力戰輕行出塞門。","從此不歸成萬古，空留賤妾怨黃昏。"]', '["良人平昔逐蕃渾，力戰轻行出塞门。","從此不归成万古，空留賤妾怨黄昏。"]', '诗', 'shi', '', NULL, '哭夫二首 二 裴羽仙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eefaeb9a-a9a2-4c8d-96ac-4d49dcb5bda4', '長門怨 一', '长门怨 一', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["雨滴梧桐秋夜長，愁心和雨到昭陽。","淚痕不學君恩斷，拭却千行更萬行。"]', '["雨滴梧桐秋夜长，愁心和雨到昭陽。","泪痕不学君恩斷，拭却千行更万行。"]', '诗', 'shi', '', NULL, '長門怨 一 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41047ebd-0b03-47ca-8ea8-1b7a9d2d9358', '長門怨 二', '长门怨 二', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["學畫蛾眉獨出羣，當時人道便承恩。","經年不見君王面，花落黃昏空掩門。"]', '["学畫蛾眉独出羣，當时人道便承恩。","經年不见君王面，花落黄昏空掩门。"]', '诗', 'shi', '', NULL, '長門怨 二 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10048cdb-c87c-4f88-8286-a4fca4960105', '送遠', '送远', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["聞道瞿塘灩澦堆，青山流水近陽臺。","知君此去無還日，妾亦隨波不復迴。"]', '["闻道瞿塘灩澦堆，青山流水近陽台。","知君此去無還日，妾亦隨波不复迴。"]', '诗', 'shi', '', NULL, '送遠 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b58412-a066-4c0c-b4d9-2e9f2a9e080c', '句', '句', '9971ed19-a203-46a6-a4b3-8886557c7ace', '唐', '["春風報梅柳，一夜發南枝。","傍人那得知心事，一面殘妝空淚痕。"]', '["春风報梅柳，一夜發南枝。","傍人那得知心事，一面殘妝空泪痕。"]', '诗', 'shi', '', NULL, '句 劉媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653cf90b-8503-48b6-8ec2-aa75ae6b16cf', '懷良人', '懷良人', '3b9ff774-2322-4af4-8e86-5ef3bda576e2', '唐', '["蓬鬢荆釵世所稀，布裙猶是嫁時衣。","胡麻好種無人種，正是歸時不見歸。"]', '["蓬鬢荆釵世所稀，布裙猶是嫁时衣。","胡麻好種無人種，正是归时不见归。"]', '诗', 'shi', '', NULL, '懷良人 葛鵶兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a22d583-2fd0-44d0-a399-e798fd738936', '會仙詩 一', '會仙诗 一', '3b9ff774-2322-4af4-8e86-5ef3bda576e2', '唐', '["彩鳳搖搖下翠微，煙光漠漠徧芳枝。","玉窗仙會何人見，唯有春風仔細知。"]', '["彩鳳搖搖下翠微，煙光漠漠徧芳枝。","玉窗仙會何人见，唯有春风仔細知。"]', '诗', 'shi', '', NULL, '會仙詩 一 葛鵶兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcac029e-2cce-449b-a39d-1264307f8e34', '會仙詩 二', '會仙诗 二', '3b9ff774-2322-4af4-8e86-5ef3bda576e2', '唐', '["煙霞迤邐接蓬萊，宮殿參差曉日開。","羣玉山前人別處，紫鸞飛起望仙臺。"]', '["煙霞迤邐接蓬萊，宮殿參差晓日开。","羣玉山前人別处，紫鸾飞起望仙台。"]', '诗', 'shi', '', NULL, '會仙詩 二 葛鵶兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d5ac7b-8c72-4d84-a819-b732fef697cd', '暗別離', '暗別離', '3f9c7f60-f624-43cf-b964-781beb356fa9', '唐', '["槐花結子桐葉焦，單飛越鳥啼青霄。","翠軒輾雲輕遙遙，燕脂淚迸紅線條。","瑤草歇芳心耿耿，玉佩無聲畫屏冷。","朱弦暗斷不見人，風動花枝月中影。","青鸞脉脉西飛去，海闊天高不知處。"]', '["槐花結子桐葉焦，單飞越鸟啼青霄。","翠軒輾云轻遙遙，燕脂泪迸紅線條。","瑤草歇芳心耿耿，玉佩無声畫屏冷。","朱弦暗斷不见人，风动花枝月中影。","青鸾脉脉西飞去，海闊天高不知处。"]', '诗', 'shi', '', NULL, '暗別離 劉瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05042944-c6de-4a97-b22f-32965fbb0774', '古意曲', '古意曲', '3f9c7f60-f624-43cf-b964-781beb356fa9', '唐', '["梧桐階下月團團，洞房如水秋夜闌。","吳刀翦破機頭錦，茱萸花墜相思枕。","綠窗寂寞背燈時，暗數寒更不成寢。"]', '["梧桐階下月團團，洞房如水秋夜闌。","吳刀翦破機头錦，茱萸花墜相思枕。","綠窗寂寞背灯时，暗數寒更不成寢。"]', '诗', 'shi', '', NULL, '古意曲 劉瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d45f6b65-1141-41ac-9666-31b4735f19bb', '闔閭城懷古', '闔閭城懷古', '3f9c7f60-f624-43cf-b964-781beb356fa9', '唐', '["五湖春水接遙天，國破君亡不記年。","唯有妖娥曾舞處，古臺寂寞起愁煙。"]', '["五湖春水接遙天，国破君亡不記年。","唯有妖娥曾舞处，古台寂寞起愁煙。"]', '诗', 'shi', '', NULL, '闔閭城懷古 劉瑤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dca98db5-1fdc-47d1-a17c-45a52aa94b83', '峽中即事', '峽中即事', '97106695-30c3-474a-8888-4fec3d7f7930', '唐', '["清秋三峽此中去，鳴鳥孤猨不可聞。","一道水聲多亂石，四時天色少晴雲。","日暮泛舟溪漵口，那堪夜永思氛氳。"]', '["清秋三峽此中去，鳴鸟孤猨不可闻。","一道水声多亂石，四时天色少晴云。","日暮泛舟溪漵口，那堪夜永思氛氳。"]', '诗', 'shi', '', NULL, '峽中即事 廉氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb4c966-5e88-4788-8764-4181d8a30ffa', '懷遠', '懷远', '97106695-30c3-474a-8888-4fec3d7f7930', '唐', '["隟塵何微微，朝夕通其輝。","人生各有託，君去獨不歸。","青林有蟬響，赤日無鳥飛。","裴回東南望，雙淚空霑衣。"]', '["隟塵何微微，朝夕通其輝。","人生各有託，君去独不归。","青林有蟬响，赤日無鸟飞。","裴回东南望，雙泪空霑衣。"]', '诗', 'shi', '', NULL, '懷遠 廉氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5849d3ad-78b6-4993-8282-6fc8a82c09e0', '寄征人', '寄征人', '97106695-30c3-474a-8888-4fec3d7f7930', '唐', '["淒淒北風吹鴛被，娟娟西月生蛾眉。","誰知獨夜相思處，淚滴寒塘蕙草時。"]', '["淒淒北风吹鴛被，娟娟西月生蛾眉。","誰知独夜相思处，泪滴寒塘蕙草时。"]', '诗', 'shi', '', NULL, '寄征人 廉氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9820b8b8-cd3f-4f5a-8c00-44a17c5e7327', '寄遠', '寄远', 'c3eab4f9-1607-4725-922e-a095f7c3b5ee', '唐', '["憶昨會詩酒，終日相逢迎。","今來成故事，歲月令人驚。","淚流紅粉薄，風度羅衣輕。","難爲子猷志，虛負文君名。"]', '["憶昨會诗酒，終日相逢迎。","今来成故事，歲月令人驚。","泪流紅粉薄，风度羅衣轻。","难爲子猷志，虛負文君名。"]', '诗', 'shi', '', NULL, '寄遠 田娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d9d9ede-c866-4998-a3ad-56b555fda913', '攜手曲', '携手曲', 'c3eab4f9-1607-4725-922e-a095f7c3b5ee', '唐', '["攜手共惜芳菲節，鶯啼錦花滿城闕。","行樂逶迤念容色，色衰秪恐君恩歇。","鳳笙龍管白日陰，盈虧自感青天月。"]', '["携手共惜芳菲節，鶯啼錦花满城闕。","行乐逶迤念容色，色衰秪恐君恩歇。","鳳笙龙管白日陰，盈虧自感青天月。"]', '诗', 'shi', '', NULL, '攜手曲 田娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4cb36e5-ee18-4734-96bd-bdccb2fee3b1', '長信宮', '长信宮', 'c3eab4f9-1607-4725-922e-a095f7c3b5ee', '唐', '["團圓手中扇，昔爲君所持。","今日君棄捐，復值秋風時。","悲將入篋笥，自歎知何爲。"]', '["團圓手中扇，昔爲君所持。","今日君棄捐，复值秋风时。","悲將入篋笥，自歎知何爲。"]', '诗', 'shi', '', NULL, '長信宮 田娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b974b7b2-1ab0-4f2f-9edb-4f5660769962', '句', '句', 'c3eab4f9-1607-4725-922e-a095f7c3b5ee', '唐', '["春至偏無興，秋來秪是眠。"]', '["春至偏無兴，秋来秪是眠。"]', '诗', 'shi', '', NULL, '句 田娥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab994ff1-9f7f-40d8-af58-7966593e7c08', '中秋夜泊武昌', '中秋夜泊武昌', 'fcc430db-cecc-4dcd-bb48-bef31ff2c161', '唐', '["兩城相對峙，一水向東流。","今夜素娥月，何年黃鶴樓。","悠悠蘭棹晚，渺渺荻花秋。","無奈柔腸斷，關山總是愁。"]', '["兩城相对峙，一水向东流。","今夜素娥月，何年黄鹤楼。","悠悠蘭棹晚，渺渺荻花秋。","無奈柔腸斷，关山總是愁。"]', '诗', 'shi', '', NULL, '中秋夜泊武昌 劉淑柔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8835ee02-a5ec-4f9c-b812-e2d9d373607c', '賦荆門', '賦荆门', '5722f4ca-17bc-4c59-b246-fa8c17eedfc6', '唐', '["黃鳥翻紅樹，青牛臥綠苔。","渚宮歌舞地，輕霧鎖樓臺。"]', '["黄鸟翻紅樹，青牛臥綠苔。","渚宮歌舞地，轻霧鎖楼台。"]', '诗', 'shi', '', NULL, '賦荆門 薛瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db8979f4-2816-450f-8c0d-f42aa28489b2', '戲贈', '戲贈', 'a7f92220-a787-4029-bdb3-a2b52c705c0d', '唐', '["砌下梧桐葉正齊，花繁雨後壓枝低。","報道不須鵶鳥亂，他家自有鳳凰棲。"]', '["砌下梧桐葉正齊，花繁雨後壓枝低。","報道不須鵶鸟亂，他家自有鳳凰棲。"]', '诗', 'shi', '', NULL, '戲贈 趙虛舟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae42fd73-831d-4411-919e-0fc62a2218b0', '銅雀臺', '銅雀台', 'd39f9a26-d375-46f8-86c5-0225639a8d34', '唐', '["君王冥漠不可見，銅雀歌舞空裴回。","西陵嘖嘖悲宿鳥，高殿沈沈閉青苔。","青苔無人跡，紅粉空相哀。"]', '["君王冥漠不可见，銅雀歌舞空裴回。","西陵嘖嘖悲宿鸟，高殿沈沈閉青苔。","青苔無人跡，紅粉空相哀。"]', '诗', 'shi', '', NULL, '銅雀臺 張瑛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39862216-ed03-4c0f-9d5f-6e8745f0dd67', '望月', '望月', 'd39f9a26-d375-46f8-86c5-0225639a8d34', '唐', '["天漢涼秋夜，澄澄一鏡明。","山空猨屢嘯，林靜鶴頻驚。"]', '["天漢涼秋夜，澄澄一镜明。","山空猨屢嘯，林静鹤頻驚。"]', '诗', 'shi', '', NULL, '望月 張瑛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691c2c25-fefa-4a1b-8976-1e51bb881ab4', '荅外', '荅外', '8cfcf55a-ed57-4728-830f-ada3c59f2496', '唐', '["征人去年戍邊水，夜得邊書字盈紙。","揮刀就燭裁紅綺，結作同心荅千里。","君寄邊書書莫絕，妾荅同心心自結。","同心再解不心離，離字頻看字愁滅。","結成一衣和淚封，封書只在懷袖中。","莫如書故字難久，願學同心長可同。"]', '["征人去年戍邊水，夜得邊书字盈紙。","揮刀就燭裁紅綺，結作同心荅千里。","君寄邊书书莫絕，妾荅同心心自結。","同心再解不心離，離字頻看字愁滅。","結成一衣和泪封，封书只在懷袖中。","莫如书故字难久，願学同心长可同。"]', '诗', 'shi', '', NULL, '荅外 長孫佐轉妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f044ce-6285-45b0-916a-10849d942b1b', '早梅', '早梅', 'f57a8fef-c9b1-4f83-af1f-a4c730e8a76a', '唐', '["南枝向暖北枝寒，一種春風有兩般。","憑仗高樓莫吹笛，大家留取倚闌干。"]', '["南枝向暖北枝寒，一種春风有兩般。","憑仗高楼莫吹笛，大家留取倚闌干。"]', '诗', 'shi', '', NULL, '早梅 劉元載妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb2b878b-df90-4d93-8cb0-590dd31e1453', '明月堂 一', '明月堂 一', 'c224e1c2-7c2a-421b-9ad2-6efa51773a52', '唐', '["蟬鬢驚秋華髮新，可憐紅隙盡埃塵。","西山一夢何年覺，明月堂前不見人。"]', '["蟬鬢驚秋华髮新，可怜紅隙尽埃塵。","西山一梦何年覺，明月堂前不见人。"]', '诗', 'shi', '', NULL, '明月堂 一 劉氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cabfa0f5-1f99-47b2-b9e5-047fd7ff7657', '明月堂 二', '明月堂 二', 'c224e1c2-7c2a-421b-9ad2-6efa51773a52', '唐', '["玉鉤風急響丁東，回首西山似夢中。","明月堂前人不到，庭梧一夜老秋風。"]', '["玉鉤风急响丁东，回首西山似梦中。","明月堂前人不到，庭梧一夜老秋风。"]', '诗', 'shi', '', NULL, '明月堂 二 劉氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92556558-bf3f-4720-888b-78a4a0c5e634', '和潘雍', '和潘雍', 'cf9b4227-1ec9-4f38-babd-df7ada4af24d', '唐', '["九天天遠瑞煙濃，駕鶴驂鸞意已同。","從此三山山上月，瓊花開處照春風。"]', '["九天天远瑞煙濃，駕鹤驂鸾意已同。","從此三山山上月，瓊花开处照春风。"]', '诗', 'shi', '', NULL, '和潘雍 葛氏女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99654625-2d53-4cb0-9bf6-83c88b781506', '寄詩', '寄诗', 'b1e5a814-e443-464c-add1-6d6eca0fc26c', '唐', '["去時盟約與心違，秋日離家春不歸。","應是維揚風景好，恣情歡笑到芳菲。"]', '["去时盟約與心違，秋日離家春不归。","應是維揚风景好，恣情歡笑到芳菲。"]', '诗', 'shi', '', NULL, '寄詩 李主簿姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa2d13b-6f5a-4a95-b875-0998ec6f9fc4', '題興元明珠亭', '題兴元明珠亭', 'bb49449c-2fb5-4302-87fa-c77f438e5dbf', '唐', '["寂寥滿地落花紅，獨有離人萬恨中。","回首池塘更無語，手彈珠淚與春風。"]', '["寂寥满地落花紅，独有離人万恨中。","回首池塘更無語，手彈珠泪與春风。"]', '诗', 'shi', '', NULL, '題興元明珠亭 京兆女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('802382ff-a138-439a-99c2-5697ae2ef2f4', '題玉泉溪', '題玉泉溪', '4b71b80c-121c-4ac5-8965-d046ed56d031', '唐', '["紅葉醉秋色，碧溪彈夜弦。","佳期不可再，風雨杳如年。"]', '["紅葉醉秋色，碧溪彈夜弦。","佳期不可再，风雨杳如年。"]', '诗', 'shi', '', NULL, '題玉泉溪 湘驛女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43597c78-90ae-45d4-90d7-206258606649', '題三鄉詩', '題三乡诗', 'a0b0138e-527a-486f-a088-b963239b83a2', '唐', '["昔逐良人西入關，良人身歿妾空還。","謝娘衛女不相待，爲雨爲雲歸此山。"]', '["昔逐良人西入关，良人身歿妾空還。","謝娘衛女不相待，爲雨爲云归此山。"]', '诗', 'shi', '', NULL, '題三鄉詩 若耶溪女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad62f19-486f-4c9e-aedb-2839b134bd27', '題沙鹿門', '題沙鹿门', '0f2b3468-4bb7-4680-9fb6-10cc013b1cab', '唐', '["昔逐良人去上京，良人身歿妾東征。","同來不得同歸去，永負朝雲暮雨情。"]', '["昔逐良人去上京，良人身歿妾东征。","同来不得同归去，永負朝云暮雨情。"]', '诗', 'shi', '', NULL, '題沙鹿門 誰氏女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a14f739c-f704-4690-bc56-3d64a436d84a', '聯句', '聯句', '2ffd7555-6a5f-4ee5-883f-2c6d360bf39a', '唐', '["朱樓影直日當午，玉樹陰低月已三。","膩粉暗銷銀鏤合，錯刀閑翦泥金衫。","繡牀怕引烏龍吠，錦字愁教青鳥銜。","百味鍊來憐益母，千花開處鬬宜男。","鴛鴦有伴誰能羨，鸚鵡無言我自慚。","浪喜游蜂飛撲撲，佯驚孤燕語喃喃。","偏憐愛數螆蛦掌，每憶光抽玳瑁簪。","煙洞幾年悲尚在，星橋一夕帳空含。","窗前時節羞虛擲，世上風流笑苦諳。","獨結香綃偷餉送，暗垂檀袖學通參。","須知化石心難定，却是爲雲分易甘。","看見風光零落盡，弦聲猶逐望江南。"]', '["朱楼影直日當午，玉樹陰低月已三。","膩粉暗銷銀鏤合，錯刀闲翦泥金衫。","繡牀怕引烏龙吠，錦字愁教青鸟銜。","百味鍊来怜益母，千花开处鬬宜男。","鴛鴦有伴誰能羨，鸚鵡無言我自慚。","浪喜游蜂飞撲撲，佯驚孤燕語喃喃。","偏怜愛數螆蛦掌，每憶光抽玳瑁簪。","煙洞幾年悲尚在，星橋一夕帳空含。","窗前时節羞虛擲，世上风流笑苦諳。","独結香綃偷餉送，暗垂檀袖学通參。","須知化石心难定，却是爲云分易甘。","看见风光零落尽，弦声猶逐望江南。"]', '诗', 'shi', '', NULL, '聯句 光	威	裒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d939efa-882f-4309-a6d1-e308c20efafb', '聯句', '聯句', 'c804800b-12d3-457b-aad2-02a7fa64fe9f', '唐', '["珠簾半牀月，青竹滿林風。","何事今宵景，無人解語同。"]', '["珠簾半牀月，青竹满林风。","何事今宵景，無人解語同。"]', '诗', 'shi', '', NULL, '聯句 越溪楊女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5851073-c8d2-4767-9aa4-368b0ddf5241', '春日', '春日', 'c804800b-12d3-457b-aad2-02a7fa64fe9f', '唐', '["春盡花隨盡，其如自是花。","從來說花意，不過此容華。","明月易虧輪，好花難戀春。","常將花月恨，幷作可憐人。"]', '["春尽花隨尽，其如自是花。","從来说花意，不過此容华。","明月易虧輪，好花难戀春。","常將花月恨，幷作可怜人。"]', '诗', 'shi', '', NULL, '春日 越溪楊女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdd65817-92c0-418b-b438-ae8a2191bfde', '句', '句', 'eaa32544-86e4-469e-ad87-5a779b5fa211', '唐', '["鑿開天外長生地，煉出人間不死丹。"]', '["鑿开天外长生地，煉出人间不死丹。"]', '诗', 'shi', '', NULL, '句 曹文姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff3fa1e4-a19d-4174-a3a2-df0cc4d92e6f', '燕子樓三首 一', '燕子楼三首 一', '7b5ac71c-f8a6-467b-9a36-8a6d98457a75', '唐', '["樓上殘燈伴曉霜，獨眠人起合歡牀。","相思一夜情多少，地角天涯不是長。"]', '["楼上殘灯伴晓霜，独眠人起合歡牀。","相思一夜情多少，地角天涯不是长。"]', '诗', 'shi', '', NULL, '燕子樓三首 一 關盼盼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac228bec-b314-4f29-9055-f6a7656826cc', '燕子樓三首 二', '燕子楼三首 二', '7b5ac71c-f8a6-467b-9a36-8a6d98457a75', '唐', '["北邙松柏鎖愁煙，燕子樓中思悄然。","自埋劒履歌塵散，紅袖香銷一十年。"]', '["北邙松柏鎖愁煙，燕子楼中思悄然。","自埋劒履歌塵散，紅袖香銷一十年。"]', '诗', 'shi', '', NULL, '燕子樓三首 二 關盼盼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90de0390-09b6-4600-93f9-785b76ad77bb', '燕子樓三首 三', '燕子楼三首 三', '7b5ac71c-f8a6-467b-9a36-8a6d98457a75', '唐', '["適看鴻雁岳陽迴，又覩玄禽逼社來。","瑤瑟玉簫無意緒，任從蛛網任從灰。"]', '["適看鴻雁岳陽迴，又覩玄禽逼社来。","瑤瑟玉簫無意緒，任從蛛網任從灰。"]', '诗', 'shi', '', NULL, '燕子樓三首 三 關盼盼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a0a4812-c838-4110-aaed-21557ce2cc49', '和白公詩', '和白公诗', '7b5ac71c-f8a6-467b-9a36-8a6d98457a75', '唐', '["自守空樓斂恨眉，形同春後牡丹枝。","舍人不會人深意，訝道泉臺不去隨。"]', '["自守空楼斂恨眉，形同春後牡丹枝。","舍人不會人深意，訝道泉台不去隨。"]', '诗', 'shi', '', NULL, '和白公詩 關盼盼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d13dcd5-c6c6-4bf8-92fd-b2e2aee78e3b', '句', '句', '7b5ac71c-f8a6-467b-9a36-8a6d98457a75', '唐', '["兒童不識沖天物，漫把青泥污雪毫。"]', '["兒童不識沖天物，漫把青泥污雪毫。"]', '诗', 'shi', '', NULL, '句 關盼盼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e858f015-2cf5-420c-870a-621f1e85dd2c', '囉嗊曲六首 一', '囉嗊曲六首 一', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["不喜秦淮水，生憎江上船。","載兒夫壻去，經歲又經年。"]', '["不喜秦淮水，生憎江上船。","載兒夫壻去，經歲又經年。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 一 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c693bf0e-7b67-4502-a0b6-19753aa799bb', '囉嗊曲六首 二', '囉嗊曲六首 二', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["借問東園柳，枯來得幾年。","自無枝葉分，莫怨太陽偏。"]', '["借问东园柳，枯来得幾年。","自無枝葉分，莫怨太陽偏。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 二 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a74af8-d559-4941-80f0-1b7d3c427f52', '囉嗊曲六首 三', '囉嗊曲六首 三', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["莫作商人婦，金釵當卜錢。","朝朝江口望，錯認幾人船。"]', '["莫作商人婦，金釵當卜錢。","朝朝江口望，錯認幾人船。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 三 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3b5d49-4baf-4326-b9f7-8ca654d0c3f9', '囉嗊曲六首 四', '囉嗊曲六首 四', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["那年離別日，只道住桐廬。","桐廬人不見，今得廣州書。"]', '["那年離別日，只道住桐廬。","桐廬人不见，今得廣州书。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 四 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f7584f-ac84-40ce-b4ec-86e8edbb9637', '囉嗊曲六首 五', '囉嗊曲六首 五', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["昨日勝今日，今年老去年。","黃河清有日，白髮黑無緣。"]', '["昨日勝今日，今年老去年。","黄河清有日，白髮黑無緣。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 五 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3b6c87-dfbf-47d5-8b47-ff210190740e', '囉嗊曲六首 六', '囉嗊曲六首 六', '753c105f-7877-408d-9f31-bead2975c365', '唐', '["昨日北風寒，牽船浦裏安。","潮來打纜斷，搖櫓始知難。"]', '["昨日北风寒，牽船浦裏安。","潮来打纜斷，搖櫓始知难。"]', '诗', 'shi', '', NULL, '囉嗊曲六首 六 劉采春 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa34fe1-59ef-4a15-8c16-882b758d5e06', '寄歐陽詹', '寄歐陽詹', 'c5f49ab9-0edb-4f60-9588-2beff7549c9a', '唐', '["自從別後減容光，半是思郎半恨郎。","欲識舊來雲髻樣，爲奴開取縷金箱。"]', '["自從別後減容光，半是思郎半恨郎。","欲識旧来云髻樣，爲奴开取縷金箱。"]', '诗', 'shi', '', NULL, '寄歐陽詹 太原妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfef5c19-8a9c-4c05-be51-d24cb2c1ce76', '續韋蟾句', '續韋蟾句', 'c5ca8309-404e-4304-ade8-2e2037478357', '唐', '["悲莫悲兮生別離，登山臨水送將歸。","武昌無限新栽柳，不見楊花撲面飛。"]', '["悲莫悲兮生別離，登山臨水送將归。","武昌無限新栽柳，不见楊花撲面飞。"]', '诗', 'shi', '', NULL, '續韋蟾句 武昌妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef49398-d683-436d-9884-3145cfb7f8a8', '獻李觀察', '獻李观察', '3c2543a0-7bb0-4ee2-9ddf-9ce601ed73c8', '唐', '["湘江舞罷忽成悲，便脫蠻靴出絳帷。","誰是蔡邕琴酒客，魏公懷舊嫁文姬。"]', '["湘江舞罷忽成悲，便脫蠻靴出絳帷。","誰是蔡邕琴酒客，魏公懷旧嫁文姬。"]', '诗', 'shi', '', NULL, '獻李觀察 舞柘枝女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ca1660-45c6-4d77-81a1-8e6d98d0f75b', '贈盧夫人', '贈盧夫人', '3315c25b-e3d2-493f-a24d-7c6279d40293', '唐', '["佳人惜顏色，恐逐芳菲歇。","日暮出畫堂，下堦拜新月。","拜月如有詞，傍人那得知。","歸來投玉枕，始覺淚痕垂。"]', '["佳人惜顏色，恐逐芳菲歇。","日暮出畫堂，下堦拜新月。","拜月如有词，傍人那得知。","归来投玉枕，始覺泪痕垂。"]', '诗', 'shi', '', NULL, '贈盧夫人 常浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42213986-9ad5-4b3a-bbe9-38f1aaf69cc8', '寄遠', '寄远', '3315c25b-e3d2-493f-a24d-7c6279d40293', '唐', '["年年二月時，十年期別期。","春風不知信，軒蓋獨遲遲。","今日無端捲珠箔，始見庭花復零落。","人心一往不復歸，歲月來時未嘗錯。","可憐熒熒玉鏡臺，塵飛冪冪幾時開。","却念容華非昔好，畫眉猶自待君來。"]', '["年年二月时，十年期別期。","春风不知信，軒蓋独遲遲。","今日無端捲珠箔，始见庭花复零落。","人心一往不复归，歲月来时未嘗錯。","可怜熒熒玉镜台，塵飞冪冪幾时开。","却念容华非昔好，畫眉猶自待君来。"]', '诗', 'shi', '', NULL, '寄遠 常浩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574c4ef0-3e5f-402e-9663-c34a9e871094', '送武補闕', '送武補闕', '85b75edc-caa3-414b-a887-93a5e38ff531', '唐', '["弄珠灘上欲銷魂，獨把離懷寄酒尊。","無限煙花不留意，忍教芳草怨王孫。"]', '["弄珠灘上欲銷魂，独把離懷寄酒尊。","無限煙花不留意，忍教芳草怨王孫。"]', '诗', 'shi', '', NULL, '送武補闕 襄陽妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c27e90-6c08-4eca-91f4-d595476a3c43', '題孫棨詩後', '題孫棨诗後', 'a0b929ca-a6f9-4034-b9b9-9c0d8a90e82c', '唐', '["苦把文章邀勸人，吟看好箇語言新。","雖然不及相如賦，也直黃金一二斤。"]', '["苦把文章邀勸人，吟看好箇語言新。","雖然不及相如賦，也直黄金一二斤。"]', '诗', 'shi', '', NULL, '題孫棨詩後 王福娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2003f214-004c-47e5-ba88-3b3d0922ae2e', '問棨詩', '问棨诗', 'a0b929ca-a6f9-4034-b9b9-9c0d8a90e82c', '唐', '["日日悲傷未有圖，嬾將心事話凡夫。","非同覆水應收得，只問仙郎有意無。"]', '["日日悲傷未有圖，嬾將心事話凡夫。","非同覆水應收得，只问仙郎有意無。"]', '诗', 'shi', '', NULL, '問棨詩 王福娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c6b743d-67eb-4201-97cf-1ae1b8d8fd7c', '謝棨詩', '謝棨诗', 'a0b929ca-a6f9-4034-b9b9-9c0d8a90e82c', '唐', '["久賦恩情欲託身，已將心事再三陳。","泥蓮既沒移栽分，今日分離莫恨人。"]', '["久賦恩情欲託身，已將心事再三陳。","泥蓮既沒移栽分，今日分離莫恨人。"]', '诗', 'shi', '', NULL, '謝棨詩 王福娘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc0e48f-426e-49f6-b00a-3c0b056323ce', '荅小子弟詩', '荅小子弟诗', 'cb858785-8770-4684-9f4c-4643ed5c883e', '唐', '["黃口小兒口莫憑，逡巡看取第三名。","孝廉持水添缾子，莫向街頭亂椀鳴。"]', '["黄口小兒口莫憑，逡巡看取第三名。","孝廉持水添缾子，莫向街头亂椀鳴。"]', '诗', 'shi', '', NULL, '荅小子弟詩 楊萊兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705323cd-0250-475f-99fc-de605dd37c80', '和趙光遠題壁', '和趙光远題壁', 'cb858785-8770-4684-9f4c-4643ed5c883e', '唐', '["長者車塵每到門，長卿非慕卓王孫。","定知羽翼難隨鳳，却喜波濤未化鯤。","嬌別翠鈿黏去袂，醉歌金雀碎殘尊。","多情多病年應促，早辦名香爲返魂。"]', '["长者车塵每到门，长卿非慕卓王孫。","定知羽翼难隨鳳，却喜波濤未化鯤。","嬌別翠鈿黏去袂，醉歌金雀碎殘尊。","多情多病年應促，早辦名香爲返魂。"]', '诗', 'shi', '', NULL, '和趙光遠題壁 楊萊兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001f0948-aab3-462e-abab-bb2b819cda0a', '貽鄭昌圖', '貽鄭昌圖', '99443206-2c8e-4397-84cc-d57dfb4b2df8', '唐', '["應是前生有宿冤，不期今世惡因緣。","蛾眉欲碎巨靈掌，雞肋難勝子路拳。","秪擬嚇人傳鐵券，未應教我踏青蓮。","曲江昨日君相遇，當下遭他數十鞭。"]', '["應是前生有宿冤，不期今世惡因緣。","蛾眉欲碎巨靈掌，雞肋难勝子路拳。","秪擬嚇人傳鐵券，未應教我踏青蓮。","曲江昨日君相遇，當下遭他數十鞭。"]', '诗', 'shi', '', NULL, '貽鄭昌圖 楚兒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9cd16aa-876f-4bb9-b871-ea629ceb4104', '和李標', '和李標', '7711d996-888f-480a-93fb-1607e91baa2e', '唐', '["怪得犬驚雞亂飛，羸童瘦馬老麻衣。","阿誰亂引閑人到，留住青蚨熱趕歸。"]', '["怪得犬驚雞亂飞，羸童瘦马老麻衣。","阿誰亂引闲人到，留住青蚨熱趕归。"]', '诗', 'shi', '', NULL, '和李標 王蘇蘇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87bd24e2-01df-4a79-abfb-efb95d837171', '臨終召客', '臨終召客', 'a477d82d-b154-435e-90e9-07c7f6286a2a', '唐', '["氣餘三五喘，花剩兩三枝。","話別一尊酒，相邀無後期。"]', '["氣餘三五喘，花剩兩三枝。","話別一尊酒，相邀無後期。"]', '诗', 'shi', '', NULL, '臨終召客 顏令賓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57168810-72bc-4465-9d8d-469e45e3d948', '寄故人', '寄故人', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["淡淡春風花落時，不堪愁望更相思。","無金可買長門賦，有恨空吟團扇詩。"]', '["淡淡春风花落时，不堪愁望更相思。","無金可買长门賦，有恨空吟團扇诗。"]', '诗', 'shi', '', NULL, '寄故人 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78fc260-abdc-4de9-a29b-58274b9636a6', '上成都在事', '上成都在事', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["昨日賣衣裳，今日賣衣裳。","衣裳渾賣盡，羞見嫁時箱。","有賣愁仍緩，無時心轉傷。"]', '["昨日賣衣裳，今日賣衣裳。","衣裳渾賣尽，羞见嫁时箱。","有賣愁仍緩，無时心轉傷。"]', '诗', 'shi', '', NULL, '上成都在事 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ffe758-af77-4a7c-b246-fe47ca00414b', '春思二首 一', '春思二首 一', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["門前梅柳爛春輝，閉妾深閨繡舞衣。","雙燕不知腸欲斷，銜泥故故傍人飛。"]', '["门前梅柳爛春輝，閉妾深閨繡舞衣。","雙燕不知腸欲斷，銜泥故故傍人飞。"]', '诗', 'shi', '', NULL, '春思二首 一 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dfdd875-80b6-4595-b41a-af4bf573f2d1', '春思二首 二', '春思二首 二', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["井上梧桐是妾移，夜來花發最高枝。","若教不向深閨種，春過門前爭得知。"]', '["井上梧桐是妾移，夜来花發最高枝。","若教不向深閨種，春過门前爭得知。"]', '诗', 'shi', '', NULL, '春思二首 二 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4074a45c-dec2-4bbd-bc7d-683b73ac7fac', '西江行', '西江行', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["日下西塞山，南來洞庭客。","晴空白鳥度，萬里秋光碧。"]', '["日下西塞山，南来洞庭客。","晴空白鸟度，万里秋光碧。"]', '诗', 'shi', '', NULL, '西江行 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e699650a-5b53-4a8a-b058-69a4d0835457', '贈所思', '贈所思', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["與君咫尺長離別，遣妾容華爲誰說。","夕望層城眼欲穿，曉臨明鏡腸堪絕。"]', '["與君咫尺长離別，遣妾容华爲誰说。","夕望層城眼欲穿，晓臨明镜腸堪絕。"]', '诗', 'shi', '', NULL, '贈所思 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cedf269-5e30-4b83-8152-021819148eac', '句', '句', '0d402104-88cd-46a1-b00b-3d52e193c9ef', '唐', '["滿院花飛人不到，含情欲語燕雙雙。"]', '["满院花飞人不到，含情欲語燕雙雙。"]', '诗', 'shi', '', NULL, '句 張窈窕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b32c76-2612-4e64-bafa-62900044331c', '贈裴思謙', '贈裴思謙', 'd78e9a76-079a-476c-b9ac-bf1c1d140ca8', '唐', '["銀釭斜背解明璫，小語偷聲賀玉郎。","從此不知蘭麝貴，夜來新惹桂枝香。"]', '["銀釭斜背解明璫，小語偷声賀玉郎。","從此不知蘭麝貴，夜来新惹桂枝香。"]', '诗', 'shi', '', NULL, '贈裴思謙 平康妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88bb632d-cfbf-49dd-803b-69f1a5de4eac', '迷香洞', '迷香洞', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["洞口飛瓊佩羽霓，香風飄拂使人迷。","自從邂逅芙蓉帳，不數桃花流水溪。"]', '["洞口飞瓊佩羽霓，香风飄拂使人迷。","自從邂逅芙蓉帳，不數桃花流水溪。"]', '诗', 'shi', '', NULL, '迷香洞 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477dd50e-337e-4b46-b80d-22c5db42b19e', '神雞枕', '神雞枕', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["枕繪鴛鴦久與棲，新裁霧縠鬬神雞。","與郎酣夢渾忘曉，雞亦留連不肯啼。"]', '["枕繪鴛鴦久與棲，新裁霧縠鬬神雞。","與郎酣梦渾忘晓，雞亦留連不肯啼。"]', '诗', 'shi', '', NULL, '神雞枕 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b354f44-4b85-44a9-8077-e85f01a4ea23', '鎖蓮燈', '鎖蓮灯', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["燈鎖蓮花花照罍，翠鈿同醉楚臺巍。","殘灰剔罷攜纖手，也勝金蓮送轍回。"]', '["灯鎖蓮花花照罍，翠鈿同醉楚台巍。","殘灰剔罷携纖手，也勝金蓮送轍回。"]', '诗', 'shi', '', NULL, '鎖蓮燈 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05cab70c-2a39-4101-b376-1931d6ecdc98', '鮫紅被', '鮫紅被', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["肱被當年僅禦寒，青樓慣染血猩紈。","牙牀舒卷鵷鸞共，正值窗櫺月一團。"]', '["肱被當年僅禦寒，青楼慣染血猩紈。","牙牀舒卷鵷鸾共，正值窗櫺月一團。"]', '诗', 'shi', '', NULL, '鮫紅被 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa8419f0-2bb4-4017-8f7c-95df04afc84f', '傳香枕', '傳香枕', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["韓壽香從何處傳，枕邊芳馥戀嬋娟。","休疑粉黛加鋌刃，玉女旃檀侍佛前。"]', '["韓壽香從何处傳，枕邊芳馥戀嬋娟。","休疑粉黛加鋌刃，玉女旃檀侍佛前。"]', '诗', 'shi', '', NULL, '傳香枕 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9e5ad2-b4ed-43a1-a234-31a80c2ec780', '八分羊', '八分羊', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["党家風味足肥羊，綺閣留人漫較量。","萬羊亦是男兒事，莫學狂夫取次嘗。"]', '["党家风味足肥羊，綺閣留人漫較量。","万羊亦是男兒事，莫学狂夫取次嘗。"]', '诗', 'shi', '', NULL, '八分羊 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8c9fc6-237d-4f41-bf87-6988452fde55', '閉門羮', '閉门羮', 'b01396b2-384d-475d-a3c4-415e05239c27', '唐', '["一豆聊供游冶郎，去時忙喚鎖倉琅。","入門獨慕相如侶，欲撥瑤琴彈鳳凰。"]', '["一豆聊供游冶郎，去时忙喚鎖倉琅。","入门独慕相如侶，欲撥瑤琴彈鳳凰。"]', '诗', 'shi', '', NULL, '閉門羮 史鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('779b5d60-21da-4e85-900d-6454a7ad0972', '突厥三臺', '突厥三台', 'a586f4c6-f347-4f6f-a483-d523cb58c071', '唐', '["雁門山上雁初飛，馬邑闌中馬正肥。","日旰山西逢驛使，殷勤南北送征衣。"]', '["雁门山上雁初飞，马邑闌中马正肥。","日旰山西逢驛使，殷勤南北送征衣。"]', '诗', 'shi', '', NULL, '突厥三臺 盛小叢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52848f8-4ef6-4ae2-9ef6-299d0013d090', '雲鬟', '云鬟', '3575c59d-4e46-4414-9ae6-4baafcb08840', '唐', '["擾擾香雲溼未乾，鴉領蟬翼膩光寒。","側邊斜插黃金鳳，妝罷夫君帶笑看。"]', '["擾擾香云溼未乾，鴉領蟬翼膩光寒。","側邊斜插黄金鳳，妝罷夫君带笑看。"]', '诗', 'shi', '', NULL, '雲鬟 趙鸞鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c5c0de-ac5a-44dd-83ab-3098d024dc2b', '柳眉', '柳眉', '3575c59d-4e46-4414-9ae6-4baafcb08840', '唐', '["彎彎柳葉愁邊戲，湛湛菱花照處頻。","嫵媚不煩螺子黛，春山畫出自精神。"]', '["彎彎柳葉愁邊戲，湛湛菱花照处頻。","嫵媚不煩螺子黛，春山畫出自精神。"]', '诗', 'shi', '', NULL, '柳眉 趙鸞鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eeb0ce1-7161-4efd-b810-0337d82ffb3f', '檀口', '檀口', '3575c59d-4e46-4414-9ae6-4baafcb08840', '唐', '["銜杯微動櫻桃顆，咳唾輕飄茉莉香。","曾見白家樊素口，瓠犀顆顆綴榴芳。"]', '["銜杯微动櫻桃顆，咳唾轻飄茉莉香。","曾见白家樊素口，瓠犀顆顆綴榴芳。"]', '诗', 'shi', '', NULL, '檀口 趙鸞鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f339e1-2cf0-45e3-946f-44073e873f43', '纖指', '纖指', '3575c59d-4e46-4414-9ae6-4baafcb08840', '唐', '["纖纖軟玉削春葱，長在香羅翠袖中。","昨日琵琶弦索上，分明滿甲染猩紅。"]', '["纖纖軟玉削春葱，长在香羅翠袖中。","昨日琵琶弦索上，分明满甲染猩紅。"]', '诗', 'shi', '', NULL, '纖指 趙鸞鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81532429-ef36-40f8-b756-bcc520acb994', '酥乳', '酥乳', '3575c59d-4e46-4414-9ae6-4baafcb08840', '唐', '["粉香汗溼瑤琴軫，春逗酥融綿雨膏。","浴罷檀郎捫弄處，靈華涼沁紫葡萄。"]', '["粉香汗溼瑤琴軫，春逗酥融綿雨膏。","浴罷檀郎捫弄处，靈华涼沁紫葡萄。"]', '诗', 'shi', '', NULL, '酥乳 趙鸞鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac890b1-7a13-4ed1-baba-e784b32b1bef', '獻陳陶處士', '獻陳陶处士', '2eea9fe6-0412-4293-ab40-5251ddf17c2c', '唐', '["蓮花爲號玉爲腮，珍重尚書遣妾來。","處士不生巫峽夢，虛勞神女下陽臺。"]', '["蓮花爲號玉爲腮，珍重尚书遣妾来。","处士不生巫峽梦，虛勞神女下陽台。"]', '诗', 'shi', '', NULL, '獻陳陶處士 蓮花妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c4ddf5e-4ed1-4fe1-aeaa-bb76fbb37e24', '敘懷', '敘懷', '22feec40-f26c-43a9-b3a0-a1e367980116', '唐', '["爲失三從泣淚頻，此身何用處人倫。","雖然日逐笙歌樂，長羨荆釵與布裙。"]', '["爲失三從泣泪頻，此身何用处人倫。","雖然日逐笙歌乐，长羨荆釵與布裙。"]', '诗', 'shi', '', NULL, '敘懷 徐月英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59097b44-1d00-4614-b1f3-ecbf1f4027cb', '送人', '送人', '22feec40-f26c-43a9-b3a0-a1e367980116', '唐', '["惆悵人間萬事違，兩人同去一人歸。","生憎平望亭前水，忍照鴛鴦相背飛。"]', '["惆悵人间万事違，兩人同去一人归。","生憎平望亭前水，忍照鴛鴦相背飞。"]', '诗', 'shi', '', NULL, '送人 徐月英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05253125-0031-4cd3-969a-77e338bd9c64', '句', '句', '22feec40-f26c-43a9-b3a0-a1e367980116', '唐', '["枕前淚與階前雨，隔箇窗兒滴到明。"]', '["枕前泪與階前雨，隔箇窗兒滴到明。"]', '诗', 'shi', '', NULL, '句 徐月英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5d6ccd-45e1-4cec-8a3a-d95d85266008', '句', '句', 'c1330b3a-cf15-4e28-8f25-52c3994ffbd5', '唐', '["連理枝前同設誓，丁香樹下共論心。"]', '["連理枝前同設誓，丁香樹下共論心。"]', '诗', 'shi', '', NULL, '句 韓襄客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e2897b-9c85-4b01-b8cb-3d9638721a9a', '酬人雨後翫竹', '酬人雨後翫竹', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["南天春雨時，那鑒雪霜姿。","衆類亦云茂，虛心能自持。","多留晉賢醉，早伴舜妃悲。","晚歲君能賞，蒼蒼勁節奇。"]', '["南天春雨时，那鑒雪霜姿。","衆類亦云茂，虛心能自持。","多留晉賢醉，早伴舜妃悲。","晚歲君能賞，蒼蒼勁節奇。"]', '诗', 'shi', '', NULL, '酬人雨後翫竹 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19341330-b123-450b-ab52-ea269709799f', '春望詞四首 一', '春望词四首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["花開不同賞，花落不同悲。","欲問相思處，花開花落時。"]', '["花开不同賞，花落不同悲。","欲问相思处，花开花落时。"]', '诗', 'shi', '', NULL, '春望詞四首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('439d558d-d67f-449d-b4b8-6566b27406cb', '春望詞四首 二', '春望词四首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["攬草結同心，將以遺知音。","春愁正斷絕，春鳥復哀吟。"]', '["攬草結同心，將以遺知音。","春愁正斷絕，春鸟复哀吟。"]', '诗', 'shi', '', NULL, '春望詞四首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba4c1606-3635-4e6a-bf0b-5324389eec27', '春望詞四首 三', '春望词四首 三', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["風花日將老，佳期猶渺渺。","不結同心人，空結同心草。"]', '["风花日將老，佳期猶渺渺。","不結同心人，空結同心草。"]', '诗', 'shi', '', NULL, '春望詞四首 三 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d87441-72e8-481a-9c57-9395380c3041', '春望詞四首 四', '春望词四首 四', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["那堪花滿枝，翻作兩相思。","玉筯垂朝鏡，春風知不知。"]', '["那堪花满枝，翻作兩相思。","玉筯垂朝镜，春风知不知。"]', '诗', 'shi', '', NULL, '春望詞四首 四 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a5d5a0e-d6b0-441a-99dd-da6091a65dfc', '宣上人見示與諸公唱和', '宣上人见示與諸公唱和', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["許廁高齋唱，涓泉定不如。","可憐譙記室，流水滿禪居。"]', '["許廁高斋唱，涓泉定不如。","可怜譙記室，流水满禪居。"]', '诗', 'shi', '', NULL, '宣上人見示與諸公唱和 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04073662-f94a-4147-9d4a-0d67f32b0ea0', '風', '风', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["獵蕙微風遠，飄弦唳一聲。","林梢鳴淅瀝，松徑夜淒清。"]', '["獵蕙微风远，飄弦唳一声。","林梢鳴淅瀝，松徑夜淒清。"]', '诗', 'shi', '', NULL, '風 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('256a243c-0921-4612-b5dc-29571f75f517', '月', '月', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["魄依鉤樣小，扇逐漢機團。","細影將圓質，人間幾處看。"]', '["魄依鉤樣小，扇逐漢機團。","細影將圓質，人间幾处看。"]', '诗', 'shi', '', NULL, '月 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09d6c628-a2f3-4172-ab93-61c63644680e', '蟬', '蟬', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["露滌清音遠，風吹數葉齊。","聲聲似相接，各在一枝棲。"]', '["露滌清音远，风吹數葉齊。","声声似相接，各在一枝棲。"]', '诗', 'shi', '', NULL, '蟬 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d40c55d-a851-4643-89e1-1f690f707f26', '池上雙鳥', '池上雙鸟', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["雙棲綠池上，朝暮共飛還。","更憶將雛日，同心蓮葉間。"]', '["雙棲綠池上，朝暮共飞還。","更憶將雛日，同心蓮葉间。"]', '诗', 'shi', '', NULL, '池上雙鳥 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5857f45-77b0-4006-ab95-b61a6f0718b2', '鴛鴦草', '鴛鴦草', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["綠英滿香砌，兩兩鴛鴦小。","但娛春日長，不管秋風早。"]', '["綠英满香砌，兩兩鴛鴦小。","但娛春日长，不管秋风早。"]', '诗', 'shi', '', NULL, '鴛鴦草 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4825eddd-ed4f-49ff-9987-fb897838c041', '罰赴邊有懷上韋令公二首 一', '罰赴邊有懷上韋令公二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["聞道邊城苦，今來到始知。","羞將門下曲，唱與隴頭兒。"]', '["闻道邊城苦，今来到始知。","羞將门下曲，唱與隴头兒。"]', '诗', 'shi', '', NULL, '罰赴邊有懷上韋令公二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa5f34d-3d7b-4e11-b493-37c66d13d981', '罰赴邊有懷上韋令公二首 二', '罰赴邊有懷上韋令公二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["黠虜猶違命，烽煙直北愁。","却教嚴譴妾，不敢向松州。"]', '["黠虜猶違命，烽煙直北愁。","却教嚴譴妾，不敢向松州。"]', '诗', 'shi', '', NULL, '罰赴邊有懷上韋令公二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e60f1a6-4ec3-4b0e-ad50-d9707e9a9797', '詠八十一顆', '詠八十一顆', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["色比丹霞朝日，形如合浦篔簹。","開時九九如數，見處雙雙頡頏。"]', '["色比丹霞朝日，形如合浦篔簹。","开时九九如數，见处雙雙頡頏。"]', '诗', 'shi', '', NULL, '詠八十一顆 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef14b41-4086-4330-b6c2-4e5150852042', '謁巫山廟', '謁巫山廟', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["亂猨啼處訪高唐，路入煙霞草木香。","山色未能忘宋玉，水聲猶是哭襄王。","朝朝夜夜陽臺下，爲雨爲雲楚國亡。","惆悵廟前多少柳，春來空鬬畫眉長。"]', '["亂猨啼处訪高唐，路入煙霞草木香。","山色未能忘宋玉，水声猶是哭襄王。","朝朝夜夜陽台下，爲雨爲云楚国亡。","惆悵廟前多少柳，春来空鬬畫眉长。"]', '诗', 'shi', '', NULL, '謁巫山廟 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d06526a-f145-4a6d-89a2-02e94b937926', '牡丹', '牡丹', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["去春零落暮春時，淚溼紅箋怨別離。","常恐便同巫峽散，因何重有武陵期。","傳情每向馨香得，不語還應彼此知。","只欲欄邊安枕席，夜深閑共說相思。"]', '["去春零落暮春时，泪溼紅箋怨別離。","常恐便同巫峽散，因何重有武陵期。","傳情每向馨香得，不語還應彼此知。","只欲欄邊安枕席，夜深闲共说相思。"]', '诗', 'shi', '', NULL, '牡丹 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a49b1116-a19b-4ab9-a350-ddf0ac19d3e7', '賊平後上高相公', '賊平後上高相公', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["驚看天地白荒荒，瞥見青山舊夕陽。","始信大威能照映，由來日月借生光。"]', '["驚看天地白荒荒，瞥见青山旧夕陽。","始信大威能照映，由来日月借生光。"]', '诗', 'shi', '', NULL, '賊平後上高相公 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d521658-87fc-448e-b859-5fcd006cc482', '送友人', '送友人', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["水國蒹葭夜有霜，月寒山色共蒼蒼。","誰言千里自今夕，離夢杳如關塞長。"]', '["水国蒹葭夜有霜，月寒山色共蒼蒼。","誰言千里自今夕，離梦杳如关塞长。"]', '诗', 'shi', '', NULL, '送友人 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad4a9e5b-eb18-448c-878a-450bc7f8909f', '聽僧吹蘆管', '听僧吹蘆管', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["曉蟬嗚咽暮鶯愁，言語殷勤十指頭。","罷閱梵書聊一弄，散隨金磬泥清秋。"]', '["晓蟬嗚咽暮鶯愁，言語殷勤十指头。","罷閱梵书聊一弄，散隨金磬泥清秋。"]', '诗', 'shi', '', NULL, '聽僧吹蘆管 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76faf698-ecaa-440a-802b-36038adc896a', '酬郭簡州寄柑子', '酬郭簡州寄柑子', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["霜規不讓黃金色，圓質仍含御史香。","何處同聲情最異，臨川太守謝家郎。"]', '["霜規不讓黄金色，圓質仍含御史香。","何处同声情最異，臨川太守謝家郎。"]', '诗', 'shi', '', NULL, '酬郭簡州寄柑子 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e8e0144-a717-4467-b6ab-c9ad3a0dc8a2', '上川主武元衡相國二首 一', '上川主武元衡相国二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["落日重城夕霧收，玳筵雕俎薦諸侯。","因令朗月當庭燎，不使珠簾下玉鉤。"]', '["落日重城夕霧收，玳筵雕俎薦諸侯。","因令朗月當庭燎，不使珠簾下玉鉤。"]', '诗', 'shi', '', NULL, '上川主武元衡相國二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3d356bf-bd83-4aa9-aa30-3a2f4c47e4a3', '上川主武元衡相國二首 二', '上川主武元衡相国二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["東閣移尊綺席陳，貂簪龍節更宜春。","軍城畫角三聲歇，雲幕初垂紅燭新。"]', '["东閣移尊綺席陳，貂簪龙節更宜春。","軍城畫角三声歇，云幕初垂紅燭新。"]', '诗', 'shi', '', NULL, '上川主武元衡相國二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0642653-c834-4a31-9fe4-d60d50a4ca8c', '憶荔枝', '憶荔枝', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["傳聞象郡隔南荒，絳實豐肌不可忘。","近有青衣連楚水，素漿還得類瓊漿。"]', '["傳闻象郡隔南荒，絳實豐肌不可忘。","近有青衣連楚水，素漿還得類瓊漿。"]', '诗', 'shi', '', NULL, '憶荔枝 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eea14da6-9c31-4559-beb0-1e9ad1bcc617', '斛石山曉望寄呂侍御', '斛石山晓望寄呂侍御', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["曦輪初轉照仙扃，旋擘煙嵐上窅冥。","不得玄暉同指點，天涯蒼翠漫青青。"]', '["曦輪初轉照仙扃，旋擘煙嵐上窅冥。","不得玄暉同指点，天涯蒼翠漫青青。"]', '诗', 'shi', '', NULL, '斛石山曉望寄呂侍御 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19c4c25f-5ace-4ebb-8d34-504675b0c861', '寄詞', '寄词', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["菌閣芝樓杳靄中，霞開深見玉皇宮。","紫陽天上神仙客，稱在人間立世功。"]', '["菌閣芝楼杳靄中，霞开深见玉皇宮。","紫陽天上神仙客，稱在人间立世功。"]', '诗', 'shi', '', NULL, '寄詞 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca5e068-b221-4b91-92a2-2dc481d2e35d', '斛石山書事', '斛石山书事', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["王家山水畫圖中，意思都盧粉墨容。","今日忽登虛境望，步搖冠翠一千峰。"]', '["王家山水畫圖中，意思都盧粉墨容。","今日忽登虛境望，步搖冠翠一千峰。"]', '诗', 'shi', '', NULL, '斛石山書事 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e12c4687-92f8-4a9c-a14b-8b93f363a0bd', '送姚員外', '送姚員外', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["萬條江柳早秋枝，褭地翻風色未衰。","欲折爾來將贈別，莫教煙月兩鄉悲。"]', '["万條江柳早秋枝，褭地翻风色未衰。","欲折爾来將贈別，莫教煙月兩乡悲。"]', '诗', 'shi', '', NULL, '送姚員外 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd3b2ad-799e-4022-a5cb-b29301708a6c', '酬祝十三秀才', '酬祝十三秀才', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["浩思藍山玉彩寒，冰囊敲碎楚金盤。","詩家利器馳聲久，何用春闈榜下看。"]', '["浩思藍山玉彩寒，冰囊敲碎楚金盤。","诗家利器驰声久，何用春闈榜下看。"]', '诗', 'shi', '', NULL, '酬祝十三秀才 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('713a1437-0601-4eb6-8510-1d7947e0d1de', '別李郎中', '別李郎中', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["花落梧桐鳳別凰，想登秦嶺更淒涼。","安仁縱有詩將賦，一半音詞雜悼亡。"]', '["花落梧桐鳳別凰，想登秦嶺更淒涼。","安仁縱有诗將賦，一半音词杂悼亡。"]', '诗', 'shi', '', NULL, '別李郎中 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81bdd5e0-703b-4d03-a551-095e06db5cdd', '送扶鍊師', '送扶鍊師', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["錦浦歸舟巫峽雲，綠波迢遞雨紛紛。","山陰妙術人傳久，也說將鵝與右軍。"]', '["錦浦归舟巫峽云，綠波迢遞雨紛紛。","山陰妙術人傳久，也说將鵝與右軍。"]', '诗', 'shi', '', NULL, '送扶鍊師 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2311e4-4768-48bc-a248-80e220b3b242', '摩訶池贈蕭中丞', '摩訶池贈蕭中丞', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["昔以多能佐碧油，今朝同泛舊仙舟。","淒涼逝水頹波遠，惟有碑泉咽不流。"]', '["昔以多能佐碧油，今朝同泛旧仙舟。","淒涼逝水頹波远，惟有碑泉咽不流。"]', '诗', 'shi', '', NULL, '摩訶池贈蕭中丞 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535b6610-e796-4b21-a230-c6f5abfc6e28', '鄉思', '乡思', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["峨嵋山下水如油，憐我心同不繫舟。","何日片帆離錦浦，櫂聲齊唱發中流。"]', '["峨嵋山下水如油，怜我心同不繫舟。","何日片帆離錦浦，櫂声齊唱發中流。"]', '诗', 'shi', '', NULL, '鄉思 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5729c9-fa9e-4f1c-931e-9e17e294b5f7', '和李書記席上見贈', '和李书記席上见贈', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["翩翩射策東堂秀，豈復相逢豁寸心。","借問風光爲誰麗，萬條絲柳翠煙深。"]', '["翩翩射策东堂秀，豈复相逢豁寸心。","借问风光爲誰丽，万條絲柳翠煙深。"]', '诗', 'shi', '', NULL, '和李書記席上見贈 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26cd7866-5191-4331-9520-3c807474298f', '棠梨花和李太尉', '棠梨花和李太尉', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["吳均蕙圃移嘉木，正及東溪春雨時。","日晚鶯啼何所爲，淺深紅膩壓繁枝。"]', '["吳均蕙圃移嘉木，正及东溪春雨时。","日晚鶯啼何所爲，淺深紅膩壓繁枝。"]', '诗', 'shi', '', NULL, '棠梨花和李太尉 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28090090-0e50-408b-a508-3a6331892547', '酬文使君', '酬文使君', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["延英曉拜漢恩新，五馬騰驤九陌塵。","今日謝庭飛白雪，巴歌不復舊陽春。"]', '["延英晓拜漢恩新，五马腾驤九陌塵。","今日謝庭飞白雪，巴歌不复旧陽春。"]', '诗', 'shi', '', NULL, '酬文使君 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2891ea6-48d2-4ea9-b2bd-05f58770bce2', '酬吳隨君', '酬吳隨君', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["支公別墅接花扃，買得前山總未經。","入戶剡溪雲水滿，高齋咫尺躡青冥。"]', '["支公別墅接花扃，買得前山總未經。","入戶剡溪云水满，高斋咫尺躡青冥。"]', '诗', 'shi', '', NULL, '酬吳隨君 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c94ed6-986b-41e5-9437-99fd35753e1d', '酬李校書', '酬李校书', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["才遊象外身雖遠，學茂區中事易聞。","自顧漳濱多病後，空瞻逸翮舞青雲。"]', '["才游象外身雖远，学茂區中事易闻。","自顧漳濱多病後，空瞻逸翮舞青云。"]', '诗', 'shi', '', NULL, '酬李校書 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38947faa-d589-4c82-b78f-ff1de44e8df0', '賦凌雲寺二首 一', '賦凌云寺二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["聞說凌雲寺裏苔，風高日近絕纖埃。","橫雲點染芙蓉壁，似待詩人寶月來。"]', '["闻说凌云寺裏苔，风高日近絕纖埃。","橫云点染芙蓉壁，似待诗人寶月来。"]', '诗', 'shi', '', NULL, '賦凌雲寺二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c2d1cd8-d6f7-4c04-b789-8a630e4b8583', '賦凌雲寺二首 二', '賦凌云寺二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["聞說凌雲寺裏花，飛空遶磴逐江斜。","有時鎖得嫦娥鏡，鏤出瑤臺五色霞。"]', '["闻说凌云寺裏花，飞空遶磴逐江斜。","有时鎖得嫦娥镜，鏤出瑤台五色霞。"]', '诗', 'shi', '', NULL, '賦凌雲寺二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df33476-3c43-4053-b46e-ee3f7f52c0fc', '九日遇雨二首 一', '九日遇雨二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["萬里驚飆朔氣深，江城蕭索晝陰陰。","誰憐不得登山去，可惜寒芳色似金。"]', '["万里驚飆朔氣深，江城蕭索晝陰陰。","誰怜不得登山去，可惜寒芳色似金。"]', '诗', 'shi', '', NULL, '九日遇雨二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b131922b-a3ec-4539-85df-4ed83475363d', '九日遇雨二首 二', '九日遇雨二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["茱萸秋節佳期阻，金菊寒花滿院香。","神女欲來知有意，先令雲雨暗池塘。"]', '["茱萸秋節佳期阻，金菊寒花满院香。","神女欲来知有意，先令云雨暗池塘。"]', '诗', 'shi', '', NULL, '九日遇雨二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50368ce3-8d6a-497b-a856-64838d3dc491', '酬雍秀才貽巴峽圖', '酬雍秀才貽巴峽圖', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["千疊雲峰萬頃湖，白波分去遶荆吳。","感君識我枕流意，重示瞿塘峽口圖。"]', '["千叠云峰万頃湖，白波分去遶荆吳。","感君識我枕流意，重示瞿塘峽口圖。"]', '诗', 'shi', '', NULL, '酬雍秀才貽巴峽圖 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60872f3c-0942-424e-a3bb-e7eeaecf9e4f', '上王尚書', '上王尚书', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["碧玉雙幢白玉郎，初辭天帝下扶桑。","手持雲篆題新榜，十萬人家春日長。"]', '["碧玉雙幢白玉郎，初辞天帝下扶桑。","手持云篆題新榜，十万人家春日长。"]', '诗', 'shi', '', NULL, '上王尚書 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f8512b-c003-4168-88c4-bd1d9b7f49d2', '和劉賓客玉蕣', '和劉賓客玉蕣', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["瓊枝的皪露珊珊，欲折如披玉彩寒。","閑拂朱房何所似，緣山偏映月輪殘。"]', '["瓊枝的皪露珊珊，欲折如披玉彩寒。","闲拂朱房何所似，緣山偏映月輪殘。"]', '诗', 'shi', '', NULL, '和劉賓客玉蕣 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eae159e2-a804-4d26-bf85-2433e848e756', '江邊', '江邊', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["西風忽報鴈雙雙，人世心形兩自降。","不爲魚腸有真訣，誰能夢夢立清江。"]', '["西风忽報鴈雙雙，人世心形兩自降。","不爲鱼腸有真訣，誰能梦梦立清江。"]', '诗', 'shi', '', NULL, '江邊 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4943b5-31bd-409a-82be-0d42b26789f7', '送盧員外', '送盧員外', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["玉壘山前風雪夜，錦官城外別離魂。","信陵公子如相問，長向夷門感舊恩。"]', '["玉壘山前风雪夜，錦官城外別離魂。","信陵公子如相问，长向夷门感旧恩。"]', '诗', 'shi', '', NULL, '送盧員外 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('846bf6c9-9bd0-4dbf-9a07-1524a97c223c', '題竹郎廟', '題竹郎廟', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["竹郎廟前多古木，夕陽沈沈山更綠。","何處江村有笛聲，聲聲盡是迎郎曲。"]', '["竹郎廟前多古木，夕陽沈沈山更綠。","何处江村有笛声，声声尽是迎郎曲。"]', '诗', 'shi', '', NULL, '題竹郎廟 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6870c80-a919-4d95-bb3e-92739b06460c', '贈蘇十三中丞', '贈蘇十三中丞', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["洛陽陌上埋輪氣，欲逐秋空擊隼飛。","今日芝泥檢徵詔，別須臺外振霜威。"]', '["洛陽陌上埋輪氣，欲逐秋空擊隼飞。","今日芝泥檢徵詔，別須台外振霜威。"]', '诗', 'shi', '', NULL, '贈蘇十三中丞 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d05c01e-6d35-4b3f-9c2a-28e4d789befa', '和郭員外題萬里橋', '和郭員外題万里橋', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["萬里橋頭獨越吟，知憑文字寫愁心。","細侯風韻兼前事，不止爲舟也作霖。"]', '["万里橋头独越吟，知憑文字寫愁心。","細侯风韻兼前事，不止爲舟也作霖。"]', '诗', 'shi', '', NULL, '和郭員外題萬里橋 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd76601-8d83-4568-a74b-e21d09e8aa6a', '送鄭眉州', '送鄭眉州', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["雨暗眉山江水流，離人掩袂立高樓。","雙旌千騎駢東陌，獨有羅敷望上頭。"]', '["雨暗眉山江水流，離人掩袂立高楼。","雙旌千騎駢东陌，独有羅敷望上头。"]', '诗', 'shi', '', NULL, '送鄭眉州 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb7146a-2632-4fa0-aa9c-0eb2729fbf99', '江亭餞別', '江亭餞別', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["綠沼紅泥物象幽，范汪兼倅李幷州。","離亭急管四更後，不見公車心獨愁。"]', '["綠沼紅泥物象幽，范汪兼倅李幷州。","離亭急管四更後，不见公车心独愁。"]', '诗', 'shi', '', NULL, '江亭餞別 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595583d9-8ccf-44a4-8019-f9d7e8c11819', '海棠溪', '海棠溪', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["春教風景駐仙霞，水面魚身總帶花。","人世不思靈卉異，競將紅纈染輕沙。"]', '["春教风景駐仙霞，水面鱼身總带花。","人世不思靈卉異，競將紅纈染轻沙。"]', '诗', 'shi', '', NULL, '海棠溪 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee01c2b5-2eeb-40bb-9a3b-26cb5367ff5b', '採蓮舟', '採蓮舟', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["風前一葉壓荷蕖，解報新秋又得魚。","兔走烏馳人語靜，滿溪紅袂櫂歌初。"]', '["风前一葉壓荷蕖，解報新秋又得鱼。","兔走烏驰人語静，满溪紅袂櫂歌初。"]', '诗', 'shi', '', NULL, '採蓮舟 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dffc7b9-42cb-459f-9afe-1a8630844614', '菱荇沼', '菱荇沼', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["水荇斜牽綠藻浮，柳絲和葉臥清流。","何時得向溪頭賞，旋摘菱花旋泛舟。"]', '["水荇斜牽綠藻浮，柳絲和葉臥清流。","何时得向溪头賞，旋摘菱花旋泛舟。"]', '诗', 'shi', '', NULL, '菱荇沼 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e47d76c7-ec62-4d0b-a2c4-f05dde780231', '金燈花', '金灯花', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["闌邊不見蘘蘘葉，砌下惟翻豔豔叢。","細視欲將何物比，曉霞初疊赤城宮。"]', '["闌邊不见蘘蘘葉，砌下惟翻豔豔叢。","細視欲將何物比，晓霞初叠赤城宮。"]', '诗', 'shi', '', NULL, '金燈花 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe019a5-0399-42cf-9c0d-0329592ed69e', '春郊遊眺寄孫處士二首 一', '春郊游眺寄孫处士二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["低頭久立向薔薇，愛似零陵香惹衣。","何事碧溪孫處士，百勞東去燕西飛。"]', '["低头久立向薔薇，愛似零陵香惹衣。","何事碧溪孫处士，百勞东去燕西飞。"]', '诗', 'shi', '', NULL, '春郊遊眺寄孫處士二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e764994-32ff-42f0-93dc-7abbc59c7fd8', '春郊遊眺寄孫處士二首 二', '春郊游眺寄孫处士二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["今朝縱目翫芳菲，夾纈籠裙繡地衣。","滿袖滿頭兼手把，教人識是看花歸。"]', '["今朝縱目翫芳菲，夾纈籠裙繡地衣。","满袖满头兼手把，教人識是看花归。"]', '诗', 'shi', '', NULL, '春郊遊眺寄孫處士二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d8bba0-da21-4d1d-9d43-4f93a3f96959', '酬楊供奉法師見招', '酬楊供奉法師见招', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["遠水長流潔復清，雪窗高臥與雲平。","不嫌袁室無煙火，惟笑商山有姓名。"]', '["远水长流潔复清，雪窗高臥與云平。","不嫌袁室無煙火，惟笑商山有姓名。"]', '诗', 'shi', '', NULL, '酬楊供奉法師見招 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56772e5f-c516-4092-9a57-c62f92e859b3', '試新服裁製初成三首 一', '試新服裁製初成三首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["紫陽宮裏賜紅綃，仙霧朦朧隔海遙。","霜兔毳寒冰繭淨，嫦娥笑指織星橋。"]', '["紫陽宮裏賜紅綃，仙霧朦朧隔海遙。","霜兔毳寒冰繭淨，嫦娥笑指织星橋。"]', '诗', 'shi', '', NULL, '試新服裁製初成三首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b94cb95-43b5-49e9-8bfa-1020257544c4', '試新服裁製初成三首 二', '試新服裁製初成三首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["九氣分爲九色霞，五靈仙馭五雲車。","春風因過東君舍，偷樣人間染百花。"]', '["九氣分爲九色霞，五靈仙馭五云车。","春风因過东君舍，偷樣人间染百花。"]', '诗', 'shi', '', NULL, '試新服裁製初成三首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2354c6c0-ba88-480a-9fe4-3d62146d5995', '試新服裁製初成三首 三', '試新服裁製初成三首 三', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["長裾本是上清儀，曾逐羣仙把玉芝。","每到宮中歌舞會，折腰齊唱步虛詞。"]', '["长裾本是上清儀，曾逐羣仙把玉芝。","每到宮中歌舞會，折腰齊唱步虛词。"]', '诗', 'shi', '', NULL, '試新服裁製初成三首 三 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5d85eb-eb61-446d-8eea-0969b5787d69', '寄張元夫', '寄張元夫', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["前溪獨立後溪行，鷺識朱衣自不驚。","借問人間愁寂意，伯牙弦絕已無聲。"]', '["前溪独立後溪行，鷺識朱衣自不驚。","借问人间愁寂意，伯牙弦絕已無声。"]', '诗', 'shi', '', NULL, '寄張元夫 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54378e9d-6b28-436a-aec7-c270c3550e0e', '酬辛員外折花見遺', '酬辛員外折花见遺', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["青鳥東飛正落梅，銜花滿口下瑤臺。","一枝爲授殷勤意，把向風前旋旋開。"]', '["青鸟东飞正落梅，銜花满口下瑤台。","一枝爲授殷勤意，把向风前旋旋开。"]', '诗', 'shi', '', NULL, '酬辛員外折花見遺 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1caf8ee7-8aad-4b43-9f08-124c35369875', '贈遠二首 一', '贈远二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["芙蓉新落蜀山秋，錦字開緘到是愁。","閨閣不知戎馬事，月高還上望夫樓。"]', '["芙蓉新落蜀山秋，錦字开緘到是愁。","閨閣不知戎马事，月高還上望夫楼。"]', '诗', 'shi', '', NULL, '贈遠二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d99e6d2-1637-43d6-840e-730704032114', '贈遠二首 二', '贈远二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["擾弱新蒲葉又齊，春深花落塞前溪。","知君未轉秦關騎，月照千門掩袖啼。"]', '["擾弱新蒲葉又齊，春深花落塞前溪。","知君未轉秦关騎，月照千门掩袖啼。"]', '诗', 'shi', '', NULL, '贈遠二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87f04dd-4dea-4274-abc3-4f53da494a58', '秋泉', '秋泉', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["冷色初澄一帶煙，幽聲遙瀉十絲弦。","長來枕上牽情思，不使愁人半夜眠。"]', '["冷色初澄一带煙，幽声遙瀉十絲弦。","长来枕上牽情思，不使愁人半夜眠。"]', '诗', 'shi', '', NULL, '秋泉 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6f3cf07-5f0f-4a52-8234-021dfe64a58e', '柳絮', '柳絮', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["二月楊花輕復微，春風搖蕩惹人衣。","他家本是無情物，一任南飛又北飛。"]', '["二月楊花轻复微，春风搖蕩惹人衣。","他家本是無情物，一任南飞又北飞。"]', '诗', 'shi', '', NULL, '柳絮 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e61e16-6dc4-442e-b776-fee363979578', '續嘉陵驛詩獻武相國', '續嘉陵驛诗獻武相国', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["蜀門西更上青天，強爲公歌蜀國弦。","卓氏長卿稱士女，錦江玉壘獻山川。"]', '["蜀门西更上青天，強爲公歌蜀国弦。","卓氏长卿稱士女，錦江玉壘獻山川。"]', '诗', 'shi', '', NULL, '續嘉陵驛詩獻武相國 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc58b7c-45e8-4ba5-b70f-655885433cc9', '段相國遊武擔寺病不能從題寄', '段相国游武擔寺病不能從題寄', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["消瘦翻堪見令公，落花無那恨東風。","儂心猶道青春在，羞看飛蓬石鏡中。"]', '["消瘦翻堪见令公，落花無那恨东风。","儂心猶道青春在，羞看飞蓬石镜中。"]', '诗', 'shi', '', NULL, '段相國遊武擔寺病不能從題寄 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbea22bb-e2b3-4cb3-baab-55f91144a159', '贈段校書', '贈段校书', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["公子翩翩說校書，玉弓金勒紫綃裾。","玄成莫便驕名譽，文采風流定不如。"]', '["公子翩翩说校书，玉弓金勒紫綃裾。","玄成莫便驕名譽，文采风流定不如。"]', '诗', 'shi', '', NULL, '贈段校書 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56319d20-e3fc-46fe-9ec8-e0ab1100f013', '十離詩 犬離主', '十離诗 犬離主', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["馴擾朱門四五年，毛香足淨主人憐。","無端咬著親情客，不得紅絲毯上眠。"]', '["馴擾朱门四五年，毛香足淨主人怜。","無端咬著親情客，不得紅絲毯上眠。"]', '诗', 'shi', '', NULL, '十離詩 犬離主 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('137c03fc-4837-4508-9f83-6fde20ca0721', '十離詩 筆離手', '十離诗 笔離手', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["越管宣毫始稱情，紅箋紙上撒花瓊。","都緣用久鋒頭盡，不得羲之手裏擎。"]', '["越管宣毫始稱情，紅箋紙上撒花瓊。","都緣用久鋒头尽，不得羲之手裏擎。"]', '诗', 'shi', '', NULL, '十離詩 筆離手 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('038324a3-80a3-4127-9c47-f5967f5784be', '十離詩 馬離廐', '十離诗 马離廐', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["雪耳紅毛淺碧蹄，追風曾到日東西。","爲驚玉貌郎君墜，不得華軒更一嘶。"]', '["雪耳紅毛淺碧蹄，追风曾到日东西。","爲驚玉貌郎君墜，不得华軒更一嘶。"]', '诗', 'shi', '', NULL, '十離詩 馬離廐 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf202f23-9e0f-476a-b478-1a05a2fc85d0', '十離詩 鸚鵡離籠', '十離诗 鸚鵡離籠', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["隴西獨自一孤身，飛去飛來上錦茵。","都緣出語無方便，不得籠中再喚人。"]', '["隴西独自一孤身，飞去飞来上錦茵。","都緣出語無方便，不得籠中再喚人。"]', '诗', 'shi', '', NULL, '十離詩 鸚鵡離籠 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db1f510a-cc7a-4717-83d0-a6579e6fa78b', '十離詩 燕離巢', '十離诗 燕離巢', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["出入朱門未忍拋，主人常愛語交交。","銜泥穢汚珊瑚枕，不得梁間更壘巢。"]', '["出入朱门未忍拋，主人常愛語交交。","銜泥穢汚珊瑚枕，不得梁间更壘巢。"]', '诗', 'shi', '', NULL, '十離詩 燕離巢 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb9b455-96ce-40dd-b844-40c3eff39445', '十離詩 珠離掌', '十離诗 珠離掌', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["皎潔圓明內外通，清光似照水晶宮。","只緣一點玷相穢，不得終宵在掌中。"]', '["皎潔圓明內外通，清光似照水晶宮。","只緣一点玷相穢，不得終宵在掌中。"]', '诗', 'shi', '', NULL, '十離詩 珠離掌 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f14df4-0dbb-4ccd-99f7-69f4c67f7d09', '十離詩 魚離池', '十離诗 鱼離池', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["跳躍深池四五秋，常搖朱尾弄綸鉤。","無端擺斷芙蓉朵，不得清波更一遊。"]', '["跳躍深池四五秋，常搖朱尾弄綸鉤。","無端擺斷芙蓉朵，不得清波更一游。"]', '诗', 'shi', '', NULL, '十離詩 魚離池 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea3902e-f875-4197-a611-256d74419476', '十離詩 魚離池', '十離诗 鱼離池', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["戲躍蓮池四五秋，常揺朱尾弄銀鈎。","無緣擺罷芙蓉朶，不得清波更一遊。"]', '["戲躍蓮池四五秋，常揺朱尾弄銀鈎。","無緣擺罷芙蓉朶，不得清波更一游。"]', '诗', 'shi', '', NULL, '十離詩 魚離池 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b89e56-bc2a-40d2-a5bd-18ac58ce688d', '十離詩 鷹離鞲', '十離诗 鷹離鞲', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["爪利如鋒眼似鈴，平原捉兔稱高情。","無端竄向青雲外，不得君王臂上擎。"]', '["爪利如鋒眼似鈴，平原捉兔稱高情。","無端竄向青云外，不得君王臂上擎。"]', '诗', 'shi', '', NULL, '十離詩 鷹離鞲 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75d1604c-46e7-446e-81db-70d01702c830', '十離詩 竹離亭', '十離诗 竹離亭', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["蓊鬱新栽四五行，常將勁節負秋霜。","爲緣春筍鑽墻破，不得垂陰覆玉堂。"]', '["蓊鬱新栽四五行，常將勁節負秋霜。","爲緣春筍鑽墻破，不得垂陰覆玉堂。"]', '诗', 'shi', '', NULL, '十離詩 竹離亭 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a65df373-13a1-4910-a348-7f0e987275c6', '十離詩 鏡離臺', '十離诗 镜離台', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["鑄瀉黃金鏡始開，初生三五月裴回。","爲遭無限塵蒙蔽，不得華堂上玉臺。"]', '["鑄瀉黄金镜始开，初生三五月裴回。","爲遭無限塵蒙蔽，不得华堂上玉台。"]', '诗', 'shi', '', NULL, '十離詩 鏡離臺 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105c5d0c-4f32-4dec-b127-eb4a748d2f63', '酬杜舍人', '酬杜舍人', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["雙魚底事到儂家，撲手新詩片片霞。","唱到白蘋洲畔曲，芙蓉空老蜀江花。"]', '["雙鱼底事到儂家，撲手新诗片片霞。","唱到白蘋洲畔曲，芙蓉空老蜀江花。"]', '诗', 'shi', '', NULL, '酬杜舍人 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50bf921e-d496-4e51-a962-87553ae33706', '籌邊樓', '籌邊楼', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["平臨雲鳥八窗秋，壯壓西川四十州。","諸將莫貪羌族馬，最高層處見邊頭。"]', '["平臨云鸟八窗秋，壯壓西川四十州。","諸將莫貪羌族马，最高層处见邊头。"]', '诗', 'shi', '', NULL, '籌邊樓 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c06078e-4c2e-4a17-bee2-08c69dc6003c', '贈韋校書', '贈韋校书', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["芸香誤比荆山玉，那似登科甲乙年。","澹地鮮風將綺思，飄花散蕊媚青天。"]', '["芸香誤比荆山玉，那似登科甲乙年。","澹地鲜风將綺思，飄花散蕊媚青天。"]', '诗', 'shi', '', NULL, '贈韋校書 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba93597-f20c-4723-a7ee-fb6720ea164b', '江月樓', '江月楼', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["秋風彷彿吳江冷，鷗鷺參差夕陽影。","垂虹納納臥譙門，雉堞眈眈俯漁艇。","陽安小兒拍手笑，使君幻出江南景。"]', '["秋风彷彿吳江冷，鷗鷺參差夕陽影。","垂虹納納臥譙门，雉堞眈眈俯漁艇。","陽安小兒拍手笑，使君幻出江南景。"]', '诗', 'shi', '', NULL, '江月樓 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458cf11a-4c09-46c7-88ef-cc2207274c92', '西巖', '西巖', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["凭闌却憶騎鯨客，把酒臨風手自招。","細雨聲中停去馬，夕陽影裏亂鳴蜩。"]', '["凭闌却憶騎鯨客，把酒臨风手自招。","細雨声中停去马，夕陽影裏亂鳴蜩。"]', '诗', 'shi', '', NULL, '西巖 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b247cf1d-ce88-4d8b-a45c-70b79c873457', '罰赴邊上武相公二首 一', '罰赴邊上武相公二首 一', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["螢在荒蕪月在天，螢飛豈到月輪邊。","重光萬里應相照，目斷雲霄信不傳。"]', '["螢在荒蕪月在天，螢飞豈到月輪邊。","重光万里應相照，目斷云霄信不傳。"]', '诗', 'shi', '', NULL, '罰赴邊上武相公二首 一 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22d6f83-4ec4-471a-9c1c-9414be712b97', '罰赴邊上武相公二首 二', '罰赴邊上武相公二首 二', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["按轡嶺頭寒復寒，微風細雨徹心肝。","但得放兒歸舍去，山水屏風永不看。"]', '["按轡嶺头寒复寒，微风細雨徹心肝。","但得放兒归舍去，山水屏风永不看。"]', '诗', 'shi', '', NULL, '罰赴邊上武相公二首 二 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e034923b-7a90-4b47-95f5-ef38508ad2d8', '寄舊詩與元微之', '寄旧诗與元微之', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["詩篇調態人皆有，細膩風光我獨知。","月下詠花憐暗澹，雨朝題柳爲欹垂。","長教碧玉藏深處，總向紅牋寫自隨。","老大不能收拾得，與君開似教男兒。"]', '["诗篇調態人皆有，細膩风光我独知。","月下詠花怜暗澹，雨朝題柳爲欹垂。","长教碧玉藏深处，總向紅牋寫自隨。","老大不能收拾得，與君开似教男兒。"]', '诗', 'shi', '', NULL, '寄舊詩與元微之 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('464e00a8-aebe-4dec-88a3-0c3bad290f7a', '句', '句', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["枝迎南北鳥，葉送往來風。"]', '["枝迎南北鸟，葉送往来风。"]', '诗', 'shi', '', NULL, '句 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af2e957f-d736-40f6-87aa-69883b6b7fcb', '賦得江邊柳', '賦得江邊柳', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["翠色連荒岸，煙姿入遠樓。","影鋪秋水面，花落釣人頭。","根老藏魚窟，枝低繫客舟。","蕭蕭風雨夜，驚夢復添愁。"]', '["翠色連荒岸，煙姿入远楼。","影鋪秋水面，花落釣人头。","根老藏鱼窟，枝低繫客舟。","蕭蕭风雨夜，驚梦复添愁。"]', '诗', 'shi', '', NULL, '賦得江邊柳 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218696ee-228c-4a50-905f-93801105dd89', '贈鄰女', '贈鄰女', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["羞日遮羅袖，愁春嬾起妝。","易求無價寶，難得有心郎。","枕上潛垂淚，花間暗斷腸。","自能窺宋玉，何必恨王昌。"]', '["羞日遮羅袖，愁春嬾起妝。","易求無價寶，难得有心郎。","枕上潛垂泪，花间暗斷腸。","自能窺宋玉，何必恨王昌。"]', '诗', 'shi', '', NULL, '贈鄰女 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa530a1-62c1-4f0d-8812-383d63a5ab09', '寄國香', '寄国香', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["旦夕醉吟身，相思又此春。","雨中寄書使，窗下斷腸人。","山捲珠簾看，愁隨芳草新。","別來清宴上，幾度落梁塵。"]', '["旦夕醉吟身，相思又此春。","雨中寄书使，窗下斷腸人。","山捲珠簾看，愁隨芳草新。","別来清宴上，幾度落梁塵。"]', '诗', 'shi', '', NULL, '寄國香 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9c2e57-adfe-4167-b1dd-856ece58cc89', '寄題鍊師', '寄題鍊師', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["霞彩翦爲衣，添香出繡幃。","芙蓉花葉□，山水帔□稀。","駐履聞鶯語，開籠放鶴飛。","高堂春睡覺，暮雨正霏霏。"]', '["霞彩翦爲衣，添香出繡幃。","芙蓉花葉□，山水帔□稀。","駐履闻鶯語，开籠放鹤飞。","高堂春睡覺，暮雨正霏霏。"]', '诗', 'shi', '', NULL, '寄題鍊師 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03776353-346e-4356-a77a-e88cefbe94f9', '寄劉尚書', '寄劉尚书', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["八座鎮雄軍，歌謠滿路新。","汾川三月雨，晉水百花春。","囹圄長空鎖，干戈久覆塵。","儒僧觀子夜，羈客醉紅茵。","筆硯行隨手，詩書坐繞身。","小材多顧盼，得作食魚人。"]', '["八座鎮雄軍，歌謠满路新。","汾川三月雨，晉水百花春。","囹圄长空鎖，干戈久覆塵。","儒僧观子夜，羈客醉紅茵。","笔硯行隨手，诗书坐繞身。","小材多顧盼，得作食鱼人。"]', '诗', 'shi', '', NULL, '寄劉尚書 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9e1e6f-4d38-4d21-aca4-89aa3f9dc492', '浣紗廟', '浣紗廟', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["吳越相謀計策多，浣紗神女已相和。","一雙笑靨纔回面，十萬精兵盡倒戈。","范蠡功成身隱遯，伍胥諫死國消磨。","只今諸暨長江畔，空有青山號苧蘿。"]', '["吳越相謀計策多，浣紗神女已相和。","一雙笑靨纔回面，十万精兵尽倒戈。","范蠡功成身隐遯，伍胥諫死国消磨。","只今諸暨长江畔，空有青山號苧蘿。"]', '诗', 'shi', '', NULL, '浣紗廟 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2508eb4f-b21a-4021-b4cb-3a6b6faa4372', '賣殘牡丹', '賣殘牡丹', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["臨風興歎落花頻，芳意潛消又一春。","應爲價高人不問，却緣香甚蝶難親。","紅英只稱生宮裏，翠葉那堪染路塵。","及至移根上林苑，王孫方恨買無因。"]', '["臨风兴歎落花頻，芳意潛消又一春。","應爲價高人不问，却緣香甚蝶难親。","紅英只稱生宮裏，翠葉那堪染路塵。","及至移根上林苑，王孫方恨買無因。"]', '诗', 'shi', '', NULL, '賣殘牡丹 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('226575d5-5828-4faa-9b0d-d5f6feea4161', '酬李學士寄簟', '酬李学士寄簟', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["珍簟新鋪翡翠樓，泓澄玉水記方流。","唯應雲扇情相似，同向銀牀恨早秋。"]', '["珍簟新鋪翡翠楼，泓澄玉水記方流。","唯應云扇情相似，同向銀牀恨早秋。"]', '诗', 'shi', '', NULL, '酬李學士寄簟 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd21d2d-c98a-46ec-a1be-c48ca863ac4c', '情書寄李子安', '情书寄李子安', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["飲冰食蘗志無功，晉水壺關在夢中。","秦鏡欲分愁墮鵲，舜琴將弄怨飛鴻。","井邊桐葉鳴秋雨，窗下銀燈暗曉風。","書信茫茫何處問，持竿盡日碧江空。"]', '["饮冰食蘗志無功，晉水壺关在梦中。","秦镜欲分愁墮鵲，舜琴將弄怨飞鴻。","井邊桐葉鳴秋雨，窗下銀灯暗晓风。","书信茫茫何处问，持竿尽日碧江空。"]', '诗', 'shi', '', NULL, '情書寄李子安 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f36d4e-511e-48fe-8514-127db8b1a2aa', '閨怨', '閨怨', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["蘼蕪盈手泣斜暉，聞道鄰家夫壻歸。","別日南鴻纔北去，今朝北鴈又南飛。","春來秋去相思在，秋去春來信息稀。","扃閉朱門人不到，砧聲何事透羅幃。"]', '["蘼蕪盈手泣斜暉，闻道鄰家夫壻归。","別日南鴻纔北去，今朝北鴈又南飞。","春来秋去相思在，秋去春来信息稀。","扃閉朱门人不到，砧声何事透羅幃。"]', '诗', 'shi', '', NULL, '閨怨 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ed9ddf-27e5-483e-9966-2c304f1c2fa3', '春情寄子安', '春情寄子安', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["山路敧斜石磴危，不愁行苦苦相思。","冰銷遠磵憐清韻，雪遠寒峰想玉姿。","莫聽凡歌春病酒，休招閑客夜貪棊。","如松匪石盟長在，比翼連襟會肯遲。","雖恨獨行冬盡日，終期相見月圓時。","別君何物堪持贈，淚落晴光一首詩。"]', '["山路敧斜石磴危，不愁行苦苦相思。","冰銷远磵怜清韻，雪远寒峰想玉姿。","莫听凡歌春病酒，休招闲客夜貪棊。","如松匪石盟长在，比翼連襟會肯遲。","雖恨独行冬尽日，終期相见月圓时。","別君何物堪持贈，泪落晴光一首诗。"]', '诗', 'shi', '', NULL, '春情寄子安 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6549f01-c55e-4bbf-8c98-54bdad1abacd', '打毬作', '打毬作', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["堅圓淨滑一星流，月杖爭敲未擬休。","無滯礙時從撥弄，有遮欄處任鉤留。","不辭宛轉長隨手，却恐相將不到頭。","畢竟入門應始了，願君爭取最前籌。"]', '["堅圓淨滑一星流，月杖爭敲未擬休。","無滯礙时從撥弄，有遮欄处任鉤留。","不辞宛轉长隨手，却恐相將不到头。","畢竟入门應始了，願君爭取最前籌。"]', '诗', 'shi', '', NULL, '打毬作 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c476b10-38e2-4ac9-8eb6-37d597c7027f', '暮春有感寄友人', '暮春有感寄友人', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["鶯語驚殘夢，輕妝改淚容。","竹陰初月薄，江靜晚煙濃。","溼觜銜泥燕，香鬚採蕊蜂。","獨憐無限思，吟罷亞枝松。"]', '["鶯語驚殘梦，轻妝改泪容。","竹陰初月薄，江静晚煙濃。","溼觜銜泥燕，香鬚採蕊蜂。","独怜無限思，吟罷亞枝松。"]', '诗', 'shi', '', NULL, '暮春有感寄友人 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e101833b-5d56-435d-9f9f-5863c87e96c2', '冬夜寄溫飛卿', '冬夜寄溫飞卿', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["苦思搜詩燈下吟，不眠長夜怕寒衾。","滿庭木葉愁風起，透幌紗窗惜月沈。","疎散未閑終遂願，盛衰空見本來心。","幽棲莫定梧桐處，暮雀啾啾空繞林。"]', '["苦思搜诗灯下吟，不眠长夜怕寒衾。","满庭木葉愁风起，透幌紗窗惜月沈。","疎散未闲終遂願，盛衰空见本来心。","幽棲莫定梧桐处，暮雀啾啾空繞林。"]', '诗', 'shi', '', NULL, '冬夜寄溫飛卿 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89044e17-bb20-4403-ae27-8cce6c955a78', '酬李郢夏日釣魚回見示', '酬李郢夏日釣鱼回见示', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["住處雖同巷，經年不一過。","清詞勸舊女，香桂折新柯。","道性欺冰雪，禪心笑綺羅。","跡登霄漢上，無路接煙波。"]', '["住处雖同巷，經年不一過。","清词勸旧女，香桂折新柯。","道性欺冰雪，禪心笑綺羅。","跡登霄漢上，無路接煙波。"]', '诗', 'shi', '', NULL, '酬李郢夏日釣魚回見示 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f943da34-6491-4bc4-919a-415a8b841b91', '次韻西鄰新居兼乞酒', '次韻西鄰新居兼乞酒', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["一首詩來百度吟，新情字字又聲金。","西看已有登垣意，遠望能無化石心。","河漢期賒空極目，瀟湘夢斷罷調琴。","況逢寒節添鄉思，叔夜佳醪莫獨斟。"]', '["一首诗来百度吟，新情字字又声金。","西看已有登垣意，远望能無化石心。","河漢期賒空極目，瀟湘梦斷罷調琴。","況逢寒節添乡思，叔夜佳醪莫独斟。"]', '诗', 'shi', '', NULL, '次韻西鄰新居兼乞酒 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bb7e56-9935-4171-83a5-7069c101bb47', '和友人次韻', '和友人次韻', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["何事能銷旅館愁，紅牋開處見銀鉤。","蓬山雨灑千峰小，嶰谷風吹萬葉秋。","字字朝看輕碧玉，篇篇夜誦在衾裯。","欲將香匣收藏却，且惜時吟在手頭。"]', '["何事能銷旅館愁，紅牋开处见銀鉤。","蓬山雨灑千峰小，嶰谷风吹万葉秋。","字字朝看轻碧玉，篇篇夜誦在衾裯。","欲將香匣收藏却，且惜时吟在手头。"]', '诗', 'shi', '', NULL, '和友人次韻 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82023a62-b0b0-4d67-bf07-4ea456ddaca6', '和新及第悼亡詩二首 一', '和新及第悼亡诗二首 一', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["仙籍人間不久留，片時已過十經秋。","鴛鴦帳下香猶暖，鸚鵡籠中語未休。","朝露綴花如臉恨，晚風敧柳似眉愁。","彩雲一去無消息，潘岳多情欲白頭。"]', '["仙籍人间不久留，片时已過十經秋。","鴛鴦帳下香猶暖，鸚鵡籠中語未休。","朝露綴花如臉恨，晚风敧柳似眉愁。","彩云一去無消息，潘岳多情欲白头。"]', '诗', 'shi', '', NULL, '和新及第悼亡詩二首 一 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('111e6d09-6699-449b-bb5b-38608630ab98', '和新及第悼亡詩二首 二', '和新及第悼亡诗二首 二', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["一枝月桂和煙秀，萬樹江桃帶雨紅。","且醉尊前休悵望，古來悲樂與今同。"]', '["一枝月桂和煙秀，万樹江桃带雨紅。","且醉尊前休悵望，古来悲乐與今同。"]', '诗', 'shi', '', NULL, '和新及第悼亡詩二首 二 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178f9489-55b1-4ec4-8de6-ee3bdb0ea1e5', '遊崇真觀南樓覩新及第題名處', '游崇真观南楼覩新及第題名处', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["雲峰滿目放春晴，歷歷銀鉤指下生。","自恨羅衣掩詩句，舉頭空羨榜中名。"]', '["云峰满目放春晴，歷歷銀鉤指下生。","自恨羅衣掩诗句，舉头空羨榜中名。"]', '诗', 'shi', '', NULL, '遊崇真觀南樓覩新及第題名處 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2cc72ba-d62c-48c2-ba5c-b21d0e342b10', '愁思', '愁思', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["落葉紛紛暮雨和，朱絲獨撫自清歌。","放情休恨無心友，養性空拋苦海波。","長者車音門外有，道家書卷枕前多。","布衣終作雲霄客，綠水青山時一過。"]', '["落葉紛紛暮雨和，朱絲独撫自清歌。","放情休恨無心友，養性空拋苦海波。","长者车音门外有，道家书卷枕前多。","布衣終作云霄客，綠水青山时一過。"]', '诗', 'shi', '', NULL, '愁思 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d394769d-918d-43ea-96f4-a657356fbe3e', '秋怨', '秋怨', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["自歎多情是足愁，況當風月滿庭秋。","洞房偏與更聲近，夜夜燈前欲白頭。"]', '["自歎多情是足愁，況當风月满庭秋。","洞房偏與更声近，夜夜灯前欲白头。"]', '诗', 'shi', '', NULL, '秋怨 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c8cb1d0-293d-4cb7-a2ec-6bd9fcfeb1a5', '江行 一', '江行 一', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["大江橫抱武昌斜，鸚鵡洲前戶萬家。","畫舸春眠朝未足，夢爲蝴蝶也尋花。"]', '["大江橫抱武昌斜，鸚鵡洲前戶万家。","畫舸春眠朝未足，梦爲蝴蝶也尋花。"]', '诗', 'shi', '', NULL, '江行 一 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833614c6-a4f2-4d7f-bb90-6e15f5fb249b', '江行 二', '江行 二', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["煙花已入鸕鷀港，畫舸猶沿鸚鵡洲。","醉臥醒吟都不覺，今朝驚在漢江頭。"]', '["煙花已入鸕鷀港，畫舸猶沿鸚鵡洲。","醉臥醒吟都不覺，今朝驚在漢江头。"]', '诗', 'shi', '', NULL, '江行 二 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bda9a76-7c2f-487c-b8ae-e49add76feb3', '聞李端公垂釣回寄贈', '闻李端公垂釣回寄贈', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["無限荷香染暑衣，阮郎何處弄船歸。","自慙不及鴛鴦侶，猶得雙雙近釣磯。"]', '["無限荷香染暑衣，阮郎何处弄船归。","自慙不及鴛鴦侶，猶得雙雙近釣磯。"]', '诗', 'shi', '', NULL, '聞李端公垂釣回寄贈 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b64c2a-96b3-424d-96da-a0f08bdff52a', '題任處士刱資福寺', '題任处士刱資福寺', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["幽人刱奇境，遊客駐行程。","粉壁空留字，蓮宮未有名。","鑿池泉自出，開徑草重生。","百尺金輪閣，當川豁眼明。"]', '["幽人刱奇境，游客駐行程。","粉壁空留字，蓮宮未有名。","鑿池泉自出，开徑草重生。","百尺金輪閣，當川豁眼明。"]', '诗', 'shi', '', NULL, '題任處士刱資福寺 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff2b9581-24f6-4323-8a44-822132ad4660', '題隱霧亭', '題隐霧亭', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["春花秋月入詩篇，白日清宵是散仙。","空捲珠簾不曾下，長移一榻對山眠。"]', '["春花秋月入诗篇，白日清宵是散仙。","空捲珠簾不曾下，长移一榻对山眠。"]', '诗', 'shi', '', NULL, '題隱霧亭 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf84d377-0e3d-4b16-9a28-0e5c632804c5', '重陽阻雨', '重陽阻雨', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["滿庭黃菊籬邊拆，兩朵芙蓉鏡裏開。","落帽臺前風雨阻，不知何處醉金杯。"]', '["满庭黄菊籬邊拆，兩朵芙蓉镜裏开。","落帽台前风雨阻，不知何处醉金杯。"]', '诗', 'shi', '', NULL, '重陽阻雨 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37e227dd-a924-4b33-b9c4-f48e7bf7a173', '早秋', '早秋', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["嫩菊含新彩，遠山閑夕煙。","涼風驚綠樹，清韻入朱弦。","思婦機中錦，征人塞外天。","鴈飛魚在水，書信若爲傳。"]', '["嫩菊含新彩，远山闲夕煙。","涼风驚綠樹，清韻入朱弦。","思婦機中錦，征人塞外天。","鴈飞鱼在水，书信若爲傳。"]', '诗', 'shi', '', NULL, '早秋 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c13506de-d6e2-4ff3-a3da-722337baa3a3', '感懷寄人', '感懷寄人', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["恨寄朱弦上，含情意不任。","早知雲雨會，未起蕙蘭心。","灼灼桃兼李，無妨國士尋。","蒼蒼松與桂，仍羨世人欽。","月色苔階淨，歌聲竹院深。","門前紅葉地，不埽待知音。"]', '["恨寄朱弦上，含情意不任。","早知云雨會，未起蕙蘭心。","灼灼桃兼李，無妨国士尋。","蒼蒼松與桂，仍羨世人欽。","月色苔階淨，歌声竹院深。","门前紅葉地，不埽待知音。"]', '诗', 'shi', '', NULL, '感懷寄人 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc9f8d3-f9ea-4a13-8b33-eff4cf03c1bf', '期友人阻雨不至', '期友人阻雨不至', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["鴈魚空有信，雞黍恨無期。","閉戶方籠月，褰簾已散絲。","近泉鳴砌畔，遠浪漲江湄。","鄉思悲秋客，愁吟五字詩。"]', '["鴈鱼空有信，雞黍恨無期。","閉戶方籠月，褰簾已散絲。","近泉鳴砌畔，远浪漲江湄。","乡思悲秋客，愁吟五字诗。"]', '诗', 'shi', '', NULL, '期友人阻雨不至 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e83ef25-9fff-48b2-bf5c-4a5483235e5c', '訪趙鍊師不遇', '訪趙鍊師不遇', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["何處同仙侶，青衣獨在家。","暖爐留煮藥，鄰院爲煎茶。","畫壁燈光暗，幡竿日影斜。","殷勤重回首，牆外數枝花。"]', '["何处同仙侶，青衣独在家。","暖爐留煮藥，鄰院爲煎茶。","畫壁灯光暗，幡竿日影斜。","殷勤重回首，牆外數枝花。"]', '诗', 'shi', '', NULL, '訪趙鍊師不遇 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4bae90-c446-4c04-9cf7-95172b439842', '遣懷', '遣懷', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["閑散身無事，風光獨自遊。","斷雲江上月，解纜海中舟。","琴弄蕭梁寺，詩吟庾亮樓。","叢篁堪作伴，片石好爲儔。","燕雀徒爲貴，金銀志不求。","滿杯春酒綠，對月夜窗幽。","繞砌澄清沼，抽簪映細流。","臥牀書冊徧，半醉起梳頭。"]', '["闲散身無事，风光独自游。","斷云江上月，解纜海中舟。","琴弄蕭梁寺，诗吟庾亮楼。","叢篁堪作伴，片石好爲儔。","燕雀徒爲貴，金銀志不求。","满杯春酒綠，对月夜窗幽。","繞砌澄清沼，抽簪映細流。","臥牀书冊徧，半醉起梳头。"]', '诗', 'shi', '', NULL, '遣懷 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e500339a-7ca1-421d-b666-d64ed98ae380', '寄飛卿', '寄飞卿', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["階砌亂蛩鳴，庭柯煙露清。","月中鄰樂響，樓上遠山明。","珍簟涼風著，瑤琴寄恨生。","嵇君嬾書札，底物慰秋情。"]', '["階砌亂蛩鳴，庭柯煙露清。","月中鄰乐响，楼上远山明。","珍簟涼风著，瑤琴寄恨生。","嵇君嬾书札，底物慰秋情。"]', '诗', 'shi', '', NULL, '寄飛卿 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741cdc44-6aa1-4d1a-97fa-12e7fbe27d88', '過鄂州', '過鄂州', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["柳拂蘭橈花滿枝，石城城下暮帆遲。","折牌峰上三閭墓，遠火山頭五馬旗。","白雪調高題舊寺，陽春歌在喚新詞。","莫愁魂逐清江去，空使行人萬首詩。"]', '["柳拂蘭橈花满枝，石城城下暮帆遲。","折牌峰上三閭墓，远火山头五马旗。","白雪調高題旧寺，陽春歌在喚新词。","莫愁魂逐清江去，空使行人万首诗。"]', '诗', 'shi', '', NULL, '過鄂州 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9867cdce-b967-4b8f-a459-c7c2a28b2d5b', '夏日山居', '夏日山居', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["移得仙居此地來，花叢自徧不曾栽。","庭前亞樹張衣桁，坐上新泉泛酒杯。","軒檻暗傳深竹徑，綺羅長擁亂書堆。","閑乘畫舫吟明月，信任輕風吹却回。"]', '["移得仙居此地来，花叢自徧不曾栽。","庭前亞樹張衣桁，坐上新泉泛酒杯。","軒檻暗傳深竹徑，綺羅长擁亂书堆。","闲乘畫舫吟明月，信任轻风吹却回。"]', '诗', 'shi', '', NULL, '夏日山居 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4435e46e-be32-47fc-8347-03398e3c18e2', '暮春即事', '暮春即事', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["深巷窮門少侶儔，阮郎唯有夢中留。","香飄羅綺誰家席，風送歌聲何處樓。","街近鼓鼙喧曉睡，庭閑鵲語亂春愁。","安能追逐人間事，萬里身同不繫舟。"]', '["深巷窮门少侶儔，阮郎唯有梦中留。","香飄羅綺誰家席，风送歌声何处楼。","街近鼓鼙喧晓睡，庭闲鵲語亂春愁。","安能追逐人间事，万里身同不繫舟。"]', '诗', 'shi', '', NULL, '暮春即事 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3332b84d-4c70-43ad-8f84-da1f6e0c1ef2', '代人悼亡', '代人悼亡', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["曾覩夭桃想玉姿，帶風楊柳認蛾眉。","珠歸龍窟知誰見，鏡在鸞臺話向誰。","從此夢悲煙雨夜，不堪吟苦寂寥時。","西山日落東山月，恨想無因有了期。"]', '["曾覩夭桃想玉姿，带风楊柳認蛾眉。","珠归龙窟知誰见，镜在鸾台話向誰。","從此梦悲煙雨夜，不堪吟苦寂寥时。","西山日落东山月，恨想無因有了期。"]', '诗', 'shi', '', NULL, '代人悼亡 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15dcd0c4-52a0-42de-bdc6-931920f8a3a3', '和人', '和人', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["茫茫九陌無知己，暮去朝來典繡衣。","寶匣鏡昏蟬鬢亂，博山爐暖麝煙微。","多情公子春留句，少思文君晝掩扉。","莫惜羊車頻列載，柳絲梅綻正芳菲。"]', '["茫茫九陌無知己，暮去朝来典繡衣。","寶匣镜昏蟬鬢亂，博山爐暖麝煙微。","多情公子春留句，少思文君晝掩扉。","莫惜羊车頻列載，柳絲梅綻正芳菲。"]', '诗', 'shi', '', NULL, '和人 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1fbe21d-629e-4638-8468-8f5a81467dda', '隔漢江寄子安', '隔漢江寄子安', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["江南江北愁望，相思相憶空吟。","鴛鴦暖臥沙浦，鸂𪆟閑飛橘林。","煙裏歌聲隱隱，渡頭月色沈沈。","含情咫尺千里，況聽家家遠砧。"]', '["江南江北愁望，相思相憶空吟。","鴛鴦暖臥沙浦，鸂𪆟闲飞橘林。","煙裏歌声隐隐，渡头月色沈沈。","含情咫尺千里，況听家家远砧。"]', '诗', 'shi', '', NULL, '隔漢江寄子安 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4142639-29cf-4e88-b506-9e2eb10d0243', '寓言', '寓言', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["紅桃處處春色，碧柳家家月明。","樓上新妝待夜，閨中獨坐含情。","芙蓉月下魚戲，螮蝀天邊雀聲。","人世悲歡一夢，如何得作雙成。"]', '["紅桃处处春色，碧柳家家月明。","楼上新妝待夜，閨中独坐含情。","芙蓉月下鱼戲，螮蝀天邊雀声。","人世悲歡一梦，如何得作雙成。"]', '诗', 'shi', '', NULL, '寓言 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47fdc2ee-45e6-4f4c-a661-257589c5f739', '江陵愁望寄子安', '江陵愁望寄子安', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["楓葉千枝復萬枝，江橋掩映暮帆遲。","憶君心似西江水，日夜東流無歇時。"]', '["楓葉千枝复万枝，江橋掩映暮帆遲。","憶君心似西江水，日夜东流無歇时。"]', '诗', 'shi', '', NULL, '江陵愁望寄子安 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('253849e9-cfff-4a60-86a4-a01d3bc1c494', '寄子安', '寄子安', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["醉別千巵不浣愁，離腸百結解無由。","蕙蘭銷歇歸春圃，楊柳東西絆客舟。","聚散已悲雲不定，恩情須學水長流。","有花時節知難遇，未肯厭厭醉玉樓。"]', '["醉別千巵不浣愁，離腸百結解無由。","蕙蘭銷歇归春圃，楊柳东西絆客舟。","聚散已悲云不定，恩情須学水长流。","有花时節知难遇，未肯厭厭醉玉楼。"]', '诗', 'shi', '', NULL, '寄子安 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60aa9e3-5b13-4265-9116-59747cecf8e0', '送別', '送別', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["秦樓幾夜愜心期，不料仙郎有別離。","睡覺莫言雲去處，殘燈一醆野蛾飛。"]', '["秦楼幾夜愜心期，不料仙郎有別離。","睡覺莫言云去处，殘灯一醆野蛾飞。"]', '诗', 'shi', '', NULL, '送別 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcca1075-392a-4299-8a82-a750fcbaf4cd', '迎李近仁員外', '迎李近仁員外', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["今日喜時聞喜鵲，昨宵燈下拜燈花。","焚香出戶迎潘岳，不羨牽牛織女家。"]', '["今日喜时闻喜鵲，昨宵灯下拜灯花。","焚香出戶迎潘岳，不羨牽牛织女家。"]', '诗', 'shi', '', NULL, '迎李近仁員外 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('962780a7-c4a0-4ce7-ab03-96b957f047a8', '送別', '送別', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["水柔逐器知難定，雲出無心肯再歸。","惆悵春風楚江暮，鴛鴦一隻失羣飛。"]', '["水柔逐器知难定，云出無心肯再归。","惆悵春风楚江暮，鴛鴦一隻失羣飞。"]', '诗', 'shi', '', NULL, '送別 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8a209f-7b1c-4afb-a21d-3cff24520ef5', '左名場自澤州至京使人傳語', '左名場自澤州至京使人傳語', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["閑居作賦幾年愁，王屋山前是舊遊。","詩詠東西千嶂亂，馬隨南北一泉流。","曾陪雨夜同歡席，別後花時獨上樓。","忽喜扣門傳語至，爲憐鄰巷小房幽。","相如琴罷朱弦斷，雙燕巢分白露秋。","莫倦蓬門時一訪，每春忙在曲江頭。"]', '["闲居作賦幾年愁，王屋山前是旧游。","诗詠东西千嶂亂，马隨南北一泉流。","曾陪雨夜同歡席，別後花时独上楼。","忽喜扣门傳語至，爲怜鄰巷小房幽。","相如琴罷朱弦斷，雙燕巢分白露秋。","莫倦蓬门时一訪，每春忙在曲江头。"]', '诗', 'shi', '', NULL, '左名場自澤州至京使人傳語 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c986d783-80bd-450f-bd0c-4c53eed19735', '和人次韻', '和人次韻', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["喧喧朱紫雜人寰，獨自清吟日色間。","何事玉郎搜藻思，忽將瓊韻扣柴關。","白花發詠慙稱謝，僻巷深居謬學顏。","不用多情欲相見，松蘿高處是前山。"]', '["喧喧朱紫杂人寰，独自清吟日色间。","何事玉郎搜藻思，忽將瓊韻扣柴关。","白花發詠慙稱謝，僻巷深居謬学顏。","不用多情欲相见，松蘿高处是前山。"]', '诗', 'shi', '', NULL, '和人次韻 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601cb6a0-7e9c-40e9-861b-0621c997a632', '光威裒姊妹三人少孤而始妍乃有是作精粹難儔雖謝家聯雪何以加之有客自京師來者示予因次其韻', '光威裒姊妹三人少孤而始妍乃有是作精粹难儔雖謝家聯雪何以加之有客自京師来者示予因次其韻', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["昔聞南國容華少，今日東鄰姊妹三。","妝閣相看鸚鵡賦，碧窗應繡鳳凰衫。","紅芳滿院參差折，綠醑盈杯次第銜。","恐向瑤池曾作女，謫來塵世未爲男。","文姬有貌終堪比，西子無言我更慚。","一曲豔歌琴杳杳，四弦輕撥語喃喃。","當臺競鬬青絲髮，對月爭誇白玉簪。","小有洞中松露滴，大羅天上柳煙含。","但能爲雨心長在，不怕吹簫事未諳。","阿母幾嗔花下語，潘郎曾向夢中參。","暫持清句魂猶斷，若覩紅顏死亦甘。","悵望佳人何處在，行雲歸北又歸南。"]', '["昔闻南国容华少，今日东鄰姊妹三。","妝閣相看鸚鵡賦，碧窗應繡鳳凰衫。","紅芳满院參差折，綠醑盈杯次第銜。","恐向瑤池曾作女，謫来塵世未爲男。","文姬有貌終堪比，西子無言我更慚。","一曲豔歌琴杳杳，四弦轻撥語喃喃。","當台競鬬青絲髮，对月爭誇白玉簪。","小有洞中松露滴，大羅天上柳煙含。","但能爲雨心长在，不怕吹簫事未諳。","阿母幾嗔花下語，潘郎曾向梦中參。","暫持清句魂猶斷，若覩紅顏死亦甘。","悵望佳人何处在，行云归北又归南。"]', '诗', 'shi', '', NULL, '光威裒姊妹三人少孤而始妍乃有是作精粹難儔雖謝家聯雪何以加之有客自京師來者示予因次其韻 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c5b8da-ee5a-4b1f-a669-8310c69530eb', '折楊柳', '折楊柳', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["朝朝送別泣花鈿，折盡春風楊柳煙。","願得西山無樹木，免教人作淚懸懸。"]', '["朝朝送別泣花鈿，折尽春风楊柳煙。","願得西山無樹木，免教人作泪懸懸。"]', '诗', 'shi', '', NULL, '折楊柳 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90f3b085-e508-4d80-8d47-b338daca575a', '句', '句', 'fb418daa-72ee-4761-9bff-5415a861ae1e', '唐', '["焚香登玉壇，端簡禮金闕。","明月照幽隙，清風開短襟。","綺陌春望遠，瑤徽春興多。","殷勤不得語，紅淚一雙流。","雲情自鬱爭同夢，仙貌長芳又勝花。"]', '["焚香登玉壇，端簡禮金闕。","明月照幽隙，清风开短襟。","綺陌春望远，瑤徽春兴多。","殷勤不得語，紅泪一雙流。","云情自鬱爭同梦，仙貌长芳又勝花。"]', '诗', 'shi', '', NULL, '句 魚玄機 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf462ca-8b6f-4b86-9858-14b1c62cb7c1', '湖上臥病喜陸鴻漸至', '湖上臥病喜陸鴻漸至', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["昔去繁霜月，今來苦霧時。","相逢仍臥病，欲語淚先垂。","強勸陶家酒，還吟謝客詩。","偶然成一醉，此外更何之。"]', '["昔去繁霜月，今来苦霧时。","相逢仍臥病，欲語泪先垂。","強勸陶家酒，還吟謝客诗。","偶然成一醉，此外更何之。"]', '诗', 'shi', '', NULL, '湖上臥病喜陸鴻漸至 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcc8efe-4fc4-43f3-99bb-ea56e48ffffd', '寄校書七兄', '寄校书七兄', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["無事烏程縣，蹉跎歲月餘。","不知芸閣吏，寂寞竟何如。","遠水浮仙棹，寒星伴使車。","因過大雷岸，莫忘八行書。"]', '["無事烏程縣，蹉跎歲月餘。","不知芸閣吏，寂寞竟何如。","远水浮仙棹，寒星伴使车。","因過大雷岸，莫忘八行书。"]', '诗', 'shi', '', NULL, '寄校書七兄 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c071b26-32b2-40c7-8daa-b3a9de3a0d7a', '寄朱放', '寄朱放', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["望水試登山，山高湖又闊。","相思無曉夕，相望經年月。","鬱鬱山木榮，綿綿野花發。","別後無限情，相逢一時說。"]', '["望水試登山，山高湖又闊。","相思無晓夕，相望經年月。","鬱鬱山木榮，綿綿野花發。","別後無限情，相逢一时说。"]', '诗', 'shi', '', NULL, '寄朱放 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a37c2e-4bf7-47f4-a5b1-d05915432fbf', '送韓揆之江西', '送韓揆之江西', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["相看指楊柳，別恨轉依依。","萬里江西水，孤舟何處歸？","湓城潮不到，夏口信應稀。","唯有衡陽雁，年年來去飛。"]', '["相看指楊柳，別恨轉依依。","万里江西水，孤舟何处归？","湓城潮不到，夏口信應稀。","唯有衡陽雁，年年来去飞。"]', '诗', 'shi', '', NULL, '送韓揆之江西 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff9d01d-966b-4559-90bc-6fe22624c5d0', '道意寄崔侍郎', '道意寄崔侍郎', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["莫漫戀浮名，應須薄宦情。","百年齊旦暮，前事盡虛盈。","愁鬢行看白，童顏學未成。","無過天竺國，依止古先生。"]', '["莫漫戀浮名，應須薄宦情。","百年齊旦暮，前事尽虛盈。","愁鬢行看白，童顏学未成。","無過天竺国，依止古先生。"]', '诗', 'shi', '', NULL, '道意寄崔侍郎 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('956af6b8-a933-4286-9109-25357e8a8ce7', '從蕭叔子聽彈琴賦得三峽流泉歌', '從蕭叔子听彈琴賦得三峽流泉歌', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["妾家本住巫山雲，巫山流泉常自聞。","玉琴彈出轉寥敻，直是當時夢裏聽。","三峽迢迢幾千里，一時流入幽閨裏。","巨石崩崖指下生，飛泉走浪弦中起。","初疑憤怒含雷風，又似嗚咽流不通。","迴湍曲瀨勢將盡，時復滴瀝平沙中。","憶昔阮公爲此曲，能令仲容聽不足。","一彈既罷復一彈，願作流泉鎮相續。"]', '["妾家本住巫山云，巫山流泉常自闻。","玉琴彈出轉寥敻，直是當时梦裏听。","三峽迢迢幾千里，一时流入幽閨裏。","巨石崩崖指下生，飞泉走浪弦中起。","初疑憤怒含雷风，又似嗚咽流不通。","迴湍曲瀨勢將尽，时复滴瀝平沙中。","憶昔阮公爲此曲，能令仲容听不足。","一彈既罷复一彈，願作流泉鎮相續。"]', '诗', 'shi', '', NULL, '從蕭叔子聽彈琴賦得三峽流泉歌 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56311c63-5446-48bc-a3f6-5cefe7b6d87c', '相思怨', '相思怨', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["人道海水深，不抵相思半。","海水尚有涯，相思渺無畔。","攜琴上高樓，樓虛月華滿。","彈著相思曲，弦腸一時斷。"]', '["人道海水深，不抵相思半。","海水尚有涯，相思渺無畔。","携琴上高楼，楼虛月华满。","彈著相思曲，弦腸一时斷。"]', '诗', 'shi', '', NULL, '相思怨 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('851b229b-a506-41b7-94a5-6844f02941a1', '感興', '感兴', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["朝雲暮雨鎮相隨，去雁來人有返期。","玉枕秪知長下淚，銀燈空照不眠時。","仰看明月翻含意，俯眄流波欲寄詞。","却憶初聞鳳樓曲，教人寂寞復相思。"]', '["朝云暮雨鎮相隨，去雁来人有返期。","玉枕秪知长下泪，銀灯空照不眠时。","仰看明月翻含意，俯眄流波欲寄词。","却憶初闻鳳楼曲，教人寂寞复相思。"]', '诗', 'shi', '', NULL, '感興 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb77b561-cadd-4aca-acf4-bf56fd49a533', '恩命追入留別廣陵故人', '恩命追入留別廣陵故人', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["無才多病分龍鍾，不料虛名達九重。","仰媿彈冠上華髮，多慙拂鏡理衰容。","馳心北闕隨芳草，極目南山望舊峰。","桂樹不能留野客，沙鷗出浦謾相逢。"]', '["無才多病分龙鍾，不料虛名達九重。","仰媿彈冠上华髮，多慙拂镜理衰容。","驰心北闕隨芳草，極目南山望旧峰。","桂樹不能留野客，沙鷗出浦謾相逢。"]', '诗', 'shi', '', NULL, '恩命追入留別廣陵故人 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05a09b49-ef3f-428d-ad40-82d739e810a2', '八至', '八至', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["至近至遠東西，至深至淺清溪。","至高至明日月，至親至疎夫妻。"]', '["至近至远东西，至深至淺清溪。","至高至明日月，至親至疎夫妻。"]', '诗', 'shi', '', NULL, '八至 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe1fef2a-a07b-44c0-a7a7-86d1dd3b53a2', '送閻二十六赴剡縣', '送閻二十六赴剡縣', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["流水閶門外，孤舟日復西。","離情遍芳草，無處不萋萋。","妾夢經吳苑，君行到剡溪。","歸來重相訪，莫學阮郎迷。"]', '["流水閶门外，孤舟日复西。","離情遍芳草，無处不萋萋。","妾梦經吳苑，君行到剡溪。","归来重相訪，莫学阮郎迷。"]', '诗', 'shi', '', NULL, '送閻二十六赴剡縣 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf797a72-c763-4fc1-a2da-da2d1f3c0867', '得閻伯鈞書', '得閻伯鈞书', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["情來對鏡嬾梳頭，暮雨蕭蕭庭樹秋。","莫怪闌干垂玉筯，只緣惆悵對銀鉤。"]', '["情来对镜嬾梳头，暮雨蕭蕭庭樹秋。","莫怪闌干垂玉筯，只緣惆悵对銀鉤。"]', '诗', 'shi', '', NULL, '得閻伯鈞書 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8711b7ec-9746-44d6-a00e-cd8b1736d363', '結素魚貽友人', '結素鱼貽友人', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["尺素如殘雪，結爲雙鯉魚。","欲知心裏事，看取腹中書。"]', '["尺素如殘雪，結爲雙鯉鱼。","欲知心裏事，看取腹中书。"]', '诗', 'shi', '', NULL, '結素魚貽友人 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6d75ed-f854-4448-aaf7-b77d85729ad3', '偶居', '偶居', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["心遠浮雲知不還，心雲併在有無間。","狂風何事相搖蕩，吹向南山復北山。"]', '["心远浮云知不還，心云併在有無间。","狂风何事相搖蕩，吹向南山复北山。"]', '诗', 'shi', '', NULL, '偶居 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b30662ff-1491-4933-80f9-f871b20ac43b', '明月夜留別', '明月夜留別', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["離人無語月無聲，明月有光人有情。","別後相思人似月，雲間水上到層城。"]', '["離人無語月無声，明月有光人有情。","別後相思人似月，云间水上到層城。"]', '诗', 'shi', '', NULL, '明月夜留別 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a856728f-cb8f-4bc0-8068-6ac77d5bc446', '春閨怨', '春閨怨', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["百尺井欄上，數株桃已紅。","念君遼海北，拋妾宋家東。"]', '["百尺井欄上，數株桃已紅。","念君遼海北，拋妾宋家东。"]', '诗', 'shi', '', NULL, '春閨怨 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c41e4b44-0abe-4f82-b6c1-c09c4ddbc40f', '句', '句', 'c01eb248-0b73-41cf-b0ac-eed08eafb3e0', '唐', '["經時未架却，心緒亂縱橫。","已看雲鬢散，更念木枯榮。","鞞鼓喧行選，旌旗拂座隅。","不覩河陽一縣花，空見青山三兩點。"]', '["經时未架却，心緒亂縱橫。","已看云鬢散，更念木枯榮。","鞞鼓喧行選，旌旗拂座隅。","不覩河陽一縣花，空见青山三兩点。"]', '诗', 'shi', '', NULL, '句 李冶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fafff7d-d7cc-4fe0-a717-0bf8797d82e7', '寄洛中諸姊', '寄洛中諸姊', '25869133-b4ea-4b0d-a6f8-1cb83bdde46d', '唐', '["舊國經年別，關河萬里思。","題詩憑鴈翼，望月想蛾眉。","白髮愁偏覺，歸心夢獨知。","誰堪離亂處，掩淚向南枝。"]', '["旧国經年別，关河万里思。","題诗憑鴈翼，望月想蛾眉。","白髮愁偏覺，归心梦独知。","誰堪離亂处，掩泪向南枝。"]', '诗', 'shi', '', NULL, '寄洛中諸姊 元淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d67b649-5b23-449c-93fe-56c4ad006a51', '秦中春望', '秦中春望', '25869133-b4ea-4b0d-a6f8-1cb83bdde46d', '唐', '["鳳樓春望好，宮闕一重重。","上苑雨中樹，終南霽後峰。","落花行處徧，佳氣晚來濃。","喜見休明代，霓裳躡道蹤。"]', '["鳳楼春望好，宮闕一重重。","上苑雨中樹，終南霽後峰。","落花行处徧，佳氣晚来濃。","喜见休明代，霓裳躡道蹤。"]', '诗', 'shi', '', NULL, '秦中春望 元淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7b7e59-440b-4241-8c20-96c1b4050832', '句', '句', '25869133-b4ea-4b0d-a6f8-1cb83bdde46d', '唐', '["弟兄俱已盡，松柏問何人。","聞道茂陵山水好，碧溪流水有桃源。","赤城峭壁無人到，丹竈芝田有鶴來。","三千宮女露蛾眉，笑煮黃金日月遲。"]', '["弟兄俱已尽，松柏问何人。","闻道茂陵山水好，碧溪流水有桃源。","赤城峭壁無人到，丹竈芝田有鹤来。","三千宮女露蛾眉，笑煮黄金日月遲。"]', '诗', 'shi', '', NULL, '句 元淳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb794bf1-a1ec-4ac3-991f-cbd58e73a860', '舟夜一章', '舟夜一章', '18433359-fd27-4fc2-8026-984796c1658f', '唐', '["水色連天色，風聲益浪聲。","旅人歸思苦，漁叟夢魂驚。","舉棹雲先到，移舟月逐行。","旋吟詩句罷，猶見遠山橫。"]', '["水色連天色，风声益浪声。","旅人归思苦，漁叟梦魂驚。","舉棹云先到，移舟月逐行。","旋吟诗句罷，猶见远山橫。"]', '诗', 'shi', '', NULL, '舟夜一章 海印 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7b2589-310f-4075-8ed5-9085bcdfd429', '詩三百三首 一', '诗三百三首 一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["凡讀我詩者，心中須護淨。","慳貪繼日廉，諂曲登時正。","驅遣除惡業，歸依受真性。","今日得佛身，急急如律令。"]', '["凡读我诗者，心中須護淨。","慳貪繼日廉，諂曲登时正。","驱遣除惡業，归依受真性。","今日得佛身，急急如律令。"]', '诗', 'shi', '', NULL, '詩三百三首 一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09db3190-bd2b-4ee6-9172-5aa3224adcdd', '詩三百三首 二', '诗三百三首 二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["重巖我卜居，鳥道絕人迹。","庭際何所有，白雲抱幽石。","住茲凡幾年，屢見春冬易。","寄語鍾鼎家，虛名定無益。"]', '["重巖我卜居，鸟道絕人迹。","庭際何所有，白云抱幽石。","住茲凡幾年，屢见春冬易。","寄語鍾鼎家，虛名定無益。"]', '诗', 'shi', '', NULL, '詩三百三首 二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af0dd7e-f73d-45ea-94f9-f166719e4818', '詩三百三首 三', '诗三百三首 三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可笑寒山道，而無車馬蹤。","聯谿難記曲，疊嶂不知重。","泣露千般草，吟風一樣松。","此時迷徑處，形問影何從。"]', '["可笑寒山道，而無车马蹤。","聯谿难記曲，叠嶂不知重。","泣露千般草，吟风一樣松。","此时迷徑处，形问影何從。"]', '诗', 'shi', '', NULL, '詩三百三首 三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46216b9e-0443-45b7-9e14-fd4990d06def', '詩三百三首 四', '诗三百三首 四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["吾家好隱淪，居處絕囂塵。","踐草成三徑，瞻雲作四鄰。","助歌聲有鳥，問法語無人。","今日娑婆樹，幾年爲一春。"]', '["吾家好隐淪，居处絕囂塵。","踐草成三徑，瞻云作四鄰。","助歌声有鸟，问法語無人。","今日娑婆樹，幾年爲一春。"]', '诗', 'shi', '', NULL, '詩三百三首 四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('982b7b73-b460-495f-a3b2-dba8f60cd222', '詩三百三首 五', '诗三百三首 五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["琴書須自隨，祿位用何爲。","投輦從賢婦，巾車有孝兒。","風吹曝麥地，水溢沃魚池。","常念鷦鷯鳥，安身在一枝。"]', '["琴书須自隨，祿位用何爲。","投輦從賢婦，巾车有孝兒。","风吹曝麦地，水溢沃鱼池。","常念鷦鷯鸟，安身在一枝。"]', '诗', 'shi', '', NULL, '詩三百三首 五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb8ac120-2981-48d3-b84b-b883fda5bd36', '詩三百三首 六', '诗三百三首 六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["弟兄同五郡，父子本三州。","欲驗飛鳧集，須徵白兔遊。","靈瓜夢裏受，神橘座中收。","鄉國何迢遰，同魚寄水流。"]', '["弟兄同五郡，父子本三州。","欲驗飞鳧集，須徵白兔游。","靈瓜梦裏受，神橘座中收。","乡国何迢遰，同鱼寄水流。"]', '诗', 'shi', '', NULL, '詩三百三首 六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c09918c7-e839-44bc-800a-0b2bcc437334', '詩三百三首 七', '诗三百三首 七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一爲書劒客，二遇聖明君。","東守文不賞，西征武不勳。","學文兼學武，學武兼學文。","今日既老矣，餘生不足云。"]', '["一爲书劒客，二遇聖明君。","东守文不賞，西征武不勳。","学文兼学武，学武兼学文。","今日既老矣，餘生不足云。"]', '诗', 'shi', '', NULL, '詩三百三首 七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac39eafa-fde9-4fdf-8a19-effb1e32117f', '詩三百三首 八', '诗三百三首 八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["莊子說送終，天地爲棺槨。","吾歸此有時，唯須一番箔。","死將餧青蠅，弔不勞白鶴。","餓著首陽山，生廉死亦樂。"]', '["莊子说送終，天地爲棺槨。","吾归此有时，唯須一番箔。","死將餧青蠅，弔不勞白鹤。","餓著首陽山，生廉死亦乐。"]', '诗', 'shi', '', NULL, '詩三百三首 八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1593b477-c934-4f38-9024-98b33e779963', '詩三百三首 九', '诗三百三首 九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["人問寒山道，寒山路不通。","夏天冰未釋，日出霧朦朧。","似我何由屆，與君心不同。","君心若似我，還得到其中。"]', '["人问寒山道，寒山路不通。","夏天冰未釋，日出霧朦朧。","似我何由屆，與君心不同。","君心若似我，還得到其中。"]', '诗', 'shi', '', NULL, '詩三百三首 九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538c8971-1e0e-416d-b3d2-242224bb64e2', '詩三百三首 十', '诗三百三首 十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["天生百尺樹，翦作長條木。","可惜棟梁材，拋之在幽谷。","年多心尚勁，日久皮漸禿。","識者取將來，猶堪柱馬屋。"]', '["天生百尺樹，翦作长條木。","可惜棟梁材，拋之在幽谷。","年多心尚勁，日久皮漸禿。","識者取將来，猶堪柱马屋。"]', '诗', 'shi', '', NULL, '詩三百三首 十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d5eda2-7d74-481e-aee5-f64090796d3e', '詩三百三首 十一', '诗三百三首 十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["驅馬度荒城，荒城動客情。","高低舊雉堞，大小古墳塋。","自振孤蓬影，長凝拱木聲。","所嗟皆俗骨，仙史更無名。"]', '["驱马度荒城，荒城动客情。","高低旧雉堞，大小古墳塋。","自振孤蓬影，长凝拱木声。","所嗟皆俗骨，仙史更無名。"]', '诗', 'shi', '', NULL, '詩三百三首 十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbb69f8-485e-4a9c-90bb-4232a1e64b11', '詩三百三首 十二', '诗三百三首 十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["鸚鵡宅西國，虞羅捕得歸。","美人朝夕弄，出入在庭幃。","賜以金籠貯，扃哉損羽衣。","不如鴻與鶴，颻颺入雲飛。"]', '["鸚鵡宅西国，虞羅捕得归。","美人朝夕弄，出入在庭幃。","賜以金籠貯，扃哉損羽衣。","不如鴻與鹤，颻颺入云飞。"]', '诗', 'shi', '', NULL, '詩三百三首 十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c80de1-c4ac-4a4e-99ff-ae255ed6184d', '詩三百三首 十三', '诗三百三首 十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["玉堂挂珠簾，中有嬋娟子。","其貌勝神仙，容華若桃李。","東家春霧合，西舍秋風起。","更過三十年，還成苷蔗滓。"]', '["玉堂挂珠簾，中有嬋娟子。","其貌勝神仙，容华若桃李。","东家春霧合，西舍秋风起。","更過三十年，還成苷蔗滓。"]', '诗', 'shi', '', NULL, '詩三百三首 十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc74af5-81a0-4061-9548-a3966071e112', '詩三百三首 十四', '诗三百三首 十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["城中娥眉女，珠珮珂珊珊。","鸚鵡花前弄，琵琶月下彈。","長歌三月響，短舞萬人看。","未必長如此，芙蓉不耐寒。"]', '["城中娥眉女，珠珮珂珊珊。","鸚鵡花前弄，琵琶月下彈。","长歌三月响，短舞万人看。","未必长如此，芙蓉不耐寒。"]', '诗', 'shi', '', NULL, '詩三百三首 十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52de482-fc61-4f54-8d44-5f5e95ed6386', '詩三百三首 十五', '诗三百三首 十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["父母續經多，田園不羨他。","婦搖機軋軋，兒弄口㗻㗻。","拍手摧花舞，搘頤聽鳥歌。","誰當來歎賞，樵客屢經過。"]', '["父母續經多，田园不羨他。","婦搖機軋軋，兒弄口㗻㗻。","拍手摧花舞，搘頤听鸟歌。","誰當来歎賞，樵客屢經過。"]', '诗', 'shi', '', NULL, '詩三百三首 十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8e1593-c9f7-46b6-8a15-32345bfc8ee3', '詩三百三首 十六', '诗三百三首 十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["家住綠巖下，庭蕪更不芟。","新藤垂繚繞，古石豎巉巖。","山果獼猴摘，池魚白鷺銜。","仙書一兩卷，樹下讀喃喃。"]', '["家住綠巖下，庭蕪更不芟。","新藤垂繚繞，古石豎巉巖。","山果獼猴摘，池鱼白鷺銜。","仙书一兩卷，樹下读喃喃。"]', '诗', 'shi', '', NULL, '詩三百三首 十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cc43289-e575-4ef8-ad61-90e2871f0823', '詩三百三首 十七', '诗三百三首 十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["四時無止息，年去又年來。","萬物有代謝，九天無朽摧。","東明又西暗，花落復花開。","唯有黃泉客，冥冥去不迴。"]', '["四时無止息，年去又年来。","万物有代謝，九天無朽摧。","东明又西暗，花落复花开。","唯有黄泉客，冥冥去不迴。"]', '诗', 'shi', '', NULL, '詩三百三首 十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb3a2f92-1667-4015-8568-3f8963d8cf43', '詩三百三首 十八', '诗三百三首 十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["歲去換愁年，春來物色鮮。","山花笑淥水，巖岫舞青煙。","蜂蝶自云樂，禽魚更可憐。","朋遊情未已，徹曉不能眠。"]', '["歲去換愁年，春来物色鲜。","山花笑淥水，巖岫舞青煙。","蜂蝶自云乐，禽鱼更可怜。","朋游情未已，徹晓不能眠。"]', '诗', 'shi', '', NULL, '詩三百三首 十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26937dab-720c-412f-9a0d-337e5d96f938', '詩三百三首 十九', '诗三百三首 十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["手筆太縱橫，身材極環瑋。","生爲有限身，死作無名鬼。","自古如此多，君今爭奈何。","可來白雲裏，教爾紫芝歌。"]', '["手笔太縱橫，身材極环瑋。","生爲有限身，死作無名鬼。","自古如此多，君今爭奈何。","可来白云裏，教爾紫芝歌。"]', '诗', 'shi', '', NULL, '詩三百三首 十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c091e30-b7df-4833-a1e9-003310a193c8', '詩三百三首 二十', '诗三百三首 二十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["欲得安身處，寒山可長保。","微風吹幽松，近聽聲逾好。","下有斑白人，喃喃讀黃老。","十年歸不得，忘却來時道。"]', '["欲得安身处，寒山可长保。","微风吹幽松，近听声逾好。","下有斑白人，喃喃读黄老。","十年归不得，忘却来时道。"]', '诗', 'shi', '', NULL, '詩三百三首 二十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8530482c-c1a0-4ac4-848f-8b239f359f73', '詩三百三首 二十一', '诗三百三首 二十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["俊傑馬上郎，揮鞭指綠楊。","謂言無死日，終不作梯航。","四運花自好，一朝成萎黃。","醍醐與石蜜，至死不能嘗。"]', '["俊傑马上郎，揮鞭指綠楊。","謂言無死日，終不作梯航。","四運花自好，一朝成萎黄。","醍醐與石蜜，至死不能嘗。"]', '诗', 'shi', '', NULL, '詩三百三首 二十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8440e54-b940-4053-a82d-e8fb1aca9d6a', '詩三百三首 二十二', '诗三百三首 二十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有一餐霞子，其居諱俗遊。","論時實蕭爽，在夏亦如秋。","幽澗常瀝瀝，高松風颼颼。","其中半日坐，忘却百年愁。"]', '["有一餐霞子，其居諱俗游。","論时實蕭爽，在夏亦如秋。","幽澗常瀝瀝，高松风颼颼。","其中半日坐，忘却百年愁。"]', '诗', 'shi', '', NULL, '詩三百三首 二十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f8e2020-0585-439d-b29d-d9e101fc7084', '詩三百三首 二十三', '诗三百三首 二十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["妾在邯鄲住，歌聲亦抑揚。","賴我安居處，此曲舊來長。","既醉莫言歸，留連日未央。","兒家寢宿處，繡被滿銀牀。"]', '["妾在邯鄲住，歌声亦抑揚。","賴我安居处，此曲旧来长。","既醉莫言归，留連日未央。","兒家寢宿处，繡被满銀牀。"]', '诗', 'shi', '', NULL, '詩三百三首 二十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b76d24ac-6a7d-4c79-8b36-ec4c6ccb2416', '詩三百三首 二十四', '诗三百三首 二十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["快搒三翼舟，善乘千里馬。","莫能造我家，謂言最幽野。","巖岫深嶂中，雲雷竟日下。","自非孔丘公，無能相救者。"]', '["快搒三翼舟，善乘千里马。","莫能造我家，謂言最幽野。","巖岫深嶂中，云雷竟日下。","自非孔丘公，無能相救者。"]', '诗', 'shi', '', NULL, '詩三百三首 二十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d1ed63a-b2e4-495c-aa3c-484d3a98e0b5', '詩三百三首 二十五', '诗三百三首 二十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["智者君拋我，愚者我拋君。","非愚亦非智，從此斷相聞。","入夜歌明月，侵晨舞白雲。","焉能拱口手，端坐鬢紛紛。"]', '["智者君拋我，愚者我拋君。","非愚亦非智，從此斷相闻。","入夜歌明月，侵晨舞白云。","焉能拱口手，端坐鬢紛紛。"]', '诗', 'shi', '', NULL, '詩三百三首 二十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2b9ad6-1c7b-4909-bd79-3515a1d2f069', '詩三百三首 二十六', '诗三百三首 二十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有鳥五色彣，棲桐食竹實。","徐動合禮儀，和鳴中音律。","昨來何以至，爲吾暫時出。","儻聞弦歌聲，作舞欣今日。"]', '["有鸟五色彣，棲桐食竹實。","徐动合禮儀，和鳴中音律。","昨来何以至，爲吾暫时出。","儻闻弦歌声，作舞欣今日。"]', '诗', 'shi', '', NULL, '詩三百三首 二十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c339144-18fc-4968-89ea-5e70bde8683d', '詩三百三首 二十七', '诗三百三首 二十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["茅棟野人居，門前車馬疎。","林幽偏聚鳥，谿闊本藏魚。","山果攜兒摘，臯田共婦鋤。","家中何所有，唯有一牀書。"]', '["茅棟野人居，门前车马疎。","林幽偏聚鸟，谿闊本藏鱼。","山果携兒摘，臯田共婦鋤。","家中何所有，唯有一牀书。"]', '诗', 'shi', '', NULL, '詩三百三首 二十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a15b83f7-2778-4c71-a401-0ea17d124324', '詩三百三首 二十八', '诗三百三首 二十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["登陟寒山道，寒山路不窮。","谿長石磊磊，澗闊草濛濛。","苔滑非關雨，松鳴不假風。","誰能超世累，共坐白雲中。"]', '["登陟寒山道，寒山路不窮。","谿长石磊磊，澗闊草濛濛。","苔滑非关雨，松鳴不假风。","誰能超世累，共坐白云中。"]', '诗', 'shi', '', NULL, '詩三百三首 二十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1becc41d-d700-4c4a-ad00-8aeb5d660dee', '詩三百三首 二十九', '诗三百三首 二十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["六極常嬰困，九維徒自論。","有才遺草澤，無藝閉蓬門。","日上巖猶暗，煙消谷尚昏。","其中長者子，箇箇總無裩。"]', '["六極常嬰困，九維徒自論。","有才遺草澤，無藝閉蓬门。","日上巖猶暗，煙消谷尚昏。","其中长者子，箇箇總無裩。"]', '诗', 'shi', '', NULL, '詩三百三首 二十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f323b758-894e-47fb-9b87-ef5d475f9f69', '詩三百三首 三十', '诗三百三首 三十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["白雲高嵯峨，淥水蕩潭波。","此處聞漁父，時時鼓棹歌。","聲聲不可聽，令我愁思多。","誰謂雀無角，其如穿屋何。"]', '["白云高嵯峨，淥水蕩潭波。","此处闻漁父，时时鼓棹歌。","声声不可听，令我愁思多。","誰謂雀無角，其如穿屋何。"]', '诗', 'shi', '', NULL, '詩三百三首 三十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33ea7df7-8496-4e59-b329-8233b14ffe10', '詩三百三首 三十一', '诗三百三首 三十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["杳杳寒山道，落落冷澗濱。","啾啾常有鳥，寂寂更無人。","磧磧風吹面，紛紛雪積身。","朝朝不見日，歲歲不知春。"]', '["杳杳寒山道，落落冷澗濱。","啾啾常有鸟，寂寂更無人。","磧磧风吹面，紛紛雪積身。","朝朝不见日，歲歲不知春。"]', '诗', 'shi', '', NULL, '詩三百三首 三十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99791624-33ea-4f82-a470-3d22dae35b67', '詩三百三首 三十二', '诗三百三首 三十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["少年何所愁，愁見鬢毛白。","白更何所愁，愁見日逼迫。","移向東岱居，配守北邙宅。","何忍出此言，此言傷老客。"]', '["少年何所愁，愁见鬢毛白。","白更何所愁，愁见日逼迫。","移向东岱居，配守北邙宅。","何忍出此言，此言傷老客。"]', '诗', 'shi', '', NULL, '詩三百三首 三十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('346ad958-32e4-491c-a5c5-b6dc6780d4fc', '詩三百三首 三十三', '诗三百三首 三十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["聞道愁難遣，斯言謂不真。","昨朝曾趂却，今日又纏身。","月盡愁難盡，年新愁更新。","誰知席帽下，元是昔愁人。"]', '["闻道愁难遣，斯言謂不真。","昨朝曾趂却，今日又纏身。","月尽愁难尽，年新愁更新。","誰知席帽下，元是昔愁人。"]', '诗', 'shi', '', NULL, '詩三百三首 三十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fadc8e0f-0947-4c9b-87f9-fecbb174dd14', '詩三百三首 三十四', '诗三百三首 三十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["兩龜乘犢車，驀出路頭戲。","一蠱從傍來，苦死欲求寄。","不載爽人情，始載被沈累。","彈指不可論，行恩却遭刺。"]', '["兩龟乘犢车，驀出路头戲。","一蠱從傍来，苦死欲求寄。","不載爽人情，始載被沈累。","彈指不可論，行恩却遭刺。"]', '诗', 'shi', '', NULL, '詩三百三首 三十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1990b6-bec4-4e87-9114-198902767c4a', '詩三百三首 三十五', '诗三百三首 三十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["三月蠶猶小，女人來采花。","隈牆弄蝴蝶，臨水擲蝦𢋙。","羅袖盛梅子，金鎞挑筍芽。","鬬論多物色，此地勝余家。"]', '["三月蠶猶小，女人来采花。","隈牆弄蝴蝶，臨水擲蝦𢋙。","羅袖盛梅子，金鎞挑筍芽。","鬬論多物色，此地勝余家。"]', '诗', 'shi', '', NULL, '詩三百三首 三十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611202c6-173d-4fc9-8cb9-43b4c07106ae', '詩三百三首 三十六', '诗三百三首 三十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["東家一老婆，富來三五年。","昔日貧於我，今笑我無錢。","渠笑我在後，我笑渠在前。","相笑儻不止，東邊復西邊。"]', '["东家一老婆，富来三五年。","昔日貧於我，今笑我無錢。","渠笑我在後，我笑渠在前。","相笑儻不止，东邊复西邊。"]', '诗', 'shi', '', NULL, '詩三百三首 三十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc022418-23fc-43e2-b2a3-a8dcf69ba456', '詩三百三首 三十七', '诗三百三首 三十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["富兒多鞅掌，觸事難祇承。","倉米已赫赤，不貸人斗升。","轉懷鉤距意，買絹先揀綾。","若至臨終日，弔客有蒼蠅。"]', '["富兒多鞅掌，觸事难祇承。","倉米已赫赤，不貸人斗升。","轉懷鉤距意，買絹先揀綾。","若至臨終日，弔客有蒼蠅。"]', '诗', 'shi', '', NULL, '詩三百三首 三十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d192e30-8ec8-46eb-b369-f21f2d08e66b', '詩三百三首 三十八', '诗三百三首 三十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余曾昔覩聰明士，博達英靈無比倫。","一選嘉名喧宇宙，五言詩句越諸人。","爲官治化超先輩，直爲無能繼後塵。","忍然富貴貪財色，瓦解冰消不可陳。"]', '["余曾昔覩聰明士，博達英靈無比倫。","一選嘉名喧宇宙，五言诗句越諸人。","爲官治化超先輩，直爲無能繼後塵。","忍然富貴貪財色，瓦解冰消不可陳。"]', '诗', 'shi', '', NULL, '詩三百三首 三十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b928c814-6966-467f-907c-fc068517ded0', '詩三百三首 三十九', '诗三百三首 三十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["白鶴銜苦桃，千里作一息。","欲往蓬萊山，將此充糧食。","未達毛摧落，離羣心慘惻。","却歸舊來巢，妻子不相識。"]', '["白鹤銜苦桃，千里作一息。","欲往蓬萊山，將此充糧食。","未達毛摧落，離羣心慘惻。","却归旧来巢，妻子不相識。"]', '诗', 'shi', '', NULL, '詩三百三首 三十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0811670e-25fe-49dc-8cbf-14dcc10819eb', '詩三百三首 四十', '诗三百三首 四十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["慣居幽隱處，乍向國清中。","時訪豐干道，仍來看拾公。","獨迴上寒巖，無人話合同。","尋究無源水，源窮水不窮。"]', '["慣居幽隐处，乍向国清中。","时訪豐干道，仍来看拾公。","独迴上寒巖，無人話合同。","尋究無源水，源窮水不窮。"]', '诗', 'shi', '', NULL, '詩三百三首 四十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1119583b-6e60-43d0-8f55-fccc615259a2', '詩三百三首 四十一', '诗三百三首 四十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["生前大愚癡，不爲今日悟。","今日如許貧，總是前生作。","今生又不修，來生還如故。","兩岸各無船，渺渺難濟渡。"]', '["生前大愚癡，不爲今日悟。","今日如許貧，總是前生作。","今生又不修，来生還如故。","兩岸各無船，渺渺难濟渡。"]', '诗', 'shi', '', NULL, '詩三百三首 四十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2068371c-8a2b-4f28-a381-995055d72398', '詩三百三首 四十二', '诗三百三首 四十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["璨璨盧家女，舊來名莫愁。","貪乘摘花馬，樂搒采蓮舟。","膝坐綠熊席，身披青鳳裘。","哀傷百年內，不免歸山丘。"]', '["璨璨盧家女，旧来名莫愁。","貪乘摘花马，乐搒采蓮舟。","膝坐綠熊席，身披青鳳裘。","哀傷百年內，不免归山丘。"]', '诗', 'shi', '', NULL, '詩三百三首 四十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6476e4a1-e339-46d4-bdf1-c2ae99e76ea8', '詩三百三首 四十三', '诗三百三首 四十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["低眼鄒公妻，邯鄲杜生母。","二人同老少，一種好面首。","昨日會客場，惡衣排在後。","只爲著破裙，喫他殘䴺𪍣。"]', '["低眼鄒公妻，邯鄲杜生母。","二人同老少，一種好面首。","昨日會客場，惡衣排在後。","只爲著破裙，喫他殘䴺𪍣。"]', '诗', 'shi', '', NULL, '詩三百三首 四十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15bbf81-c8f8-46e1-9ee6-900eef8d0bb5', '詩三百三首 四十四', '诗三百三首 四十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["獨臥重巖下，蒸雲晝不消。","室中雖暡靉，心裏絕喧囂。","夢去遊金闕，魂歸度石橋。","拋除鬧我者，歷歷樹間瓢。"]', '["独臥重巖下，蒸云晝不消。","室中雖暡靉，心裏絕喧囂。","梦去游金闕，魂归度石橋。","拋除鬧我者，歷歷樹间瓢。"]', '诗', 'shi', '', NULL, '詩三百三首 四十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5b633a-2355-48a8-9e83-87bf5603f84b', '詩三百三首 四十五', '诗三百三首 四十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["夫物有所用，用之各有宜。","用之若失所，一缺復一虧。","圓鑿而方枘，悲哉空爾爲。","驊騮將捕鼠，不及跛猫兒。"]', '["夫物有所用，用之各有宜。","用之若失所，一缺复一虧。","圓鑿而方枘，悲哉空爾爲。","驊騮將捕鼠，不及跛猫兒。"]', '诗', 'shi', '', NULL, '詩三百三首 四十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f7bd356-374d-4d86-a6c0-1c20301cf47f', '詩三百三首 四十六', '诗三百三首 四十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["誰家長不死，死事舊來均。","始憶八尺漢，俄成一聚塵。","黃泉無曉日，青草有時春。","行到傷心處，松風愁殺人。"]', '["誰家长不死，死事旧来均。","始憶八尺漢，俄成一聚塵。","黄泉無晓日，青草有时春。","行到傷心处，松风愁殺人。"]', '诗', 'shi', '', NULL, '詩三百三首 四十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('911905d1-9c98-45e9-86eb-1180c9631d18', '詩三百三首 四十七', '诗三百三首 四十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["騮馬珊瑚鞭，驅馳洛陽道。","自矜美少年，不信有衰老。","白髮會應生，紅顏豈長保。","但看北邙山，箇是蓬萊島。"]', '["騮马珊瑚鞭，驱驰洛陽道。","自矜美少年，不信有衰老。","白髮會應生，紅顏豈长保。","但看北邙山，箇是蓬萊島。"]', '诗', 'shi', '', NULL, '詩三百三首 四十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee68a5a-e3b9-4310-952e-6958eaa56396', '詩三百三首 四十八', '诗三百三首 四十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["竟日常如醉，流年不暫停。","埋著蓬蒿下，曉月何冥冥。","骨肉消散盡，魂魄幾凋零。","遮莫齩鐵口，無因讀老經。"]', '["竟日常如醉，流年不暫停。","埋著蓬蒿下，晓月何冥冥。","骨肉消散尽，魂魄幾凋零。","遮莫齩鐵口，無因读老經。"]', '诗', 'shi', '', NULL, '詩三百三首 四十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca158369-c545-4091-b92a-d8d059ae0a7b', '詩三百三首 四十九', '诗三百三首 四十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一向寒山坐，淹留三十年。","昨來訪親友，太半入黃泉。","漸減如殘燭，長流似逝川。","今朝對孤影，不覺淚雙懸。"]', '["一向寒山坐，淹留三十年。","昨来訪親友，太半入黄泉。","漸減如殘燭，长流似逝川。","今朝对孤影，不覺泪雙懸。"]', '诗', 'shi', '', NULL, '詩三百三首 四十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33aad07b-e13a-4eb2-87bb-55061a2aadcb', '詩三百三首 五十', '诗三百三首 五十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["相喚採芙蓉，可憐清江裏。","遊戲不覺暮，屢見狂風起。","浪捧鴛鴦兒，波搖鸂鶒子。","此時居舟楫，浩蕩情無已。"]', '["相喚採芙蓉，可怜清江裏。","游戲不覺暮，屢见狂风起。","浪捧鴛鴦兒，波搖鸂鶒子。","此时居舟楫，浩蕩情無已。"]', '诗', 'shi', '', NULL, '詩三百三首 五十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe76e29c-c7c5-495a-aecc-a66924a41046', '詩三百三首 五十一', '诗三百三首 五十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["吾心似秋月，碧潭清皎潔。","無物堪比倫，教我如何說。"]', '["吾心似秋月，碧潭清皎潔。","無物堪比倫，教我如何说。"]', '诗', 'shi', '', NULL, '詩三百三首 五十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eccb61bc-15b6-4ef8-b45f-f9eb302668c7', '詩三百三首 五十二', '诗三百三首 五十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["垂柳暗如煙，飛花飄似霰。","夫居離婦州，婦住思夫縣。","各在天一涯，何時得相見？","寄語明月樓，莫貯雙飛燕。"]', '["垂柳暗如煙，飞花飄似霰。","夫居離婦州，婦住思夫縣。","各在天一涯，何时得相见？","寄語明月楼，莫貯雙飞燕。"]', '诗', 'shi', '', NULL, '詩三百三首 五十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9072441-da51-4774-a06f-3466a3157dca', '詩三百三首 五十三', '诗三百三首 五十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有酒相招飲，有肉相呼喫。","黃泉前後人，少壯須努力。","玉帶暫時華，金釵非久飾。","張翁與鄭婆，一去無消息。"]', '["有酒相招饮，有肉相呼喫。","黄泉前後人，少壯須努力。","玉带暫时华，金釵非久飾。","張翁與鄭婆，一去無消息。"]', '诗', 'shi', '', NULL, '詩三百三首 五十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4555ed9-13b5-4fc0-a67c-9a1fac88bd62', '詩三百三首 五十四', '诗三百三首 五十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可憐好丈夫，身體極稜稜。","春秋未三十，才藝百般能。","金羈逐俠客，玉饌集良朋。","唯有一般惡，不傳無盡燈。"]', '["可怜好丈夫，身體極稜稜。","春秋未三十，才藝百般能。","金羈逐俠客，玉饌集良朋。","唯有一般惡，不傳無尽灯。"]', '诗', 'shi', '', NULL, '詩三百三首 五十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e96122-7e34-4273-bba3-ff560edd5a2d', '詩三百三首 五十五', '诗三百三首 五十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["桃花欲經夏，風月催不待。","訪覓漢時人，能無一箇在。","朝朝花遷落，歲歲人移改。","今日揚塵處，昔時爲大海。"]', '["桃花欲經夏，风月催不待。","訪覓漢时人，能無一箇在。","朝朝花遷落，歲歲人移改。","今日揚塵处，昔时爲大海。"]', '诗', 'shi', '', NULL, '詩三百三首 五十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('124d6329-4473-413c-ba33-2f66f6d09add', '詩三百三首 五十六', '诗三百三首 五十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見東家女，年可有十八。","西舍競來問，願姻夫妻活。","烹羊煮衆命，聚頭作婬殺。","含笑樂呵呵，啼哭受殃抉。"]', '["我见东家女，年可有十八。","西舍競来问，願姻夫妻活。","烹羊煮衆命，聚头作婬殺。","含笑乐呵呵，啼哭受殃抉。"]', '诗', 'shi', '', NULL, '詩三百三首 五十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac5d248b-7395-4410-8ee5-2fca45f776ab', '詩三百三首 五十七', '诗三百三首 五十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["田舍多桑園，牛犢滿廐轍。","肯信有因果，頑皮早晚裂。","眼看消磨盡，當頭各自活。","紙袴瓦作裩，到頭凍餓殺。"]', '["田舍多桑园，牛犢满廐轍。","肯信有因果，頑皮早晚裂。","眼看消磨尽，當头各自活。","紙袴瓦作裩，到头凍餓殺。"]', '诗', 'shi', '', NULL, '詩三百三首 五十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0de3690-b77e-454e-b01f-cd9ca228ec40', '詩三百三首 五十八', '诗三百三首 五十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見百十狗，箇箇毛鬇鬡。","臥者渠自臥，行者渠自行。","投之一塊骨，相與啀喍爭。","良由爲骨少，狗多分不平。"]', '["我见百十狗，箇箇毛鬇鬡。","臥者渠自臥，行者渠自行。","投之一塊骨，相與啀喍爭。","良由爲骨少，狗多分不平。"]', '诗', 'shi', '', NULL, '詩三百三首 五十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f025ed30-0459-45aa-b3c4-7f35d27387e8', '詩三百三首 五十九', '诗三百三首 五十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["極目兮長望，白雲四茫茫。","鴟鵶飽腲腇，鸞鳳飢徬徨。","駿馬放石磧，蹇驢能至堂。","天高不可問，鷦鵊在滄浪。"]', '["極目兮长望，白云四茫茫。","鴟鵶飽腲腇，鸾鳳飢徬徨。","駿马放石磧，蹇驢能至堂。","天高不可问，鷦鵊在滄浪。"]', '诗', 'shi', '', NULL, '詩三百三首 五十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f835f5a-9a57-4a54-90ce-428f1e0c3c32', '詩三百三首 六十', '诗三百三首 六十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["洛陽多女兒，春日逞華麗。","共折路邊花，各持插高髻。","髻高花匼匝，人見皆睥睨。","別求醦醦憐，將歸見夫壻。"]', '["洛陽多女兒，春日逞华丽。","共折路邊花，各持插高髻。","髻高花匼匝，人见皆睥睨。","別求醦醦怜，將归见夫壻。"]', '诗', 'shi', '', NULL, '詩三百三首 六十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe62d4b-19b4-425f-a292-9cebc02d47c8', '詩三百三首 六十一', '诗三百三首 六十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["春女衒容儀，相將南陌陲。","看花愁日晚，隱樹怕風吹。","年少徒傍來，白馬黃金羈。","何須久相弄，兒家夫壻知。"]', '["春女衒容儀，相將南陌陲。","看花愁日晚，隐樹怕风吹。","年少徒傍来，白马黄金羈。","何須久相弄，兒家夫壻知。"]', '诗', 'shi', '', NULL, '詩三百三首 六十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8062c758-e477-47b0-961e-1c5630c30f18', '詩三百三首 六十二', '诗三百三首 六十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["羣女戲夕陽，風來滿路香。","綴裙金蛺蝶，插髻玉鴛鴦。","角婢紅羅縝，閹奴紫錦裳。","爲觀失道者，鬢白心惶惶。"]', '["羣女戲夕陽，风来满路香。","綴裙金蛺蝶，插髻玉鴛鴦。","角婢紅羅縝，閹奴紫錦裳。","爲观失道者，鬢白心惶惶。"]', '诗', 'shi', '', NULL, '詩三百三首 六十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('461bb2e5-bcac-4e3f-a1da-dee1f6775068', '詩三百三首 六十三', '诗三百三首 六十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["若人逢鬼魅，第一莫驚懅。","捺硬莫采渠，呼名自當去。","燒香請佛力，禮拜求僧助。","蚊子叮鐵牛，無渠下觜處。"]', '["若人逢鬼魅，第一莫驚懅。","捺硬莫采渠，呼名自當去。","燒香請佛力，禮拜求僧助。","蚊子叮鐵牛，無渠下觜处。"]', '诗', 'shi', '', NULL, '詩三百三首 六十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9ddbfd-e61f-4889-9cb2-bdeddd099649', '詩三百三首 六十四', '诗三百三首 六十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["浩浩黃河水，東流長不息。","悠悠不見清，人人壽有極。","苟欲乘白雲，曷由生羽翼。","唯當鬒髮時，行住須努力。"]', '["浩浩黄河水，东流长不息。","悠悠不见清，人人壽有極。","苟欲乘白云，曷由生羽翼。","唯當鬒髮时，行住須努力。"]', '诗', 'shi', '', NULL, '詩三百三首 六十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f63665af-0020-4407-b158-3bdc5d708499', '詩三百三首 六十五', '诗三百三首 六十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["乘茲朽木船，采彼紝婆子。","行至大海中，波濤復不止。","唯賫一宿糧，去岸三千里。","煩惱從何生，愁哉緣苦起。"]', '["乘茲朽木船，采彼紝婆子。","行至大海中，波濤复不止。","唯賫一宿糧，去岸三千里。","煩惱從何生，愁哉緣苦起。"]', '诗', 'shi', '', NULL, '詩三百三首 六十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad9d882-fa41-4c5a-90f3-802545790d7c', '詩三百三首 六十六', '诗三百三首 六十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["默默永無言，後生何所述。","隱居在林藪，智日何由出。","枯槁非堅衛，風霜成夭疾。","土牛耕石田，未有得稻日。"]', '["默默永無言，後生何所述。","隐居在林藪，智日何由出。","枯槁非堅衛，风霜成夭疾。","土牛耕石田，未有得稻日。"]', '诗', 'shi', '', NULL, '詩三百三首 六十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81800dd9-2f0e-474c-8bcf-0c218cd3425b', '詩三百三首 六十七', '诗三百三首 六十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["山中何太冷，自古非今年。","沓嶂恆凝雪，幽林每吐煙。","草生芒種後，葉落立秋前。","此有沈迷客，窺窺不見天。"]', '["山中何太冷，自古非今年。","沓嶂恆凝雪，幽林每吐煙。","草生芒種後，葉落立秋前。","此有沈迷客，窺窺不见天。"]', '诗', 'shi', '', NULL, '詩三百三首 六十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ed8b61f-bf4e-4946-8c44-60d5eb92a2a8', '詩三百三首 六十八', '诗三百三首 六十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["山客心悄悄，常嗟歲序遷。","辛勤采芝朮，搜斥詎成仙。","庭廓雲初卷，林明月正圓。","不歸何所爲，桂樹相留連。"]', '["山客心悄悄，常嗟歲序遷。","辛勤采芝朮，搜斥詎成仙。","庭廓云初卷，林明月正圓。","不归何所爲，桂樹相留連。"]', '诗', 'shi', '', NULL, '詩三百三首 六十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c555bc5-5bca-45a2-8071-98e1c4ea5b06', '詩三百三首 六十九', '诗三百三首 六十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有人兮山楹，雲卷兮霞纓。","秉芳兮欲寄，路漫漫兮難征。","心惆悵兮狐疑，年老已無成。","衆喔咿斯，蹇獨立兮忠貞。"]', '["有人兮山楹，云卷兮霞纓。","秉芳兮欲寄，路漫漫兮难征。","心惆悵兮狐疑，年老已無成。","衆喔咿斯，蹇独立兮忠貞。"]', '诗', 'shi', '', NULL, '詩三百三首 六十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbc2c9f1-d0a5-4cde-a839-7234b71ea3e8', '詩三百三首 七十', '诗三百三首 七十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["豬喫死人肉，人喫死豬腸。","豬不嫌人臭，人反道豬香。","豬死拋水內，人死掘土藏。","彼此莫相噉，蓮花生沸湯。"]', '["豬喫死人肉，人喫死豬腸。","豬不嫌人臭，人反道豬香。","豬死拋水內，人死掘土藏。","彼此莫相噉，蓮花生沸湯。"]', '诗', 'shi', '', NULL, '詩三百三首 七十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0b1b932-68ed-4c6d-9db5-33830065ab2c', '詩三百三首 七十一', '诗三百三首 七十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["快哉混沌身，不飯復不尿。","遭得誰鑽鑿，因茲立九竅。","朝朝爲衣食，歲歲愁租調。","千箇爭一錢，聚頭亡命叫。"]', '["快哉混沌身，不飯复不尿。","遭得誰鑽鑿，因茲立九竅。","朝朝爲衣食，歲歲愁租調。","千箇爭一錢，聚头亡命叫。"]', '诗', 'shi', '', NULL, '詩三百三首 七十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f50052-e0dd-4da2-8d79-33598a367926', '詩三百三首 七十二', '诗三百三首 七十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["啼哭緣何事，淚如珠子顆。","應當有別離，復是遭喪禍。","所爲在貧窮，未能了因果。","塚間瞻死屍，六道不干我。"]', '["啼哭緣何事，泪如珠子顆。","應當有別離，复是遭喪禍。","所爲在貧窮，未能了因果。","塚间瞻死屍，六道不干我。"]', '诗', 'shi', '', NULL, '詩三百三首 七十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0e2bf38-95f1-4867-8a0e-a962214c8462', '詩三百三首 七十三', '诗三百三首 七十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["婦女慵經織，男夫嬾耨田。","輕浮耽挾彈，跕躧拈抹弦。","凍骨衣應急，充腸食在先。","今誰念於汝，苦痛哭蒼天。"]', '["婦女慵經织，男夫嬾耨田。","轻浮耽挾彈，跕躧拈抹弦。","凍骨衣應急，充腸食在先。","今誰念於汝，苦痛哭蒼天。"]', '诗', 'shi', '', NULL, '詩三百三首 七十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e90372e-5d11-461a-a561-63e93b2857d5', '詩三百三首 七十四', '诗三百三首 七十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["不行真正道，隨邪號行婆。","口慙神佛少，心懷嫉妒多。","背後噇魚肉，人前念佛陀。","如此修身處，難應避奈何。"]', '["不行真正道，隨邪號行婆。","口慙神佛少，心懷嫉妒多。","背後噇鱼肉，人前念佛陀。","如此修身处，难應避奈何。"]', '诗', 'shi', '', NULL, '詩三百三首 七十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec62262-c89c-48a8-89fc-d80eb1201cfb', '詩三百三首 七十五', '诗三百三首 七十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有一等愚，茫茫恰似驢。","還解人言語，貪婬狀若豬。","險巇難可測，實語却成虛。","誰能共伊語，令教莫此居。"]', '["世有一等愚，茫茫恰似驢。","還解人言語，貪婬狀若豬。","險巇难可測，實語却成虛。","誰能共伊語，令教莫此居。"]', '诗', 'shi', '', NULL, '詩三百三首 七十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('953805e5-ac10-49c1-8cc4-c02acea44c8c', '詩三百三首 七十六', '诗三百三首 七十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有漢姓慠慢，名貪字不廉。","一身無所解，百事被他嫌。","死惡黃連苦，生憐白蜜甜。","喫魚猶未止，食肉更無厭。"]', '["有漢姓慠慢，名貪字不廉。","一身無所解，百事被他嫌。","死惡黄連苦，生怜白蜜甜。","喫鱼猶未止，食肉更無厭。"]', '诗', 'shi', '', NULL, '詩三百三首 七十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54a61bc9-334e-48d9-8fc4-cb5535b59b8a', '詩三百三首 七十七', '诗三百三首 七十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["縱你居犀角，饒君帶虎睛。","桃枝將辟穢，蒜殼取爲瓔。","暖腹茱萸酒，空心枸杞羹。","終歸不免死，浪自覓長生。"]', '["縱你居犀角，饒君带虎睛。","桃枝將辟穢，蒜殼取爲瓔。","暖腹茱萸酒，空心枸杞羹。","終归不免死，浪自覓长生。"]', '诗', 'shi', '', NULL, '詩三百三首 七十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c43e3e-c499-4609-a4ac-c9f50786b8e3', '詩三百三首 七十八', '诗三百三首 七十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["卜擇幽居地，天台更莫言。","猨啼谿霧冷，嶽色草門連。","折葉覆松室，開池引澗泉。","已甘休萬事，采蕨度殘年。"]', '["卜擇幽居地，天台更莫言。","猨啼谿霧冷，嶽色草门連。","折葉覆松室，开池引澗泉。","已甘休万事，采蕨度殘年。"]', '诗', 'shi', '', NULL, '詩三百三首 七十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa17c9c-3f75-4b49-ba89-42e539ab99b5', '詩三百三首 七十九', '诗三百三首 七十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["益者益其精，可名爲有益。","易者易其形，是名之有易。","能益復能易，當得上仙籍。","無益復無易，終不免死厄。"]', '["益者益其精，可名爲有益。","易者易其形，是名之有易。","能益复能易，當得上仙籍。","無益复無易，終不免死厄。"]', '诗', 'shi', '', NULL, '詩三百三首 七十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('071e5afc-3077-4df4-b25b-b70d3e1777ad', '詩三百三首 八十', '诗三百三首 八十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["徒勞說三史，浪自看五經。","洎老檢黃籍，依前住白丁。","筮遭連蹇卦，生主虛危星。","不及河邊樹，年年一度青。"]', '["徒勞说三史，浪自看五經。","洎老檢黄籍，依前住白丁。","筮遭連蹇卦，生主虛危星。","不及河邊樹，年年一度青。"]', '诗', 'shi', '', NULL, '詩三百三首 八十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e44958a-2ace-4527-ac61-549b52731954', '詩三百三首 八十一', '诗三百三首 八十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["碧澗泉水清，寒山月華白。","默知神自明，觀空境逾寂。"]', '["碧澗泉水清，寒山月华白。","默知神自明，观空境逾寂。"]', '诗', 'shi', '', NULL, '詩三百三首 八十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc2a482e-10a8-4766-8c14-bd1d6904b9a0', '詩三百三首 八十二', '诗三百三首 八十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我今有一襦，非羅復非綺。","借問作何色，不紅亦不紫。","夏天將作衫，冬天將作被。","冬夏遞互用，長年只這是。"]', '["我今有一襦，非羅复非綺。","借问作何色，不紅亦不紫。","夏天將作衫，冬天將作被。","冬夏遞互用，长年只這是。"]', '诗', 'shi', '', NULL, '詩三百三首 八十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e952e6a-279c-4758-8356-61762ce838e2', '詩三百三首 八十三', '诗三百三首 八十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["白拂栴檀柄，馨香竟日聞。","柔和如卷霧，搖拽似行雲。","禮奉宜當暑，高提復去塵。","時時方丈內，將用指迷人。"]', '["白拂栴檀柄，馨香竟日闻。","柔和如卷霧，搖拽似行云。","禮奉宜當暑，高提复去塵。","时时方丈內，將用指迷人。"]', '诗', 'shi', '', NULL, '詩三百三首 八十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a951cb-90ab-4e2a-bb82-90c18fbce596', '詩三百三首 八十四', '诗三百三首 八十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["貪愛有人求快活，不知禍在百年身。","但看陽燄浮漚水，便覺無常敗壞人。","丈夫志氣直如鐵，無曲心中道自真。","行密節高霜下竹，方知不枉用心神。"]', '["貪愛有人求快活，不知禍在百年身。","但看陽燄浮漚水，便覺無常敗壞人。","丈夫志氣直如鐵，無曲心中道自真。","行密節高霜下竹，方知不枉用心神。"]', '诗', 'shi', '', NULL, '詩三百三首 八十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cfaaca2-d493-45f9-9af5-4e783140ab42', '詩三百三首 八十五', '诗三百三首 八十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["多少般數人，百計求名利。","心貪覓榮華，經營圖富貴。","心未片時歇，奔突如煙氣。","家眷實團圓，一呼百諾至。","不過七十年，冰消瓦解置。","死了萬事休，誰人承後嗣。","水浸泥彈丸，方知無意智。"]', '["多少般數人，百計求名利。","心貪覓榮华，經營圖富貴。","心未片时歇，奔突如煙氣。","家眷實團圓，一呼百諾至。","不過七十年，冰消瓦解置。","死了万事休，誰人承後嗣。","水浸泥彈丸，方知無意智。"]', '诗', 'shi', '', NULL, '詩三百三首 八十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26dd6f17-3b2a-4301-b84a-d98c0e23e352', '詩三百三首 八十六', '诗三百三首 八十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["貪人好聚財，恰如梟愛子。","子大而食母，財多還害己。","散之即福生，聚之即禍起。","無財亦無禍，鼓翼青雲裏。"]', '["貪人好聚財，恰如梟愛子。","子大而食母，財多還害己。","散之即福生，聚之即禍起。","無財亦無禍，鼓翼青云裏。"]', '诗', 'shi', '', NULL, '詩三百三首 八十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de7f75a9-7d2d-45d9-a3c1-4b23af2324ff', '詩三百三首 八十七', '诗三百三首 八十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["去家一萬里，提劒擊匈奴。","得利渠即死，失利汝即殂。","渠命既不惜，汝命亦何辜。","教汝百勝術，不貪爲上謨。"]', '["去家一万里，提劒擊匈奴。","得利渠即死，失利汝即殂。","渠命既不惜，汝命亦何辜。","教汝百勝術，不貪爲上謨。"]', '诗', 'shi', '', NULL, '詩三百三首 八十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35661fb2-59ad-482c-b524-ea712e68da74', '詩三百三首 八十八', '诗三百三首 八十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["瞋是心中火，能燒功德林。","欲行菩薩道，忍辱護真心。"]', '["瞋是心中火，能燒功德林。","欲行菩薩道，忍辱護真心。"]', '诗', 'shi', '', NULL, '詩三百三首 八十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204bdb0f-6fa1-4a8d-b13d-5b811369f26f', '詩三百三首 八十九', '诗三百三首 八十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["汝爲埋頭癡兀兀，愛向無明羅剎窟。","再三勸你早修行，是你頑癡心恍惚。","不肯信受寒山語，轉轉倍加業汩汩。","直待斬首作兩段，方知自身奴賊物。"]', '["汝爲埋头癡兀兀，愛向無明羅剎窟。","再三勸你早修行，是你頑癡心恍惚。","不肯信受寒山語，轉轉倍加業汩汩。","直待斬首作兩段，方知自身奴賊物。"]', '诗', 'shi', '', NULL, '詩三百三首 八十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d671d9a6-0b1a-4282-85a4-a394c1305b8e', '詩三百三首 九十', '诗三百三首 九十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["惡趣甚茫茫，冥冥無日光。","人間八百歲，未抵半宵長。","此等諸癡子，論情甚可傷。","勸君求出離，認取法中王。"]', '["惡趣甚茫茫，冥冥無日光。","人间八百歲，未抵半宵长。","此等諸癡子，論情甚可傷。","勸君求出離，認取法中王。"]', '诗', 'shi', '', NULL, '詩三百三首 九十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74148e53-bd8c-48f7-aaa2-165d1a7640e5', '詩三百三首 九十一', '诗三百三首 九十一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有多解人，愚癡徒苦辛。","不求當來善，唯知造惡因。","五逆十惡輩，三毒以爲親。","一死入地獄，長如鎮庫銀。"]', '["世有多解人，愚癡徒苦辛。","不求當来善，唯知造惡因。","五逆十惡輩，三毒以爲親。","一死入地獄，长如鎮庫銀。"]', '诗', 'shi', '', NULL, '詩三百三首 九十一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec4c6f3-eb9b-4fd1-a473-dc6e4407ab3a', '詩三百三首 九十二', '诗三百三首 九十二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["天高高不窮，地厚厚無極。","動物在其中，憑茲造化力。","爭頭覓飽暖，作計相噉食。","因果都未詳，盲兒問乳色。"]', '["天高高不窮，地厚厚無極。","动物在其中，憑茲造化力。","爭头覓飽暖，作計相噉食。","因果都未詳，盲兒问乳色。"]', '诗', 'shi', '', NULL, '詩三百三首 九十二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db8e3e2-039e-428b-9417-34cd45d96a42', '詩三百三首 九十三', '诗三百三首 九十三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["天下幾種人，論時色數有。","賈婆如許夫，黃老元無婦。","衛氏兒可憐，鐘家女極醜。","渠若向西行，我便東邊走。"]', '["天下幾種人，論时色數有。","賈婆如許夫，黄老元無婦。","衛氏兒可怜，鐘家女極醜。","渠若向西行，我便东邊走。"]', '诗', 'shi', '', NULL, '詩三百三首 九十三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d012133b-b43e-4473-b23d-46f8652debe3', '詩三百三首 九十四', '诗三百三首 九十四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["賢士不貪婪，癡人好鑪冶。","麥地占他家，竹園皆我者。","努膊覓錢財，切齒驅奴馬。","須看郭門外，壘壘松栢下。"]', '["賢士不貪婪，癡人好鑪冶。","麦地占他家，竹园皆我者。","努膊覓錢財，切齒驱奴马。","須看郭门外，壘壘松栢下。"]', '诗', 'shi', '', NULL, '詩三百三首 九十四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5452e44b-7125-4121-954f-8302c8873699', '詩三百三首 九十五', '诗三百三首 九十五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["嗊嗊買魚肉，擔歸餧妻子。","何須殺他命，將來活汝己。","此非天堂緣，純是地獄滓。","徐六語破堆，始知沒道理。"]', '["嗊嗊買鱼肉，擔归餧妻子。","何須殺他命，將来活汝己。","此非天堂緣，純是地獄滓。","徐六語破堆，始知沒道理。"]', '诗', 'shi', '', NULL, '詩三百三首 九十五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('171d9b97-1a69-4f75-8e7c-113deb24ae9a', '詩三百三首 九十六', '诗三百三首 九十六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有人把椿樹，喚作白栴檀。","學道多沙數，幾箇得泥丸。","棄金却擔草，謾他亦自謾。","似聚砂一處，成團也大難。"]', '["有人把椿樹，喚作白栴檀。","学道多沙數，幾箇得泥丸。","棄金却擔草，謾他亦自謾。","似聚砂一处，成團也大难。"]', '诗', 'shi', '', NULL, '詩三百三首 九十六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e42feac-3dc3-49ab-9445-654067aa13f5', '詩三百三首 九十七', '诗三百三首 九十七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["蒸砂擬作飯，臨渴始掘井。","用力磨碌磚，那堪將作鏡。","佛說元平等，總有真如性。","但自審思量，不用閑爭競。"]', '["蒸砂擬作飯，臨渴始掘井。","用力磨碌磚，那堪將作镜。","佛说元平等，總有真如性。","但自審思量，不用闲爭競。"]', '诗', 'shi', '', NULL, '詩三百三首 九十七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83c8d652-c3f4-4a76-82a1-2ee73a3ee74d', '詩三百三首 九十八', '诗三百三首 九十八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["推尋世間事，子細總皆知。","凡事莫容易，盡愛討便宜。","護即弊成好，毀即是成非。","故知雜濫口，背面總由伊。","冷暖我自量，不信奴脣皮。"]', '["推尋世间事，子細總皆知。","凡事莫容易，尽愛討便宜。","護即弊成好，毀即是成非。","故知杂濫口，背面總由伊。","冷暖我自量，不信奴脣皮。"]', '诗', 'shi', '', NULL, '詩三百三首 九十八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4782f46c-1167-4482-af9a-80286f502c8f', '詩三百三首 九十九', '诗三百三首 九十九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["蹭蹬諸貧士，飢寒成至極。","閑居好作詩，札札用心力。","賤他言孰采，勸君休歎息。","題安餬{麥幷}上，乞狗也不喫。"]', '["蹭蹬諸貧士，飢寒成至極。","闲居好作诗，札札用心力。","賤他言孰采，勸君休歎息。","題安餬{麦幷}上，乞狗也不喫。"]', '诗', 'shi', '', NULL, '詩三百三首 九十九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00945457-4606-427a-be1b-6af889d83d8e', '詩三百三首 一百', '诗三百三首 一百', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["欲識生死譬，且將冰水比。","水結即成冰，冰消返成水。","已死必應生，出生還復死。","冰水不相傷，生死還雙美。"]', '["欲識生死譬，且將冰水比。","水結即成冰，冰消返成水。","已死必應生，出生還复死。","冰水不相傷，生死還雙美。"]', '诗', 'shi', '', NULL, '詩三百三首 一百 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3c24f3d-03eb-47e8-8e47-3864bedc91e8', '詩三百三首 一百一', '诗三百三首 一百一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["尋思少年日，遊獵向平陵。","國使職非願，神仙未足稱。","聯翩騎白馬，喝兔放蒼鷹。","不覺大流落，皤皤誰見矜。"]', '["尋思少年日，游獵向平陵。","国使職非願，神仙未足稱。","聯翩騎白马，喝兔放蒼鷹。","不覺大流落，皤皤誰见矜。"]', '诗', 'shi', '', NULL, '詩三百三首 一百一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efc4e43c-c637-48db-a4db-9dc26c19b034', '詩三百三首 一百二', '诗三百三首 一百二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["偃息深林下，從生是農夫。","立身既質直，出語無諂諛。","保我不鑒璧，信君方得珠。","焉能同泛灩，極目波上鳧。"]', '["偃息深林下，從生是農夫。","立身既質直，出語無諂諛。","保我不鑒璧，信君方得珠。","焉能同泛灩，極目波上鳧。"]', '诗', 'shi', '', NULL, '詩三百三首 一百二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac596b0-b5db-4878-9f41-97e2f5dd3578', '詩三百三首 一百三', '诗三百三首 一百三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["不須攻人惡，何用伐己善。","行之則可行，卷之則可卷。","祿厚憂積大，言深慮交淺。","聞茲若念茲，小子當自見。"]', '["不須攻人惡，何用伐己善。","行之則可行，卷之則可卷。","祿厚憂積大，言深慮交淺。","闻茲若念茲，小子當自见。"]', '诗', 'shi', '', NULL, '詩三百三首 一百三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b509a7-fe4b-4a81-bf07-ff306f9f1662', '詩三百三首 一百四', '诗三百三首 一百四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["富兒會高堂，華燈何煒煌。","此時無燭者，心願處其傍。","不意遭排遣，還歸暗處藏。","益人明詎損，頓訝惜餘光。"]', '["富兒會高堂，华灯何煒煌。","此时無燭者，心願处其傍。","不意遭排遣，還归暗处藏。","益人明詎損，頓訝惜餘光。"]', '诗', 'shi', '', NULL, '詩三百三首 一百四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1618dcd5-7c50-4e45-8c0c-9cb8ecbf5ccc', '詩三百三首 一百五', '诗三百三首 一百五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有聰明士，勤苦探幽文。","三端自孤立，六藝越諸君。","神氣卓然異，精彩超衆羣。","不識箇中意，逐境亂紛紛。"]', '["世有聰明士，勤苦探幽文。","三端自孤立，六藝越諸君。","神氣卓然異，精彩超衆羣。","不識箇中意，逐境亂紛紛。"]', '诗', 'shi', '', NULL, '詩三百三首 一百五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683e5b2a-d809-4750-bb94-cd54365fabcd', '詩三百三首 一百六', '诗三百三首 一百六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["層層山水秀，煙霞鎖翠微。","嵐拂紗巾濕，露霑蓑草衣。","足躡遊方履，手執古藤枝。","更觀塵世外，夢境復何爲。"]', '["層層山水秀，煙霞鎖翠微。","嵐拂紗巾濕，露霑蓑草衣。","足躡游方履，手執古藤枝。","更观塵世外，梦境复何爲。"]', '诗', 'shi', '', NULL, '詩三百三首 一百六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b422b60d-ae38-4681-a4fe-ce22ac693110', '詩三百三首 一百七', '诗三百三首 一百七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["滿卷才子詩，溢壺聖人酒。","行愛觀牛犢，坐不離左右。","霜露入茅簷，月華明甕牖。","此時吸兩甌，吟詩五百首。"]', '["满卷才子诗，溢壺聖人酒。","行愛观牛犢，坐不離左右。","霜露入茅簷，月华明甕牖。","此时吸兩甌，吟诗五百首。"]', '诗', 'shi', '', NULL, '詩三百三首 一百七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b280be78-5308-4a31-9cac-b798126a93f4', '詩三百三首 一百八', '诗三百三首 一百八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["施家有兩兒，以藝干齊楚。","文武各自備，託身爲得所。","孟公問其術，我子親教汝。","秦衛兩不成，失時成齟齬。"]', '["施家有兩兒，以藝干齊楚。","文武各自備，託身爲得所。","孟公问其術，我子親教汝。","秦衛兩不成，失时成齟齬。"]', '诗', 'shi', '', NULL, '詩三百三首 一百八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed48ec3f-0814-400f-8e06-3dbebe5d664b', '詩三百三首 一百九', '诗三百三首 一百九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["止宿鴛鴦鳥，一雄兼一雌。","銜花相共食，刷羽每相隨。","戲入煙霄裏，宿歸沙岸湄。","自憐生處樂，不奪鳳皇池。"]', '["止宿鴛鴦鸟，一雄兼一雌。","銜花相共食，刷羽每相隨。","戲入煙霄裏，宿归沙岸湄。","自怜生处乐，不奪鳳皇池。"]', '诗', 'shi', '', NULL, '詩三百三首 一百九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd94cd6-1c36-4324-b38b-f370e6d4e66c', '詩三百三首 一百一十', '诗三百三首 一百一十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["或有衒行人，才藝過周孔。","見罷頭兀兀，看時身侗侗。","繩牽未肯行，錐刺猶不動。","恰似羊公鶴，可憐生氃氋。"]', '["或有衒行人，才藝過周孔。","见罷头兀兀，看时身侗侗。","繩牽未肯行，錐刺猶不动。","恰似羊公鹤，可怜生氃氋。"]', '诗', 'shi', '', NULL, '詩三百三首 一百一十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a98770e-adf5-4781-9ce9-c9df33df17f4', '詩三百三首 一一一', '诗三百三首 一一一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["少小帶經鋤，本將兄共居。","緣遭他輩責，剩被自妻疎。","拋絕紅塵境，常遊好閱書。","誰能借斗水，活取轍中魚。"]', '["少小带經鋤，本將兄共居。","緣遭他輩責，剩被自妻疎。","拋絕紅塵境，常游好閱书。","誰能借斗水，活取轍中鱼。"]', '诗', 'shi', '', NULL, '詩三百三首 一一一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ecc2ab-e112-4e8d-8ebf-0ec00804ff82', '詩三百三首 一一二', '诗三百三首 一一二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["變化計無窮，生死竟不止。","三途鳥雀身，五嶽龍魚已。","世濁作𦎔羺，時清爲騄駬。","前迴是富兒，今度成貧士。"]', '["变化計無窮，生死竟不止。","三途鸟雀身，五嶽龙鱼已。","世濁作𦎔羺，时清爲騄駬。","前迴是富兒，今度成貧士。"]', '诗', 'shi', '', NULL, '詩三百三首 一一二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9e03ac-af78-4f4c-86bd-20daa0e1f4b8', '詩三百三首 一一三', '诗三百三首 一一三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["書判全非弱，嫌身不得官。","銓曹被拗折，洗垢覓瘡瘢。","必也關天命，今冬更試看。","盲兒射雀目，偶中亦非難。"]', '["书判全非弱，嫌身不得官。","銓曹被拗折，洗垢覓瘡瘢。","必也关天命，今冬更試看。","盲兒射雀目，偶中亦非难。"]', '诗', 'shi', '', NULL, '詩三百三首 一一三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba1e5f33-0a08-4737-b426-c3ce6650904e', '詩三百三首 一一四', '诗三百三首 一一四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["貧驢欠一尺，富狗剩三寸。","若分貧不平，中半富與困。","始取驢飽足，却令狗飢頓。","爲汝熟思量，令我也愁悶。"]', '["貧驢欠一尺，富狗剩三寸。","若分貧不平，中半富與困。","始取驢飽足，却令狗飢頓。","爲汝熟思量，令我也愁悶。"]', '诗', 'shi', '', NULL, '詩三百三首 一一四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('148737bd-4a03-450a-b3af-1b9af9e59ff3', '詩三百三首 一一五', '诗三百三首 一一五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["柳郎八十二，藍嫂一十八。","夫妻共百年，相憐情狡猾。","弄璋字烏䖘，擲瓦名婠妠。","屢見枯楊荑，常遭青女殺。"]', '["柳郎八十二，藍嫂一十八。","夫妻共百年，相怜情狡猾。","弄璋字烏䖘，擲瓦名婠妠。","屢见枯楊荑，常遭青女殺。"]', '诗', 'shi', '', NULL, '詩三百三首 一一五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf4d957-05e0-433d-ba92-6350586ed4d4', '詩三百三首 一一六', '诗三百三首 一一六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["大有飢寒客，生將獸魚殊。","長存磨石下，時哭路邊隅。","累日空思飯，經冬不識襦。","唯齎一束草，幷帶五升麩。"]', '["大有飢寒客，生將獸鱼殊。","长存磨石下，时哭路邊隅。","累日空思飯，經冬不識襦。","唯齎一束草，幷带五升麩。"]', '诗', 'shi', '', NULL, '詩三百三首 一一六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd13e9e2-eb50-404c-bf49-25895121e679', '詩三百三首 一一七', '诗三百三首 一一七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["赫赫誰𤮧肆，其酒甚濃厚。","可憐高幡幟，極目平升斗。","何意訝不售，其家多猛狗。","童子欲來沽，狗齩便是走。"]', '["赫赫誰𤮧肆，其酒甚濃厚。","可怜高幡幟，極目平升斗。","何意訝不售，其家多猛狗。","童子欲来沽，狗齩便是走。"]', '诗', 'shi', '', NULL, '詩三百三首 一一七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c874d0f0-2433-4e20-b670-cfc49297cdc3', '詩三百三首 一一八', '诗三百三首 一一八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["吁嗟濁濫處，羅剎共賢人。","謂是等流類，焉知道不親。","狐假師子勢，詐妄却稱珍。","鉛礦入鑪冶，方知金不知。"]', '["吁嗟濁濫处，羅剎共賢人。","謂是等流類，焉知道不親。","狐假師子勢，詐妄却稱珍。","鉛礦入鑪冶，方知金不知。"]', '诗', 'shi', '', NULL, '詩三百三首 一一八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f81363-833c-48ab-b133-af9f0181fef4', '詩三百三首 一一九', '诗三百三首 一一九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["田家避暑月，斗酒共誰歡。","雜雜排山果，疎疎圍酒罇。","蘆莦將代席，蕉葉且充盤。","醉後搘頤坐，須彌小彈丸。"]', '["田家避暑月，斗酒共誰歡。","杂杂排山果，疎疎圍酒罇。","蘆莦將代席，蕉葉且充盤。","醉後搘頤坐，須彌小彈丸。"]', '诗', 'shi', '', NULL, '詩三百三首 一一九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc20706-80b9-4bef-8b73-9634fc9fd972', '詩三百三首 一百二十', '诗三百三首 一百二十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["箇是何措大，時來省南院。","年可三十餘，曾經四五選。","囊裏無青蚨，篋中有黃絹。","行到食店前，不敢暫迴面。"]', '["箇是何措大，时来省南院。","年可三十餘，曾經四五選。","囊裏無青蚨，篋中有黄絹。","行到食店前，不敢暫迴面。"]', '诗', 'shi', '', NULL, '詩三百三首 一百二十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b69daf4-dead-43a1-8140-636540117a46', '詩三百三首 一二一', '诗三百三首 一二一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["爲人常喫用，愛意須慳惜。","老去不自由，漸被他推斥。","送向荒山頭，一生願虛擲。","亡羊罷補牢，失意終無極。"]', '["爲人常喫用，愛意須慳惜。","老去不自由，漸被他推斥。","送向荒山头，一生願虛擲。","亡羊罷補牢，失意終無極。"]', '诗', 'shi', '', NULL, '詩三百三首 一二一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcf8e29-1fad-4710-a667-d6e1563181a2', '詩三百三首 一二二', '诗三百三首 一二二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["浪造凌霄閣，虛登百尺樓。","養生仍夭命，誘讀詎封侯。","不用從黃口，何須厭白頭。","未能端似箭，且莫曲如鉤。"]', '["浪造凌霄閣，虛登百尺楼。","養生仍夭命，誘读詎封侯。","不用從黄口，何須厭白头。","未能端似箭，且莫曲如鉤。"]', '诗', 'shi', '', NULL, '詩三百三首 一二二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc703a21-bba8-4e98-ba0a-ba884de37a81', '詩三百三首 一二三', '诗三百三首 一二三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["雲山疊疊連天碧，路僻林深無客遊。","遠望孤蟾明皎皎，近聞羣鳥語啾啾。","老夫獨坐棲青嶂，少室閑居任白頭。","可歎往年與今日，無心還似水東流。"]', '["云山叠叠連天碧，路僻林深無客游。","远望孤蟾明皎皎，近闻羣鸟語啾啾。","老夫独坐棲青嶂，少室闲居任白头。","可歎往年與今日，無心還似水东流。"]', '诗', 'shi', '', NULL, '詩三百三首 一二三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cff0ac-7cbf-40ec-b67e-9b230b3d635e', '詩三百三首 一二四', '诗三百三首 一二四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["富貴疎親聚，只爲多錢米。","貧賤骨肉離，非關少兄弟。","急須歸去來，招賢閣未啓。","浪行朱雀街，踏破皮鞋底。"]', '["富貴疎親聚，只爲多錢米。","貧賤骨肉離，非关少兄弟。","急須归去来，招賢閣未啓。","浪行朱雀街，踏破皮鞋底。"]', '诗', 'shi', '', NULL, '詩三百三首 一二四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cec929d-88f7-4907-93b3-2dcfa3c0ba79', '詩三百三首 一二五', '诗三百三首 一二五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見一癡漢，仍居三兩婦。","養得八九兒，總是隨宜手。","丁防是新差，資財非舊有。","黃蘖作驢鞦，始知苦在後。"]', '["我见一癡漢，仍居三兩婦。","養得八九兒，總是隨宜手。","丁防是新差，資財非旧有。","黄蘖作驢鞦，始知苦在後。"]', '诗', 'shi', '', NULL, '詩三百三首 一二五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4cae778-cfce-4787-ab73-1a7323db4860', '詩三百三首 一二六', '诗三百三首 一二六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["新穀尚未熟，舊穀今已無。","就貸一斗許，門外立踟躕。","夫出教問婦，婦出遣問夫。","慳惜不救乏，財多爲累愚。"]', '["新穀尚未熟，旧穀今已無。","就貸一斗許，门外立踟躕。","夫出教问婦，婦出遣问夫。","慳惜不救乏，財多爲累愚。"]', '诗', 'shi', '', NULL, '詩三百三首 一二六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb478b39-8ba7-4732-8182-af3f122ba32f', '詩三百三首 一二七', '诗三百三首 一二七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["大有好笑事，畧陳三五箇。","張公富奢華，孟子貧轗軻。","只取侏儒飽，不憐方朔餓。","巴歌唱者多，白雪無人和。"]', '["大有好笑事，畧陳三五箇。","張公富奢华，孟子貧轗軻。","只取侏儒飽，不怜方朔餓。","巴歌唱者多，白雪無人和。"]', '诗', 'shi', '', NULL, '詩三百三首 一二七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f324252-fade-4634-abc1-e0dbb7a507e3', '詩三百三首 一二八', '诗三百三首 一二八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["老翁娶少婦，髮白婦不耐。","老婆嫁少夫，面黃夫不愛。","老翁娶老婆，一一無棄背。","少婦嫁少夫，兩兩相憐態。"]', '["老翁娶少婦，髮白婦不耐。","老婆嫁少夫，面黄夫不愛。","老翁娶老婆，一一無棄背。","少婦嫁少夫，兩兩相怜態。"]', '诗', 'shi', '', NULL, '詩三百三首 一二八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('357ba0cf-312b-475c-bfe5-ba8ee9539360', '詩三百三首 一二九', '诗三百三首 一二九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["雍容美少年，博覽諸經史。","盡號曰先生，皆稱爲學士。","未能得官職，不解秉耒耜。","冬披破布衫，蓋是書誤己。"]', '["雍容美少年，博覽諸經史。","尽號曰先生，皆稱爲学士。","未能得官職，不解秉耒耜。","冬披破布衫，蓋是书誤己。"]', '诗', 'shi', '', NULL, '詩三百三首 一二九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c44716-7e92-423a-94c8-58ceaa7b30e2', '詩三百三首 一三○', '诗三百三首 一三○', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["鳥語情不堪，其時臥草菴。","櫻桃紅爍爍，楊柳正毿毿。","旭日銜青嶂，晴雲洗淥潭。","誰知出塵俗，馭上寒山南。"]', '["鸟語情不堪，其时臥草菴。","櫻桃紅爍爍，楊柳正毿毿。","旭日銜青嶂，晴云洗淥潭。","誰知出塵俗，馭上寒山南。"]', '诗', 'shi', '', NULL, '詩三百三首 一三○ 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf91ed12-db3d-40fe-bc9d-ec264dd0d097', '詩三百三首 一三一', '诗三百三首 一三一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昨日何悠悠，場中可憐許。","上爲桃李徑，下作蘭蓀渚。","復有綺羅人，舍中翠毛羽。","相逢欲相喚，脈脈不能語。"]', '["昨日何悠悠，場中可怜許。","上爲桃李徑，下作蘭蓀渚。","复有綺羅人，舍中翠毛羽。","相逢欲相喚，脈脈不能語。"]', '诗', 'shi', '', NULL, '詩三百三首 一三一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01240f01-978c-409d-aec0-572e34a6e872', '詩三百三首 一三二', '诗三百三首 一三二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["丈夫莫守困，無錢須經紀。","養得一牸牛，生得五犢子。","犢子又生兒，積數無窮已。","寄語陶朱公，富與君相似。"]', '["丈夫莫守困，無錢須經紀。","養得一牸牛，生得五犢子。","犢子又生兒，積數無窮已。","寄語陶朱公，富與君相似。"]', '诗', 'shi', '', NULL, '詩三百三首 一三二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3e45c4-f886-4c3c-a08c-8fbdaeda917b', '詩三百三首 一三三', '诗三百三首 一三三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["之字何惶惶，卜居須自審。","南方瘴癘多，北地風霜甚。","荒陬不可居，毒川難可飲。","魂兮歸去來，食我家園葚。"]', '["之字何惶惶，卜居須自審。","南方瘴癘多，北地风霜甚。","荒陬不可居，毒川难可饮。","魂兮归去来，食我家园葚。"]', '诗', 'shi', '', NULL, '詩三百三首 一三三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92194ad5-b8b3-45d5-a569-4305ba687d63', '詩三百三首 一三四', '诗三百三首 一三四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昨夜夢還家，見婦機中織。","駐梭如有思，擎梭似無力。","呼之迴面視，況復不相識。","應是別多年，鬢毛非舊色。"]', '["昨夜梦還家，见婦機中织。","駐梭如有思，擎梭似無力。","呼之迴面視，況复不相識。","應是別多年，鬢毛非旧色。"]', '诗', 'shi', '', NULL, '詩三百三首 一三四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a10879-0640-4c60-b606-95d31af1118a', '詩三百三首 一三五', '诗三百三首 一三五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["人生不滿百，常懷千載憂。","自身病始可，又爲子孫愁。","下視禾根土，上看桑樹頭。","秤鎚落東海，到底始知休。"]', '["人生不满百，常懷千載憂。","自身病始可，又爲子孫愁。","下視禾根土，上看桑樹头。","秤鎚落东海，到底始知休。"]', '诗', 'shi', '', NULL, '詩三百三首 一三五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e163fb15-195d-4e80-a07e-d7d189897df0', '詩三百三首 一三六', '诗三百三首 一三六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有一等流，悠悠似木頭。","出語無知解，云我百不憂。","問道道不會，問佛佛不求。","子細推尋著，茫然一場愁。"]', '["世有一等流，悠悠似木头。","出語無知解，云我百不憂。","问道道不會，问佛佛不求。","子細推尋著，茫然一場愁。"]', '诗', 'shi', '', NULL, '詩三百三首 一三六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb43ee21-be42-4afe-961c-ebe440f945e0', '詩三百三首 一三七', '诗三百三首 一三七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["董郎年少時，出入帝京裏。","衫作嫩鵝黃，容儀畫相似。","常騎踏雪馬，拂拂紅塵起。","觀者滿路傍，箇是誰家子。"]', '["董郎年少时，出入帝京裏。","衫作嫩鵝黄，容儀畫相似。","常騎踏雪马，拂拂紅塵起。","观者满路傍，箇是誰家子。"]', '诗', 'shi', '', NULL, '詩三百三首 一三七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cef1bfd-82d7-441f-b55f-d81b50034ff3', '詩三百三首 一三八', '诗三百三首 一三八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["箇是誰家子，爲人大被憎。","癡心常憤憤，肉眼醉瞢瞢。","見佛不禮佛，逢僧不施僧。","唯知打大臠，除此百無能。"]', '["箇是誰家子，爲人大被憎。","癡心常憤憤，肉眼醉瞢瞢。","见佛不禮佛，逢僧不施僧。","唯知打大臠，除此百無能。"]', '诗', 'shi', '', NULL, '詩三百三首 一三八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65cc1249-2fa1-459a-b2c9-38813b108df5', '詩三百三首 一三九', '诗三百三首 一三九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["人以身爲本，本以心爲柄。","本在心莫邪，心邪喪本命。","未能免此殃，何言嬾照鏡。","不念金剛經，却令菩薩病。"]', '["人以身爲本，本以心爲柄。","本在心莫邪，心邪喪本命。","未能免此殃，何言嬾照镜。","不念金剛經，却令菩薩病。"]', '诗', 'shi', '', NULL, '詩三百三首 一三九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1df98c2-11ec-4cee-9bba-ca11a587e4f7', '詩三百三首 一百四十', '诗三百三首 一百四十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["城北仲家翁，渠家多酒肉。","仲翁婦死時，弔客滿堂屋。","仲翁自身亡，能無一人哭。","喫他桮臠者，何太冷心腹。"]', '["城北仲家翁，渠家多酒肉。","仲翁婦死时，弔客满堂屋。","仲翁自身亡，能無一人哭。","喫他桮臠者，何太冷心腹。"]', '诗', 'shi', '', NULL, '詩三百三首 一百四十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14717c81-6fef-48fa-9068-9a47b0bcb527', '詩三百三首 一四一', '诗三百三首 一四一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["下愚讀我詩，不解却嗤誚。","中庸讀我詩，思量云甚要。","上賢讀我詩，把著滿面笑。","楊修見幼婦，一覽便知妙。"]', '["下愚读我诗，不解却嗤誚。","中庸读我诗，思量云甚要。","上賢读我诗，把著满面笑。","楊修见幼婦，一覽便知妙。"]', '诗', 'shi', '', NULL, '詩三百三首 一四一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a630e407-55e6-4abd-857d-1e285cf3a5c9', '詩三百三首 一四二', '诗三百三首 一四二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自有慳惜人，我非慳惜輩。","衣單爲舞穿，酒盡緣歌啐。","當取一腹飽，莫令兩脚儽。","蓬蒿鑽髑髏，此日君應悔。"]', '["自有慳惜人，我非慳惜輩。","衣單爲舞穿，酒尽緣歌啐。","當取一腹飽，莫令兩脚儽。","蓬蒿鑽髑髏，此日君應悔。"]', '诗', 'shi', '', NULL, '詩三百三首 一四二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e175af1f-d771-4a9a-8f4e-35c1aee728b8', '詩三百三首 一四三', '诗三百三首 一四三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我行經古墳，淚盡嗟存沒。","塚破壓黃腸，棺穿露白骨。","欹斜有甕缾，掁撥無簪笏。","風至攬其中，灰塵亂𡋯𡋯。"]', '["我行經古墳，泪尽嗟存沒。","塚破壓黄腸，棺穿露白骨。","欹斜有甕缾，掁撥無簪笏。","风至攬其中，灰塵亂𡋯𡋯。"]', '诗', 'shi', '', NULL, '詩三百三首 一四三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a28b3106-f605-4056-b7e6-e89468372bc6', '詩三百三首 一四四', '诗三百三首 一四四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["夕陽赫西山，草木光曄曄。","復有朦朧處，松蘿相連接。","此中多伏虎，見我奮迅鬣。","手中無寸刃，爭不懼懾懾。"]', '["夕陽赫西山，草木光曄曄。","复有朦朧处，松蘿相連接。","此中多伏虎，见我奮迅鬣。","手中無寸刃，爭不懼懾懾。"]', '诗', 'shi', '', NULL, '詩三百三首 一四四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d43d57e1-94bb-4b47-ae48-7bd031101b76', '詩三百三首 一四五', '诗三百三首 一四五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["出身既擾擾，世事非一狀。","未能捨流俗，所以相追訪。","昨弔徐五死，今送劉三葬。","終日不得閑，爲此心悽愴。"]', '["出身既擾擾，世事非一狀。","未能捨流俗，所以相追訪。","昨弔徐五死，今送劉三葬。","終日不得闲，爲此心悽愴。"]', '诗', 'shi', '', NULL, '詩三百三首 一四五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7430ff3a-1443-4f87-bc9c-cebedb2fa366', '詩三百三首 一四六', '诗三百三首 一四六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有樂且須樂，時哉不可失。","雖云一百年，豈滿三萬日。","寄世是須臾，論錢莫啾唧。","孝經末後章，委曲陳情畢。"]', '["有乐且須乐，时哉不可失。","雖云一百年，豈满三万日。","寄世是須臾，論錢莫啾唧。","孝經末後章，委曲陳情畢。"]', '诗', 'shi', '', NULL, '詩三百三首 一四六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941162d2-9d37-48ee-a9e9-93c7baa907ac', '詩三百三首 一四七', '诗三百三首 一四七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["獨坐常忽忽，情懷何悠悠。","山腰雲縵縵，谷口風颼颼。","猨來樹嫋嫋，鳥入林啾啾。","時催鬢颯颯，歲盡老惆惆。"]', '["独坐常忽忽，情懷何悠悠。","山腰云縵縵，谷口风颼颼。","猨来樹嫋嫋，鸟入林啾啾。","时催鬢颯颯，歲尽老惆惆。"]', '诗', 'shi', '', NULL, '詩三百三首 一四七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7cdaef4-bdae-48aa-8daf-3f67393d64cc', '詩三百三首 一四八', '诗三百三首 一四八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一人好頭肚，六藝盡皆通。","南見驅歸北，西風趂向東。","長漂如泛萍，不息似飛蓬。","問是何等色，姓貧名曰窮。"]', '["一人好头肚，六藝尽皆通。","南见驱归北，西风趂向东。","长漂如泛萍，不息似飞蓬。","问是何等色，姓貧名曰窮。"]', '诗', 'shi', '', NULL, '詩三百三首 一四八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2a9006-11ee-4c8f-9155-ef81ea9fd6b5', '詩三百三首 一四九', '诗三百三首 一四九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["他賢君即受，不賢君莫與。","君賢他見容，不賢他亦拒。","嘉善矜不能，仁徒方得所。","勸逐子張言，拋却卜商語。"]', '["他賢君即受，不賢君莫與。","君賢他见容，不賢他亦拒。","嘉善矜不能，仁徒方得所。","勸逐子張言，拋却卜商語。"]', '诗', 'shi', '', NULL, '詩三百三首 一四九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069308be-e25a-473e-91d4-c346a0c71bbe', '詩三百三首 一百五十', '诗三百三首 一百五十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["俗薄真成薄，人心箇不同。","殷翁笑柳老，柳老笑殷翁。","何故兩相笑，俱行譣詖中。","裝車競嵽嵲，翻載各瀧涷。"]', '["俗薄真成薄，人心箇不同。","殷翁笑柳老，柳老笑殷翁。","何故兩相笑，俱行譣詖中。","裝车競嵽嵲，翻載各瀧涷。"]', '诗', 'shi', '', NULL, '詩三百三首 一百五十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35723ded-7d9f-407a-882e-120dd9c6ba88', '詩三百三首 一五一', '诗三百三首 一五一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["是我有錢日，恆爲汝貸將。","汝今既飽暖，見我不分張。","須憶汝欲得，似我今承望。","有無更代事，勸汝熟思量。"]', '["是我有錢日，恆爲汝貸將。","汝今既飽暖，见我不分張。","須憶汝欲得，似我今承望。","有無更代事，勸汝熟思量。"]', '诗', 'shi', '', NULL, '詩三百三首 一五一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ab37b7-5de6-440b-afa5-fa176d243127', '詩三百三首 一五二', '诗三百三首 一五二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["人生一百年，佛說十二部。","慈悲如野鹿，瞋忿似家狗。","家狗趂不去，野鹿常好走。","欲伏獼猴心，須聽獅子吼。"]', '["人生一百年，佛说十二部。","慈悲如野鹿，瞋忿似家狗。","家狗趂不去，野鹿常好走。","欲伏獼猴心，須听獅子吼。"]', '诗', 'shi', '', NULL, '詩三百三首 一五二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8410522-1d55-434d-aa98-9fcc1987f7b1', '詩三百三首 一五三', '诗三百三首 一五三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["教汝數般事，思量知我賢。","極貧忍賣屋，纔富須買田。","空腹不得走，枕頭須莫眠。","此言期衆見，挂在日東邊。"]', '["教汝數般事，思量知我賢。","極貧忍賣屋，纔富須買田。","空腹不得走，枕头須莫眠。","此言期衆见，挂在日东邊。"]', '诗', 'shi', '', NULL, '詩三百三首 一五三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355d794f-e5cb-4631-b9ba-d72add045355', '詩三百三首 一五四', '诗三百三首 一五四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山多幽奇，登者皆恒懾。","月照水澄澄，風吹草獵獵。","凋梅雪作花，杌木雲充葉。","觸雨轉鮮靈，非晴不可涉。"]', '["寒山多幽奇，登者皆恒懾。","月照水澄澄，风吹草獵獵。","凋梅雪作花，杌木云充葉。","觸雨轉鲜靈，非晴不可涉。"]', '诗', 'shi', '', NULL, '詩三百三首 一五四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28c02203-ae21-40b5-b836-3a4fd23c82fc', '詩三百三首 一五五', '诗三百三首 一五五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有樹先林生，計年逾一倍。","根遭陵谷變，葉被風霜改。","咸笑外凋零，不憐內文采。","皮膚脫落盡，唯有貞實在。"]', '["有樹先林生，計年逾一倍。","根遭陵谷变，葉被风霜改。","咸笑外凋零，不怜內文采。","皮膚脫落尽，唯有貞實在。"]', '诗', 'shi', '', NULL, '詩三百三首 一五五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7296b47a-6353-421a-9516-934a0da02198', '詩三百三首 一五六', '诗三百三首 一五六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山有躶蟲，身白而頭黑。","手把兩卷書，一道將一德。","住不安釜竈，行不齎衣裓。","常持智慧劒，擬破煩惱賊。"]', '["寒山有躶蟲，身白而头黑。","手把兩卷书，一道將一德。","住不安釜竈，行不齎衣裓。","常持智慧劒，擬破煩惱賊。"]', '诗', 'shi', '', NULL, '詩三百三首 一五六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da1293b5-cc71-4f47-9e18-c46dc3857cb1', '詩三百三首 一五七', '诗三百三首 一五七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有人畏白首，不肯捨朱紱。","采藥空求仙，根苗亂挑掘。","數年無效驗，癡意瞋怫鬱。","獵師披袈裟，元非汝使物。"]', '["有人畏白首，不肯捨朱紱。","采藥空求仙，根苗亂挑掘。","數年無效驗，癡意瞋怫鬱。","獵師披袈裟，元非汝使物。"]', '诗', 'shi', '', NULL, '詩三百三首 一五七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481695e0-5fa5-4c84-a28d-fa5cd0eaeddc', '詩三百三首 一五八', '诗三百三首 一五八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昔時可可貧，今朝最貧凍。","作事不諧和，觸途成倥傯。","行泥屢脚屈，坐社頻腹痛。","失却斑猫兒，老鼠圍飯甕。"]', '["昔时可可貧，今朝最貧凍。","作事不諧和，觸途成倥傯。","行泥屢脚屈，坐社頻腹痛。","失却斑猫兒，老鼠圍飯甕。"]', '诗', 'shi', '', NULL, '詩三百三首 一五八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae720546-eca1-47b7-ac4b-742e54b9a805', '詩三百三首 一五九', '诗三百三首 一五九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見世間人，堂堂好儀相。","不報父母恩，方寸底模樣。","欠負他人錢，蹄穿始惆悵。","箇箇惜妻兒，爺孃不供養。","兄弟似冤家，心中長悵怏。","憶昔少年時，求神願成長。","今爲不孝子，世間多此樣。","買肉自家噇，抹觜道我暢。","自逞說嘍囉，聰明無益當。","牛頭努目瞋，出去始時曏。","擇佛燒好香，揀僧歸供養。","羅漢門前乞，趂却閑和尚。","不悟無爲人，從來無相狀。","封疏請名僧，䞋錢兩三樣。","雲光好法師，安角在頭上。","汝無平等心，聖賢俱不降。","凡聖皆混然，勸君休取相。","我法妙難思，天龍盡迴向。","我今稽首禮，無上法中王。","慈悲大喜捨，名稱滿十方。","衆生作依怙，智慧身金剛。","頂禮無所著，我師大法王。"]', '["我见世间人，堂堂好儀相。","不報父母恩，方寸底模樣。","欠負他人錢，蹄穿始惆悵。","箇箇惜妻兒，爺孃不供養。","兄弟似冤家，心中长悵怏。","憶昔少年时，求神願成长。","今爲不孝子，世间多此樣。","買肉自家噇，抹觜道我暢。","自逞说嘍囉，聰明無益當。","牛头努目瞋，出去始时曏。","擇佛燒好香，揀僧归供養。","羅漢门前乞，趂却闲和尚。","不悟無爲人，從来無相狀。","封疏請名僧，䞋錢兩三樣。","云光好法師，安角在头上。","汝無平等心，聖賢俱不降。","凡聖皆混然，勸君休取相。","我法妙难思，天龙尽迴向。","我今稽首禮，無上法中王。","慈悲大喜捨，名稱满十方。","衆生作依怙，智慧身金剛。","頂禮無所著，我師大法王。"]', '诗', 'shi', '', NULL, '詩三百三首 一五九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151b7e3c-9ce0-4fab-aa77-738fde64ba1f', '詩三百三首 一百六十', '诗三百三首 一百六十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可貴天然物，獨一無伴侶。","覓他不可見，出入無門戶。","促之在方寸，延之一切處。","你若不信愛，相逢不相遇。"]', '["可貴天然物，独一無伴侶。","覓他不可见，出入無门戶。","促之在方寸，延之一切处。","你若不信愛，相逢不相遇。"]', '诗', 'shi', '', NULL, '詩三百三首 一百六十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5c6dab-0d5e-451d-b60b-e5038af7f2d7', '詩三百三首 一六一', '诗三百三首 一六一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余家有一窟，窟中無一物。","淨潔空堂堂，光華明日日。","䔫食養微軀，布裘遮幻質。","任你千聖現，我有天真佛。"]', '["余家有一窟，窟中無一物。","淨潔空堂堂，光华明日日。","䔫食養微軀，布裘遮幻質。","任你千聖現，我有天真佛。"]', '诗', 'shi', '', NULL, '詩三百三首 一六一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41452555-b341-4871-8bb1-04bd0ebf6f97', '詩三百三首 一六二', '诗三百三首 一六二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["男兒大丈夫，作事莫莽鹵。","勁挺鐵石心，直取菩提路。","邪路不用行，行之枉辛苦。","不要求佛果，識取心王主。"]', '["男兒大丈夫，作事莫莽鹵。","勁挺鐵石心，直取菩提路。","邪路不用行，行之枉辛苦。","不要求佛果，識取心王主。"]', '诗', 'shi', '', NULL, '詩三百三首 一六二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793d041b-e71b-4766-b5d2-0c88d83e7d79', '詩三百三首 一六三', '诗三百三首 一六三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["粵自居寒山，曾經幾萬載。","任運遯林泉，棲遲觀自在。","寒巖人不到，白雲常靉靆。","細草作臥褥，青天爲被蓋。","快活枕石頭，天地任變改。"]', '["粵自居寒山，曾經幾万載。","任運遯林泉，棲遲观自在。","寒巖人不到，白云常靉靆。","細草作臥褥，青天爲被蓋。","快活枕石头，天地任变改。"]', '诗', 'shi', '', NULL, '詩三百三首 一六三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07a854fa-70e1-4f19-881f-6527886dc163', '詩三百三首 一六四', '诗三百三首 一六四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可重是寒山，白雲常自閑。","猨啼暢道內，虎嘯出人間。","獨步石可履，孤吟藤好攀。","松風清颯颯，鳥語聲𠴨𠴨。"]', '["可重是寒山，白云常自闲。","猨啼暢道內，虎嘯出人间。","独步石可履，孤吟藤好攀。","松风清颯颯，鸟語声𠴨𠴨。"]', '诗', 'shi', '', NULL, '詩三百三首 一六四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f00f1b-fa25-457b-b8bc-efb675347daa', '詩三百三首 一六五', '诗三百三首 一六五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["閑自訪高僧，煙山萬萬層。","師親指歸路，月挂一輪燈。"]', '["闲自訪高僧，煙山万万層。","師親指归路，月挂一輪灯。"]', '诗', 'shi', '', NULL, '詩三百三首 一六五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db4b0d22-3550-46e1-bb26-410025207ff4', '詩三百三首 一六六', '诗三百三首 一六六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["閑遊華頂上，日朗晝光輝。","四顧晴空裏，白雲同鶴飛。"]', '["闲游华頂上，日朗晝光輝。","四顧晴空裏，白云同鹤飞。"]', '诗', 'shi', '', NULL, '詩三百三首 一六六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5442868b-5e64-4c02-bd4f-0ebc692b490b', '詩三百三首 一六七', '诗三百三首 一六七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有多事人，廣學諸知見。","不識本真性，與道轉懸遠。","若能明實相，豈用陳虛願。","一念了自心，開佛之知見。"]', '["世有多事人，廣学諸知见。","不識本真性，與道轉懸远。","若能明實相，豈用陳虛願。","一念了自心，开佛之知见。"]', '诗', 'shi', '', NULL, '詩三百三首 一六七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc16a49b-04dc-46ae-9540-723733c27238', '詩三百三首 一六八', '诗三百三首 一六八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山有一宅，宅中無闌隔。","六門左右通，堂中見天碧。","房房虛索索，東壁打西壁。","其中一物無，免被人來惜。","寒到燒輭火，飢來煮菜喫。","不學田舍翁，廣置牛莊宅。","盡作地獄業，一入何曾極。","好好善思量，思量知軌則。"]', '["寒山有一宅，宅中無闌隔。","六门左右通，堂中见天碧。","房房虛索索，东壁打西壁。","其中一物無，免被人来惜。","寒到燒輭火，飢来煮菜喫。","不学田舍翁，廣置牛莊宅。","尽作地獄業，一入何曾極。","好好善思量，思量知軌則。"]', '诗', 'shi', '', NULL, '詩三百三首 一六八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3737a1-bf9d-462f-82c8-a619df2df424', '詩三百三首 一六九', '诗三百三首 一六九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["儂家暫下山，入到城隍裏。","逢見一羣女，端正容貌美。","頭帶蜀樣花，燕脂塗粉膩。","金釧鏤銀朵，羅衣緋紅紫。","朱顏類神仙，香帶氛氳氣。","時人皆顧盼，癡愛染心意。","謂言世無雙，魂影隨他去。","狗齩枯骨頭，虛自舐脣齒。","不解返思量，與畜何曾異。","今成白髮婆，老陋若精魅。","無始由狗心，不超解脫地。"]', '["儂家暫下山，入到城隍裏。","逢见一羣女，端正容貌美。","头带蜀樣花，燕脂塗粉膩。","金釧鏤銀朵，羅衣緋紅紫。","朱顏類神仙，香带氛氳氣。","时人皆顧盼，癡愛染心意。","謂言世無雙，魂影隨他去。","狗齩枯骨头，虛自舐脣齒。","不解返思量，與畜何曾異。","今成白髮婆，老陋若精魅。","無始由狗心，不超解脫地。"]', '诗', 'shi', '', NULL, '詩三百三首 一六九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b700323-b9c3-449c-91c8-d017310b6926', '詩三百三首 一百七十', '诗三百三首 一百七十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一自遯寒山，養命餐山果。","平生何所憂，此世隨緣過。","日月如逝川，光陰石中火。","任你天地移，我暢巖中坐。"]', '["一自遯寒山，養命餐山果。","平生何所憂，此世隨緣過。","日月如逝川，光陰石中火。","任你天地移，我暢巖中坐。"]', '诗', 'shi', '', NULL, '詩三百三首 一百七十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ed9dc17-96df-48a3-873e-fdbe89d74596', '詩三百三首 一七一', '诗三百三首 一七一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見世間人，茫茫走路塵。","不知此中事，將何爲去津。","榮華能幾日，眷屬片時親。","縱有千斤金，不如林下貧。"]', '["我见世间人，茫茫走路塵。","不知此中事，將何爲去津。","榮华能幾日，眷屬片时親。","縱有千斤金，不如林下貧。"]', '诗', 'shi', '', NULL, '詩三百三首 一七一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08565735-813e-44e8-b349-dbf0e06fcf54', '詩三百三首 一七二', '诗三百三首 一七二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自聞梁朝日，四依諸賢士。","寶志萬迴師，四仙傅大士。","顯揚一代教，作時如來使。","造建僧伽藍，信心歸佛理。","雖乃得如斯，有爲多患累。","與道殊懸遠，折西補東爾。","不達無爲功，損多益少利。","有聲而無形，至今何處去。"]', '["自闻梁朝日，四依諸賢士。","寶志万迴師，四仙傅大士。","显揚一代教，作时如来使。","造建僧伽藍，信心归佛理。","雖乃得如斯，有爲多患累。","與道殊懸远，折西補东爾。","不達無爲功，損多益少利。","有声而無形，至今何处去。"]', '诗', 'shi', '', NULL, '詩三百三首 一七二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50c3082-df12-4fa6-a476-ce552d52a145', '詩三百三首 一七三', '诗三百三首 一七三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["吁嗟貧復病，爲人絕友親。","甕裏長無飯，甑中屢生塵。","蓬菴不免雨，漏榻劣容身。","莫怪今憔悴，多愁定損人。"]', '["吁嗟貧复病，爲人絕友親。","甕裏长無飯，甑中屢生塵。","蓬菴不免雨，漏榻劣容身。","莫怪今憔悴，多愁定損人。"]', '诗', 'shi', '', NULL, '詩三百三首 一七三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a12f6b-7936-488d-95ac-d4ab081fdc5b', '詩三百三首 一七四', '诗三百三首 一七四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["養女畏太多，已生須訓誘。","捺頭遣小心，鞭背令緘口。","未解乘機杼，那堪事箕箒。","張婆語驢駒，汝大不如母。"]', '["養女畏太多，已生須訓誘。","捺头遣小心，鞭背令緘口。","未解乘機杼，那堪事箕箒。","張婆語驢駒，汝大不如母。"]', '诗', 'shi', '', NULL, '詩三百三首 一七四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5336bfc-41de-41ca-ba75-cd9079bf6595', '詩三百三首 一七五', '诗三百三首 一七五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["秉志不可卷，須知我匪席。","浪造山林中，獨臥盤陀石。","辯士來勸余，速令受金璧。","鑿牆植蓬蒿，若此非有益。"]', '["秉志不可卷，須知我匪席。","浪造山林中，独臥盤陀石。","辯士来勸余，速令受金璧。","鑿牆植蓬蒿，若此非有益。"]', '诗', 'shi', '', NULL, '詩三百三首 一七五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d13446a4-9f68-4376-807a-6f565e5b3fe7', '詩三百三首 一七六', '诗三百三首 一七六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["以我棲遲處，幽深難可論。","無風蘿自動，不霧竹長昏。","澗水緣誰咽，山雲忽自屯。","午時菴內坐，始覺日頭暾。"]', '["以我棲遲处，幽深难可論。","無风蘿自动，不霧竹长昏。","澗水緣誰咽，山云忽自屯。","午时菴內坐，始覺日头暾。"]', '诗', 'shi', '', NULL, '詩三百三首 一七六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd5ec13-45fd-495a-bcf8-ff214aba9f20', '詩三百三首 一七七', '诗三百三首 一七七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["憶昔遇逢處，人間逐勝遊。","樂山登萬仞，愛水泛千舟。","送客琵琶谷，攜琴鸚鵡洲。","焉知松樹下，抱膝冷颼颼。"]', '["憶昔遇逢处，人间逐勝游。","乐山登万仞，愛水泛千舟。","送客琵琶谷，携琴鸚鵡洲。","焉知松樹下，抱膝冷颼颼。"]', '诗', 'shi', '', NULL, '詩三百三首 一七七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd03234-4a5c-48fb-97ae-ca691787e827', '詩三百三首 一七八', '诗三百三首 一七八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["報汝修道者，進求虛勞神。","人有精靈物，無字復無文。","呼時歷歷應，隱處不居存。","叮嚀善保護，勿令有點痕。"]', '["報汝修道者，進求虛勞神。","人有精靈物，無字复無文。","呼时歷歷應，隐处不居存。","叮嚀善保護，勿令有点痕。"]', '诗', 'shi', '', NULL, '詩三百三首 一七八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f68ac4ad-7adc-4f45-8b5a-ab6d53fda1fc', '詩三百三首 一七九', '诗三百三首 一七九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["去年春鳥鳴，此時思弟兄。","今年秋菊爛，此時思發生。","綠水千腸咽，黃雲四面平。","哀哉百年內，腸斷憶咸京。"]', '["去年春鸟鳴，此时思弟兄。","今年秋菊爛，此时思發生。","綠水千腸咽，黄云四面平。","哀哉百年內，腸斷憶咸京。"]', '诗', 'shi', '', NULL, '詩三百三首 一七九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40a6c1e-0234-436d-93f7-0a18846663f6', '詩三百三首 一百八十', '诗三百三首 一百八十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["多少天台人，不識寒山子。","莫知真意度，喚作閑言語。"]', '["多少天台人，不識寒山子。","莫知真意度，喚作闲言語。"]', '诗', 'shi', '', NULL, '詩三百三首 一百八十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c1c3da-391e-4148-8b65-ea82f7c014b9', '詩三百三首 一八一', '诗三百三首 一八一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一住寒山萬事休，更無雜念挂心頭。","閑於石壁題詩句，任運還同不繫舟。"]', '["一住寒山万事休，更無杂念挂心头。","闲於石壁題诗句，任運還同不繫舟。"]', '诗', 'shi', '', NULL, '詩三百三首 一八一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbd7bfcd-a71c-4d9a-b3d2-92dc7e1b3f69', '詩三百三首 一八二', '诗三百三首 一八二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可惜百年屋，左倒右復傾。","牆壁分散盡，木植亂差橫。","甎瓦片片落，朽爛不堪停。","狂風吹驀榻，再豎卒難成。"]', '["可惜百年屋，左倒右复傾。","牆壁分散尽，木植亂差橫。","甎瓦片片落，朽爛不堪停。","狂风吹驀榻，再豎卒难成。"]', '诗', 'shi', '', NULL, '詩三百三首 一八二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('501d9d6d-d256-4c01-a216-232f7615a491', '詩三百三首 一八三', '诗三百三首 一八三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["精神殊爽爽，形貌極堂堂。","能射穿七札，讀書覽五行。","經眠虎頭枕，昔坐象牙牀。","若無一堵物，不啻冷如霜。"]', '["精神殊爽爽，形貌極堂堂。","能射穿七札，读书覽五行。","經眠虎头枕，昔坐象牙牀。","若無一堵物，不啻冷如霜。"]', '诗', 'shi', '', NULL, '詩三百三首 一八三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099d19f5-6d46-4b49-9b75-5dafaacdc2a8', '詩三百三首 一八四', '诗三百三首 一八四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["笑我田舍兒，頭頰底縶澀。","巾子未曾高，腰帶長時急。","非是不及時，無錢趂不及。","一日有錢財，浮圖頂上立。"]', '["笑我田舍兒，头頰底縶澀。","巾子未曾高，腰带长时急。","非是不及时，無錢趂不及。","一日有錢財，浮圖頂上立。"]', '诗', 'shi', '', NULL, '詩三百三首 一八四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311e8565-cae9-4113-8bd6-1aa8996b10a5', '詩三百三首 一八五', '诗三百三首 一八五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["買肉血{氵目舌}{氵目舌}，買魚跳鱍鱍。","君身招罪累，妻子成快活。","纔死渠便嫁，他人誰敢遏。","一朝如破牀，兩箇當頭脫。"]', '["買肉血{氵目舌}{氵目舌}，買鱼跳鱍鱍。","君身招罪累，妻子成快活。","纔死渠便嫁，他人誰敢遏。","一朝如破牀，兩箇當头脫。"]', '诗', 'shi', '', NULL, '詩三百三首 一八五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fda6302-82e6-492f-a9a0-197de20fd8dc', '詩三百三首 一八六', '诗三百三首 一八六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["客難寒山子，君詩無道理。","吾觀乎古人，貧賤不爲恥。","應之笑此言，談何疎闊矣。","願君似今日，錢是急事爾。"]', '["客难寒山子，君诗無道理。","吾观乎古人，貧賤不爲恥。","應之笑此言，談何疎闊矣。","願君似今日，錢是急事爾。"]', '诗', 'shi', '', NULL, '詩三百三首 一八六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9768b77-4ea3-46e7-b814-860dd70b60e3', '詩三百三首 一八七', '诗三百三首 一八七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["從生不往來，至死無仁義。","言既有枝葉，心懷便險詖。","若其開小道，緣此生大僞。","詐說造雲梯，削之成棘刺。"]', '["從生不往来，至死無仁義。","言既有枝葉，心懷便險詖。","若其开小道，緣此生大僞。","詐说造云梯，削之成棘刺。"]', '诗', 'shi', '', NULL, '詩三百三首 一八七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3b08999-a44c-410d-bfed-1121d9847d8d', '詩三百三首 一八八', '诗三百三首 一八八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一缾鑄金成，一缾埏泥出。","二缾任君看，那箇缾牢實。","欲知缾有二，須知業非一。","將此驗生因，修行在今日。"]', '["一缾鑄金成，一缾埏泥出。","二缾任君看，那箇缾牢實。","欲知缾有二，須知業非一。","將此驗生因，修行在今日。"]', '诗', 'shi', '', NULL, '詩三百三首 一八八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b230d68-0f52-4b51-8564-77c1c977ac70', '詩三百三首 一八九', '诗三百三首 一八九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["攜殘荒草廬，其中煙火蔚。","借問羣小兒，生來凡幾日。","門外有三車，迎之不肯出。","飽食腹膨脝，箇是癡頑物。"]', '["携殘荒草廬，其中煙火蔚。","借问羣小兒，生来凡幾日。","门外有三车，迎之不肯出。","飽食腹膨脝，箇是癡頑物。"]', '诗', 'shi', '', NULL, '詩三百三首 一八九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b18344-0ca4-42ff-a49d-2616e5f970c5', '詩三百三首 一百九十', '诗三百三首 一百九十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有身與無身，是我復非我。","如此審思量，遷延倚巖坐。","足間青草生，頂上紅塵墮。","已見俗中人，靈牀施酒果。"]', '["有身與無身，是我复非我。","如此審思量，遷延倚巖坐。","足间青草生，頂上紅塵墮。","已见俗中人，靈牀施酒果。"]', '诗', 'shi', '', NULL, '詩三百三首 一百九十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0f80e1-cbb9-4252-931f-5d2b042f9f40', '詩三百三首 一九一', '诗三百三首 一九一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昨見河邊樹，摧殘不可論。","二三餘幹在，千萬斧刀痕。","霜凋萎疎葉，波衝枯朽根。","生處當如此，何用怨乾坤。"]', '["昨见河邊樹，摧殘不可論。","二三餘幹在，千万斧刀痕。","霜凋萎疎葉，波衝枯朽根。","生处當如此，何用怨乾坤。"]', '诗', 'shi', '', NULL, '詩三百三首 一九一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb7a4cb-e732-412e-80f3-c5c5e035bfeb', '詩三百三首 一九二', '诗三百三首 一九二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余見僧繇性希奇，巧妙間生梁朝時。","道子飄然爲殊特，二公善繪手毫揮。","逞畫圖真意氣異，龍行鬼走神巍巍。","饒邈虛空寫塵跡，無因畫得誌公師。"]', '["余见僧繇性希奇，巧妙间生梁朝时。","道子飄然爲殊特，二公善繪手毫揮。","逞畫圖真意氣異，龙行鬼走神巍巍。","饒邈虛空寫塵跡，無因畫得誌公師。"]', '诗', 'shi', '', NULL, '詩三百三首 一九二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ff3dd3-b8f6-4c5b-b0fc-943ed02f1593', '詩三百三首 一九三', '诗三百三首 一九三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["久住寒山凡幾秋，獨吟歌曲絕無憂。","蓬扉不掩常幽寂，泉涌甘漿長自流。","石室地鑪砂鼎沸，松黃柏茗乳香甌。","飢餐一粒伽陀藥，心地調和倚石頭。"]', '["久住寒山凡幾秋，独吟歌曲絕無憂。","蓬扉不掩常幽寂，泉涌甘漿长自流。","石室地鑪砂鼎沸，松黄柏茗乳香甌。","飢餐一粒伽陀藥，心地調和倚石头。"]', '诗', 'shi', '', NULL, '詩三百三首 一九三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a54c07c-1dff-4532-8936-a8c60481ce4a', '詩三百三首 一九四', '诗三百三首 一九四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["丹丘迥聳與雲齊，空裏五峰遙望低。","鴈塔高排出青嶂，禪林古殿入虹蜺。","風搖松葉赤城秀，霧吐中巖仙路迷。","碧落千山萬仞現，藤蘿相接次連谿。"]', '["丹丘迥聳與云齊，空裏五峰遙望低。","鴈塔高排出青嶂，禪林古殿入虹蜺。","风搖松葉赤城秀，霧吐中巖仙路迷。","碧落千山万仞現，藤蘿相接次連谿。"]', '诗', 'shi', '', NULL, '詩三百三首 一九四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8147a4a-5251-4312-b4fb-a4c7790d6cda', '詩三百三首 一九五', '诗三百三首 一九五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["千生萬死凡幾生，生死來去轉迷情。","不識心中無價寶，猶似盲驢信脚行。"]', '["千生万死凡幾生，生死来去轉迷情。","不識心中無價寶，猶似盲驢信脚行。"]', '诗', 'shi', '', NULL, '詩三百三首 一九五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08df7232-10b7-4c43-952a-bcb8a82973a2', '詩三百三首 一九六', '诗三百三首 一九六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["老病殘年百有餘，面黃頭白好山居。","布裘擁質隨緣過，豈羨人間巧樣模。","心神用盡爲名利，百種貪婪進己軀。","浮生幻化如燈燼，塚內埋身是有無。"]', '["老病殘年百有餘，面黄头白好山居。","布裘擁質隨緣過，豈羨人间巧樣模。","心神用尽爲名利，百種貪婪進己軀。","浮生幻化如灯燼，塚內埋身是有無。"]', '诗', 'shi', '', NULL, '詩三百三首 一九六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea8c051-beed-4b47-aafd-38f0c2792357', '詩三百三首 一九七', '诗三百三首 一九七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世間何事最堪嗟，盡是三途造罪楂。","不學白雲巖下客，一條寒衲是生涯。","秋到任他林落葉，春來從你樹開花。","三界橫眠閑無事，明月清風是我家。"]', '["世间何事最堪嗟，尽是三途造罪楂。","不学白云巖下客，一條寒衲是生涯。","秋到任他林落葉，春来從你樹开花。","三界橫眠闲無事，明月清风是我家。"]', '诗', 'shi', '', NULL, '詩三百三首 一九七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1077fe-38b0-4a80-ac62-7a6a3e638e7b', '詩三百三首 一九八', '诗三百三首 一九八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昔年曾到大海遊，爲采摩尼誓懇求。","直到龍宮深密處，金關鎖斷主神愁。","龍王守護安耳裏，劒客星揮無處搜。","賈客却歸門內去，明珠元在我心頭。"]', '["昔年曾到大海游，爲采摩尼誓懇求。","直到龙宮深密处，金关鎖斷主神愁。","龙王守護安耳裏，劒客星揮無处搜。","賈客却归门內去，明珠元在我心头。"]', '诗', 'shi', '', NULL, '詩三百三首 一九八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deeb538f-2fec-43ff-af47-c78a9376836e', '詩三百三首 一九九', '诗三百三首 一九九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["衆星羅列夜明深，巖點孤燈月未沈。","圓滿光華不磨瑩，挂在青天是我心。"]', '["衆星羅列夜明深，巖点孤灯月未沈。","圓满光华不磨瑩，挂在青天是我心。"]', '诗', 'shi', '', NULL, '詩三百三首 一九九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02a7f72-f997-4e1d-bd89-65e2f199df57', '詩三百三首 二百', '诗三百三首 二百', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["千年石上古人蹤，萬丈巖前一點空。","明月照時常皎潔，不勞尋討問西東。"]', '["千年石上古人蹤，万丈巖前一点空。","明月照时常皎潔，不勞尋討问西东。"]', '诗', 'shi', '', NULL, '詩三百三首 二百 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec0ee3f-9402-4e7b-b692-57b38fa2621a', '詩三百三首 二百一', '诗三百三首 二百一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山頂上月輪孤，照見晴空一物無。","可貴天然無價寶，埋在五陰溺身軀。"]', '["寒山頂上月輪孤，照见晴空一物無。","可貴天然無價寶，埋在五陰溺身軀。"]', '诗', 'shi', '', NULL, '詩三百三首 二百一 寒山 shi');
